// Object->model binder instrumentation. PCSX2 shows every entity slot carrying
// geometry pointers at +0x80/+0x90; this runtime shows none, so count whether
// the binder at 0x206C98 and its caller at 0x206BD8 execute at all. The
// wrappers only increment, then run the generated body unchanged.
void sub_00206C98_0x206c98(uint8_t *rdram, R5900Context *ctx, PS2Runtime *runtime);
void FUN_00206bd8_0x206bd8(uint8_t *rdram, R5900Context *ctx, PS2Runtime *runtime);
void sub_00191688_0x191688(uint8_t *rdram, R5900Context *ctx, PS2Runtime *runtime);
void FUN_001da8f0_0x1da8f0(uint8_t *rdram, R5900Context *ctx, PS2Runtime *runtime);
void sub_00112030_0x112030(uint8_t *rdram, R5900Context *ctx, PS2Runtime *runtime);
void FUN_001d8620_0x1d8620(uint8_t *rdram, R5900Context *ctx, PS2Runtime *runtime);
void sub_0010A4F8_0x10a4f8(uint8_t *rdram, R5900Context *ctx, PS2Runtime *runtime);
void sub_00144A88_0x144a88(uint8_t *rdram, R5900Context *ctx, PS2Runtime *runtime);
void FUN_00144bb0_0x144bb0(uint8_t *rdram, R5900Context *ctx, PS2Runtime *runtime);
void FUN_00191900_0x191900(uint8_t *rdram, R5900Context *ctx, PS2Runtime *runtime);
void FUN_00191800_0x191800(uint8_t *rdram, R5900Context *ctx, PS2Runtime *runtime);
void sub_00182318_0x182318(uint8_t *rdram, R5900Context *ctx, PS2Runtime *runtime);

