std::atomic<uint64_t> g_mohBinderCallerHits{0};
// The two remaining candidates that store a register (not $sp-relative) to
// +0x80 of a base and also use the pool stride 0x2B0 as an offset.
std::atomic<uint64_t> g_moh191688Hits{0};
std::atomic<uint64_t> g_moh191900Hits{0};
// The layout coordinate chain 0x1DA8F0 -> 0x112030, documented in the movie-fullscreen
// fallback as "never runs" for the movie widget. Count it.
std::atomic<uint64_t> g_mohLayout1da8f0{0};
std::atomic<uint64_t> g_mohLayout112030{0};
std::atomic<uint64_t> g_mohLayout1d8620{0};
std::atomic<uint64_t> g_mohLayout10a4f8{0};
std::atomic<uint64_t> g_mohLayout144a88{0};
std::atomic<uint64_t> g_mohLayout144bb0{0};
std::atomic<uint64_t> g_moh191800Hits{0};
std::atomic<uint64_t> g_moh182318Hits{0};

static void mohCountBinder206c98(uint8_t *rdram, R5900Context *ctx, PS2Runtime *runtime)
{
    const uint64_t hit = g_mohBinderHits.fetch_add(1, std::memory_order_relaxed);
    const uint32_t a0In = getRegU32(ctx, 4);
    const uint32_t a1In = getRegU32(ctx, 5);

    // Census over every call, not just the first few: does any invocation ever
    // target the entity pool rather than a stack temporary?
    {
        static std::atomic<uint32_t> s_inPool{0}, s_stack{0}, s_other{0};
        static std::atomic<uint32_t> s_minA1{0xFFFFFFFFu}, s_maxA1{0};
        const bool poolHit = a1In >= 0x1D4DFC0u &&
                             a1In < 0x1D4DFC0u + 64u * 0x2B0u;
        if (poolHit) s_inPool.fetch_add(1, std::memory_order_relaxed);
        else if (a1In >= 0x01F00000u) s_stack.fetch_add(1, std::memory_order_relaxed);
        else s_other.fetch_add(1, std::memory_order_relaxed);
        uint32_t cur = s_minA1.load(std::memory_order_relaxed);
        while (a1In < cur && !s_minA1.compare_exchange_weak(cur, a1In)) {}
        cur = s_maxA1.load(std::memory_order_relaxed);
        while (a1In > cur && !s_maxA1.compare_exchange_weak(cur, a1In)) {}
        if ((hit % 100u) == 99u)
            std::cerr << "[MOH:binder-census-v1] calls=" << std::dec << (hit + 1)
                      << " inPool=" << s_inPool.load(std::memory_order_relaxed)
                      << " stackLike=" << s_stack.load(std::memory_order_relaxed)
                      << " other=" << s_other.load(std::memory_order_relaxed)
                      << std::hex << " a1Range=0x" << s_minA1.load(std::memory_order_relaxed)
                      << "..0x" << s_maxA1.load(std::memory_order_relaxed)
                      << std::dec << std::endl;
    }

    // $s4 cannot be read after the body returns (callee-saved and restored), so
    // find the write target by differencing guest RAM across the call. Only the
    // first few calls are instrumented; the window covers where the native
    // entity pool and its geometry live.
    constexpr uint32_t kDiffBase = 0x01C00000u;
    constexpr uint32_t kDiffSize = 0x00400000u;
    std::vector<uint8_t> before;
    const bool doDiff = false;
    if (doDiff)
        before.assign(rdram + kDiffBase, rdram + kDiffBase + kDiffSize);

    sub_00206C98_0x206c98(rdram, ctx, runtime);

    if (doDiff)
    {
        uint32_t shown = 0u;
        std::cerr << "[MOH:binder-diff-v1] hit=" << std::dec << hit << " changed=";
        for (uint32_t off = 0u; off < kDiffSize && shown < 12u; off += 4u)
        {
            uint32_t a = 0u, b = 0u;
            std::memcpy(&a, before.data() + off, 4);
            std::memcpy(&b, rdram + kDiffBase + off, 4);
            if (a != b)
            {
                std::cerr << (shown ? " " : "") << "0x" << std::hex
                          << (kDiffBase + off) << ":" << a << "->" << b;
                ++shown;
            }
        }
        std::cerr << std::dec << (shown ? "" : "(aucun)") << std::endl;
    }
    if (hit < 12u)
    {
        // s4 is the object base the two pointer stores use (0x206CF8 -> +0x90,
        // 0x206FFC -> +0x80). Report it so it can be matched against the pool
        // at 0x1D4DFC0 with stride 0x2B0.
        // 0x206CA8 does `daddu $s4, $a1, $zero`: the object base is a1, not a0.
        const uint32_t base = a1In;
        const bool inPool = base >= 0x1D4DFC0u &&
                            base < 0x1D4DFC0u + 64u * 0x2B0u &&
                            ((base - 0x1D4DFC0u) % 0x2B0u) == 0u;
        std::cerr << "[MOH:binder-base-v1] hit=" << std::dec << hit
                  << " a0=0x" << std::hex << a0In
                  << " a1(s4)=0x" << base << std::dec
                  << " inPool=" << (inPool ? 1 : 0) << std::endl;
    }
}

