static void mohCountLayout112030(uint8_t *rdram, R5900Context *ctx, PS2Runtime *runtime)
{
    const uint64_t k = g_mohLayout112030.fetch_add(1, std::memory_order_relaxed);
    // 0x112030 writes two floats at +0x14/+0x18 of a widget structure - the layout
    // rect. Record which widgets receive it, and the coordinates written, so the set
    // of laid-out widgets can be compared against the one drawing the movie.
    const uint32_t a0 = getRegU32(ctx, 4);
    const uint32_t a1 = getRegU32(ctx, 5);
    sub_00112030_0x112030(rdram, ctx, runtime);
    if (k < 16u)
        std::cerr << "[MOH:layout-rect-v1] k=" << std::dec << k
                  << " a0=0x" << std::hex << a0 << " a1=0x" << a1
                  << " v0=0x" << getRegU32(ctx, 2)
                  << " v1=0x" << getRegU32(ctx, 3) << std::dec
                  << " f12=" << ctx->f[12] << " f13=" << ctx->f[13]
                  << std::endl;
}

