    void logMohCompC0CdbOpenProtocolTraceV1(
        const char *stage,
        const uint8_t *rdram,
        const R5900Context *ctx,
        uint32_t entryPc,
        uint32_t handleHint,
        uint32_t entryHint,
        const std::string &pathHint,
        bool readTransaction = false)
    {
        static std::atomic<uint32_t> s_openLogs{0u};
        static std::atomic<uint32_t> s_readLogs{0u};
        std::atomic<uint32_t> &logCounter =
            readTransaction ? s_readLogs : s_openLogs;
        const uint32_t index =
            logCounter.fetch_add(1u, std::memory_order_relaxed);
        if (index >= 32u)
        {
            return;
        }

        const uint32_t table =
            readGuestU32OrZero(rdram, kMohAsyncTableBaseAddr);
        uint32_t handle = handleHint;
        uint32_t entry = entryHint;
        if (handle == 0u && entry != 0u)
        {
            handle = readGuestU32OrZero(rdram, entry + 0x00u);
        }
        if (handle == 0u)
        {
            handle =
                readTransaction
                    ? g_mohCompC0CdbReadHandleV1.load(
                          std::memory_order_acquire)
                    : g_mohCompC0CdbOpenHandleV1.load(
                          std::memory_order_acquire);
        }
        if (entry == 0u &&
            table != 0u &&
            (handle & kMohFrontendAsyncTypeMask) != 0u)
        {
            entry =
                table +
                (((handle >> 24u) & 0xFFu) *
                 kMohAsyncEntryStride);
        }
        if (entry == 0u)
        {
            entry =
                readTransaction
                    ? g_mohCompC0CdbReadEntryV1.load(
                          std::memory_order_acquire)
                    : g_mohCompC0CdbOpenEntryV1.load(
                          std::memory_order_acquire);
        }

        uint32_t slot =
            entry != 0u
                ? readGuestU32OrZero(rdram, entry + 0x24u)
                : 0u;
        if (slot == 0u)
        {
            slot =
                readTransaction
                    ? g_mohCompC0CdbReadSlotV1.load(
                          std::memory_order_acquire)
                    : g_mohCompC0CdbOpenSlotV1.load(
                          std::memory_order_acquire);
        }
        const uint32_t object =
            readTransaction
                ? g_mohCompC0CdbReadObjectV1.load(
                      std::memory_order_acquire)
                : 0u;
        std::string path =
            slot != 0u
                ? readGuestStringLimited(
                      rdram,
                      slot + 0x0Cu,
                      128u)
                : std::string{};
        if (path.empty())
        {
            path = pathHint;
        }

        constexpr uint32_t kManager = 0x0025FC80u;
        constexpr uint32_t kDvdManager = 0x0025AB10u;
        constexpr uint32_t kDvdDescriptor = 0x0025AB34u;
        const auto entryWord =
            [rdram, entry](uint32_t offset)
            {
                return entry != 0u
                           ? readGuestU32OrZero(
                                 rdram,
                                 entry + offset)
                           : 0u;
            };
        const auto slotWord =
            [rdram, slot](uint32_t offset)
            {
                return slot != 0u
                           ? readGuestU32OrZero(
                                 rdram,
                                 slot + offset)
                           : 0u;
        };
        std::cerr
            << (readTransaction
                    ? "[MOH:comp-c0-cdb-read-protocol-trace-v1]"
                    : "[MOH:comp-c0-cdb-open-protocol-trace-v1]")
            << " idx=" << std::dec << index
            << " stage=" << stage
            << " pc=0x" << std::hex << entryPc
            << " nextPc=0x" << (ctx ? ctx->pc : 0u)
            << " ra=0x" << (ctx ? getRegU32(ctx, 31) : 0u)
            << " sp=0x" << (ctx ? getRegU32(ctx, 29) : 0u)
            << " handle=0x" << handle
            << " type=0x" << (handle & kMohFrontendAsyncTypeMask)
            << " table=0x" << table
            << " entry=0x" << entry
            << " status=0x" << entryWord(0x08u)
            << " operation=0x" << entryWord(0x10u)
            << " context=0x" << entryWord(0x14u)
            << " object=0x" << object
            << " offset=0x" << entryWord(0x18u)
            << " chunk=0x" << entryWord(0x1Cu)
            << " destination=0x" << entryWord(0x20u)
            << " slot=0x" << slot
            << " callback=0x" << entryWord(0x28u)
            << " startFn=0x" << entryWord(0x2Cu)
            << " slotState=0x" << slotWord(0x00u)
            << " slotSize=0x" << slotWord(0x04u)
            << " slotOffset=0x" << slotWord(0x08u)
            << " managerCurrent=0x"
            << readGuestU32OrZero(rdram, kManager + 0x20u)
            << " managerQueue=0x"
            << readGuestU32OrZero(rdram, kManager + 0x2Cu)
            << " managerDepth=0x"
            << readGuestU32OrZero(rdram, kManager + 0x10u)
            << " managerCount=0x"
            << readGuestU32OrZero(rdram, kManager + 0x0Cu)
            << " v0=0x" << (ctx ? getRegU32(ctx, 2) : 0u)
            << " a0=0x" << (ctx ? getRegU32(ctx, 4) : 0u)
            << " s0=0x" << (ctx ? getRegU32(ctx, 16) : 0u)
            << " s1=0x" << (ctx ? getRegU32(ctx, 17) : 0u)
            << " s2=0x" << (ctx ? getRegU32(ctx, 18) : 0u)
            << " s3=0x" << (ctx ? getRegU32(ctx, 19) : 0u)
            << " s4=0x" << (ctx ? getRegU32(ctx, 20) : 0u)
            << " path='" << path << "'"
            << " entryWords=";
        if (entry != 0u)
        {
            logMohGuestWords(rdram, entry, 12u);
        }
        else
        {
            std::cerr << "()";
        }
        std::cerr << " slotWords=";
        if (slot != 0u)
        {
            logMohGuestWords(rdram, slot, 12u);
        }
        else
        {
            std::cerr << "()";
        }
        std::cerr << " objectWords=";
        if (readTransaction && object != 0u)
        {
            logMohGuestWords(rdram, object, 16u);
        }
        else
        {
            std::cerr << "()";
        }
        std::cerr << " managerWords=";
        logMohGuestWords(rdram, kManager, 16u);
        std::cerr << " dvdManagerWords=";
        logMohGuestWords(rdram, kDvdManager, 20u);
        std::cerr << " dvdDescriptorWords=";
        logMohGuestWords(rdram, kDvdDescriptor, 12u);
        std::cerr << std::dec << std::endl;
    }

