            ctx->vu0_vf[12] = _mm_loadu_ps(axisX.data());
            ctx->vu0_vf[13] = _mm_loadu_ps(axisY.data());
            ctx->vu0_vf[14] = _mm_loadu_ps(axisZ.data());
