        std::cerr << " managerWords=";
        logMohGuestWords(rdram, kManagerBase, 12u);
        std::cerr << " dvdManagerWords=";
        logMohGuestWords(rdram, kC0DvdManagerBase, 20u);
        std::cerr << " dvdDescriptorWords=";
