    void mohSoundPacket204720Trace(uint8_t *rdram, R5900Context *ctx, PS2Runtime *runtime)
    {
        if (!ctx)
        {
            return;
        }

        const uint32_t slot = getRegU32(ctx, 4);
        const uint32_t record = getRegU32(ctx, 5);
        const uint32_t soundObj =
            slot < 10u ? readGuestU32OrZero(rdram, 0x00260978u + slot * 4u) : 0u;

        static std::atomic<uint32_t> s_logCount{0u};
        const uint32_t index = s_logCount.fetch_add(1u, std::memory_order_relaxed);
        if (index < 8u)
        {
            std::cerr << "[MOH:sound-packet-dispatch]"
                      << " idx=" << std::dec << index
                      << " slot=" << slot
                      << " soundObj=0x" << std::hex << soundObj
                      << " stream=0x" << readGuestU32OrZero(rdram, soundObj + 0x00u)
                      << " record=0x" << record
                      << " tag=0x" << readGuestU32OrZero(rdram, record + 0x00u)
                      << std::dec << std::endl;
        }

        // TEMP menu-SFX probe: fresh bounded log once the menu is reached,
        // with record words (movie phase exhausts the main cap).
        if (g_mohMenuMusicGuestHandle.load(std::memory_order_acquire) != 0u)
        {
            static std::atomic<uint32_t> s_menuLog{0u};
            const uint32_t menuIdx =
                s_menuLog.fetch_add(1u, std::memory_order_relaxed);
            if (menuIdx < 24u)
            {
                std::cerr << "[MOH:menu-sfx-probe-v1] fn=204720"
                          << " idx=" << std::dec << menuIdx
                          << " slot=" << slot
                          << " soundObj=0x" << std::hex << soundObj
                          << " record=0x" << record
                          << " ra=0x" << getRegU32(ctx, 31)
                          << " recordWords=";
                logMohGuestWords(rdram, record, 12u);
                std::cerr << std::dec << std::endl;
            }
        }

        if (g_mohOriginalSoundPacket204720 &&
            g_mohOriginalSoundPacket204720 != &mohSoundPacket204720Trace)
        {
            g_mohOriginalSoundPacket204720(rdram, ctx, runtime);
        }
        else
        {
            ctx->pc = getRegU32(ctx, 31);
        }

        mohMovieAudioBridge().pump();
    }

