    void mohStreamAvail1f16d8Trace(uint8_t *rdram, R5900Context *ctx, PS2Runtime *runtime)
    {
        const uint32_t entryPc = ctx ? ctx->pc : 0u;
        const uint32_t a0 = getRegU32(ctx, 4);
        const uint32_t ra = getRegU32(ctx, 31);
        const uint32_t globalQueueBefore = readGuestU32OrZero(rdram, 0x00256900u);

        if (ra == 0x001E34A8u || a0 == globalQueueBefore)
        {
            (void)completeMohMovieOpenAsync(rdram, ctx, runtime, a0);
            (void)completeMohMovieStreamAsync(rdram, ctx, runtime, a0);
        }

        if (g_mohOriginalStreamAvail1f16d8 && g_mohOriginalStreamAvail1f16d8 != &mohStreamAvail1f16d8Trace)
        {
            g_mohOriginalStreamAvail1f16d8(rdram, ctx, runtime);
        }
        else if (ctx)
        {
            ctx->pc = ra;
        }

        const uint32_t ret = ctx ? getRegU32(ctx, 2) : 0u;
        const uint32_t globalQueue = readGuestU32OrZero(rdram, 0x00256900u);
        const bool movieWaitCall = ra == 0x001E34A8u || a0 == globalQueue || ret < 0x00064000u;

        static std::atomic<uint32_t> s_log{0u};
        const uint32_t idx = movieWaitCall ? s_log.fetch_add(1u, std::memory_order_relaxed) : UINT32_MAX;
        if (!movieWaitCall || idx >= 128u)
        {
            return;
        }

        const uint32_t header = readGuestU32OrZero(rdram, a0 + 0x00u);
        const uint32_t signature = readGuestU32OrZero(rdram, header + 0x00u);
        const uint32_t obj08 = readGuestU32OrZero(rdram, a0 + 0x08u);
        const uint32_t obj10 = readGuestU32OrZero(rdram, a0 + 0x10u);
        const uint32_t obj20 = readGuestU32OrZero(rdram, a0 + 0x20u);
        const uint32_t obj24 = readGuestU32OrZero(rdram, a0 + 0x24u);
        const uint32_t obj28 = readGuestU32OrZero(rdram, a0 + 0x28u);
        const uint32_t obj2c = readGuestU32OrZero(rdram, a0 + 0x2Cu);
        const uint32_t obj34 = readGuestU32OrZero(rdram, a0 + 0x34u);
        const uint32_t obj4c = readGuestU32OrZero(rdram, a0 + 0x4Cu);
        const uint32_t obj50 = readGuestU32OrZero(rdram, a0 + 0x50u);
        const uint32_t obj54 = readGuestU32OrZero(rdram, a0 + 0x54u);
        const uint32_t obj58 = readGuestU32OrZero(rdram, a0 + 0x58u);
        const uint32_t obj5c = readGuestU32OrZero(rdram, a0 + 0x5Cu);
        const uint32_t obj60 = readGuestU32OrZero(rdram, a0 + 0x60u);
        const uint32_t obj64 = readGuestU32OrZero(rdram, a0 + 0x64u);
        const uint32_t header34 = readGuestU32OrZero(rdram, header + 0x34u);

        std::cerr << "[MOH:stream16d8]"
                  << " idx=" << std::dec << idx
                  << " pc=0x" << std::hex << entryPc
                  << " ra=0x" << ra
                  << " obj=0x" << a0
                  << " ret=0x" << ret
                  << " globalQueue=0x" << globalQueue
                  << " header=0x" << header
                  << " sig=0x" << signature
                  << " h34=0x" << header34
                  << " objWords=(+08=0x" << obj08
                  << ",+10=0x" << obj10
                  << ",+20=0x" << obj20
                  << ",+24=0x" << obj24
                  << ",+28=0x" << obj28
                  << ",+2c=0x" << obj2c
                  << ",+34=0x" << obj34
                  << ",+4c=0x" << obj4c
                  << ",+50=0x" << obj50
                  << ",+54=0x" << obj54
                  << ",+58=0x" << obj58
                  << ",+5c=0x" << obj5c
                  << ",+60=0x" << obj60
                  << ",+64=0x" << obj64 << ")"
                  << " globals";
        logMohWords(rdram, 0x00256900u, {0x00u, 0x04u, 0x08u, 0x0Cu, 0x10u});
        if (obj64 >= 0x00010000u && obj64 + 0x20u <= 0x02000000u)
        {
            std::cerr << " list64";
            logMohGuestWords(rdram, obj64, 8u);
        }
        std::cerr << std::dec << std::endl;
    }

    void logMohFrontendMethodState(const char *tag,
                                   const uint8_t *rdram,
                                   uint32_t method,
                                   uint32_t a0,
                                   uint32_t a1,
                                   uint32_t a2,
                                   uint32_t ra,
                                   uint32_t ret)
    {
        std::cerr << "[MOH:" << tag << "]"
                  << " method=0x" << std::hex << method
                  << " node=0x" << a0
                  << " out=0x" << a1
                  << " obj=0x" << a2
                  << " ra=0x" << ra
                  << " ret=0x" << ret
                  << " node";
        logMohWords(rdram, a0, {0x00u, 0x04u, 0x08u, 0x10u, 0x14u, 0x18u, 0x1Cu, 0x20u, 0x24u, 0x28u, 0x2Cu});
        std::cerr << " out";
        logMohWords(rdram, a1, {0x00u, 0x04u, 0x08u, 0x0Cu, 0x10u, 0x14u, 0x18u, 0x1Cu});
        std::cerr << " objw";
        logMohWords(rdram, a2, {0x00u, 0x04u, 0x08u, 0x0Cu, 0x10u, 0x14u, 0x18u, 0x1Cu,
                                0x20u, 0x24u, 0x28u, 0x2Cu, 0x30u, 0x34u, 0x38u, 0x3Cu,
                                0x40u, 0x44u, 0x48u, 0x4Cu, 0x50u});
        std::cerr << " objf";
        logMohFloats(rdram, a2, {0x20u, 0x24u, 0x28u, 0x2Cu, 0x30u, 0x34u, 0x38u, 0x3Cu,
                                 0x40u, 0x44u, 0x48u, 0x4Cu, 0x50u});
        std::cerr << std::dec << std::endl;
    }

    constexpr uint32_t kMohDisplayListDescAddr = 0x0023F930u;
    constexpr uint32_t kMohTargetXFixed = 1548u << 4u;
    constexpr uint32_t kMohTargetYFixed = 1903u << 4u;
    constexpr uint32_t kMohRenderMaxScanBytes = 0x20000u;
    constexpr std::array<uint32_t, 8> kMohRenderOutCursorOffsets = {
        0x00u, 0x04u, 0x08u, 0x0Cu, 0x10u, 0x14u, 0x18u, 0x1Cu};
    constexpr std::array<uint32_t, 12> kMohRenderDisplayListOffsets = {
        0x00u, 0x04u, 0x08u, 0x0Cu, 0x10u, 0x14u, 0x18u, 0x1Cu,
        0x20u, 0x24u, 0x28u, 0x2Cu};
    constexpr size_t kMohRenderCursorCount =
        kMohRenderOutCursorOffsets.size() + kMohRenderDisplayListOffsets.size();

    struct MohRenderTraceState
    {
        std::array<uint32_t, kMohRenderCursorCount> before{};
        uint32_t method = 0u;
        uint32_t node = 0u;
        uint32_t out = 0u;
        uint32_t obj = 0u;
        uint32_t ra = 0u;
    };

    struct MohRenderRangeSummary
    {
        uint32_t bytes = 0u;
        uint32_t gifTags = 0u;
        uint32_t xyzCount = 0u;
        uint32_t firstX = 0u;
        uint32_t firstY = 0u;
        uint32_t secondX = 0u;
        uint32_t secondY = 0u;
        uint32_t hitAddr = 0u;
        bool hitTarget = false;
    };

    thread_local MohRenderTraceState g_mohRenderTrace{};

    bool readGuestU64(const uint8_t *rdram, uint32_t addr, uint64_t &out)
    {
        const uint8_t *ptr = getConstMemPtr(rdram, addr);
        if (!ptr)
        {
            out = 0u;
            return false;
        }

        std::memcpy(&out, ptr, sizeof(out));
        return true;
    }

    void mohFrontendGsApply1a1b00Trace(uint8_t *rdram, R5900Context *ctx, PS2Runtime *runtime)
    {
        if (!ctx || !runtime || !g_mohOriginalGsApply1a1b00)
        {
            return;
        }

        constexpr uint32_t kFrontendFirstObject = 0x005A8200u;
        constexpr uint32_t kFrontendFirstObjectVtable = kFrontendFirstObject + 0x20u;
        constexpr uint32_t kFrontendElementType = 0x00332600u;
        constexpr uint32_t kFrontendElementVtable = 0x0031CDE8u;
        constexpr uint32_t kGsManagerGlobal = 0x0024ABACu;

        const uint32_t env = getRegU32(ctx, 4);
        const uint32_t ra = getRegU32(ctx, 31);
        const uint32_t manager = readGuestU32OrZero(rdram, kGsManagerGlobal);
        const uint32_t managerWhich = readGuestU32OrZero(rdram, manager + 0xF4u);
        const uint32_t managerFrame = readGuestU32OrZero(rdram, manager + 0xF8u);
        const uint32_t managerPending = readGuestU32OrZero(rdram, manager + 0xFCu);
        const uint32_t envWhich = readGuestU32OrZero(rdram, env + 0xF4u);
        uint64_t envDisp1 = 0u;
        uint64_t envDisp2 = 0u;
        (void)readGuestU64(rdram, env + 0x70u, envDisp1);
        (void)readGuestU64(rdram, env + 0x78u, envDisp2);

        const auto &gsBefore = runtime->memory().gs();
        const uint64_t oldDisp1 = gsBefore.dispfb1;
        const uint64_t oldDisp2 = gsBefore.dispfb2;

        g_mohOriginalGsApply1a1b00(rdram, ctx, runtime);

        // The 0x5a82xx region is reused while the movies are active.  The vtable
        // value alone therefore becomes true much too early and exhausts this
        // bounded trace before the real post-INTRO frontend exists.  Match the
        // complete first menu element signature observed both natively and in
        // PCSX2 before consuming a trace slot.
        if (managerFrame < 2500u ||
            readGuestU32OrZero(rdram, kFrontendFirstObject) != kFrontendElementType ||
            readGuestU32OrZero(rdram, kFrontendFirstObjectVtable) != kFrontendElementVtable)
        {
            return;
        }

        static std::atomic<uint32_t> s_logCount{0u};
        const uint32_t seq = s_logCount.fetch_add(1u, std::memory_order_relaxed);
        if (seq >= 96u)
        {
            return;
        }

        const auto &gsAfter = runtime->memory().gs();
        std::cerr << "[MOH:frontend-gs-swap] seq=" << std::dec << seq
                  << " env=0x" << std::hex << env
                  << " ra=0x" << ra
                  << " manager=0x" << manager
                  << " managerWhich=" << std::dec << managerWhich
                  << " envWhich=" << envWhich
                  << " frame=" << managerFrame
                  << " pending=" << managerPending
                  << " envFbp=(" << (envDisp1 & 0x1FFu)
                  << "," << (envDisp2 & 0x1FFu) << ")"
                  << " hostBefore=(" << (oldDisp1 & 0x1FFu)
                  << "," << (oldDisp2 & 0x1FFu) << ")"
                  << " hostAfter=(" << (gsAfter.dispfb1 & 0x1FFu)
                  << "," << (gsAfter.dispfb2 & 0x1FFu) << ")"
                  << " nextPc=0x" << std::hex << ctx->pc
                  << std::dec << std::endl;
    }

    uint32_t normalizeMohLinearAddr(uint32_t addr)
    {
        return addr & 0x1FFFFFFFu;
    }

    bool isMohPlausibleRenderCursor(uint32_t before, uint32_t after, uint32_t &start, uint32_t &end)
    {
        start = normalizeMohLinearAddr(before);
        end = normalizeMohLinearAddr(after);
        return end > start &&
               start >= 0x00100000u &&
               end <= 0x02000000u &&
               (end - start) <= kMohRenderMaxScanBytes;
    }

    bool looksLikeMohXyz2(uint64_t value, uint32_t &x, uint32_t &y)
    {
        x = static_cast<uint32_t>(value & 0xFFFFu);
        y = static_cast<uint32_t>((value >> 16u) & 0xFFFFu);
        return x >= 0x5000u && x <= 0xA000u &&
               y >= 0x6000u && y <= 0xA000u;
    }

    bool looksLikeMohGifTag(uint64_t tagQword0, uint64_t regsQword)
    {
        const uint32_t nloop = static_cast<uint32_t>(tagQword0 & 0x7FFFu);
        const uint32_t flg = static_cast<uint32_t>((tagQword0 >> 58u) & 0x3u);
        const uint32_t nreg = static_cast<uint32_t>((tagQword0 >> 60u) & 0xFu);
        return nloop != 0u && nloop <= 0x4000u &&
               flg <= 2u &&
               regsQword != 0u &&
               (nreg <= 0xFu);
    }

    MohRenderRangeSummary summarizeMohRenderRange(const uint8_t *rdram, uint32_t start, uint32_t end)
    {
        MohRenderRangeSummary summary{};
        summary.bytes = end - start;

        for (uint32_t p = start; p + sizeof(uint64_t) <= end; p += 4u)
        {
            uint64_t value = 0u;
            if (!readGuestU64(rdram, p, value))
            {
                continue;
            }

            uint32_t x = 0u;
            uint32_t y = 0u;
            if (looksLikeMohXyz2(value, x, y))
            {
                if (summary.xyzCount == 0u)
                {
                    summary.firstX = x >> 4u;
                    summary.firstY = y >> 4u;
                }
                else if (summary.xyzCount == 1u)
                {
                    summary.secondX = x >> 4u;
                    summary.secondY = y >> 4u;
                }
                ++summary.xyzCount;

                if (x == kMohTargetXFixed && y == kMohTargetYFixed)
                {
                    summary.hitTarget = true;
                    if (summary.hitAddr == 0u)
                    {
                        summary.hitAddr = p;
                    }
                }
            }

            if ((p & 0xFu) == 0u && p + 16u <= end)
            {
                uint64_t regs = 0u;
                if (readGuestU64(rdram, p + 8u, regs) && looksLikeMohGifTag(value, regs))
                {
                    ++summary.gifTags;
                }
            }
        }

        return summary;
    }

    bool isMohMenuDisplayListBuffer(uint32_t addr)
    {
        return addr == 0x00484100u || addr == 0x00505200u;
    }

    void logMohQwordsAround(const char *label, const uint8_t *rdram, uint32_t center);

    void logMohRenderSummary(const MohRenderRangeSummary &summary)
    {
        std::cerr << " bytes=0x" << std::hex << summary.bytes
                  << " gifTags=" << std::dec << summary.gifTags
                  << " xyz=" << summary.xyzCount
                  << " quads~=" << (summary.xyzCount / 2u)
                  << " first=(" << summary.firstX << "," << summary.firstY << ")"
                  << " second=(" << summary.secondX << "," << summary.secondY << ")"
                  << " hit1548_1903=" << (summary.hitTarget ? 1 : 0)
                  << " hitAddr=0x" << std::hex << summary.hitAddr;
    }

    MohRenderRangeSummary logMohMenuBufferState(const char *summaryLabel,
                                                const char *headLabel,
                                                const char *hitLabel,
                                                const uint8_t *rdram,
                                                uint32_t base,
                                                uint32_t scanBytes)
    {
        MohRenderRangeSummary summary{};
        if (base != 0u)
        {
            summary = summarizeMohRenderRange(rdram, base, std::min(base + scanBytes, 0x02000000u));
        }

        std::cerr << " " << summaryLabel;
        logMohRenderSummary(summary);
        std::cerr << " " << headLabel;
        logMohWords(rdram, base, {0x00u, 0x04u, 0x08u, 0x0Cu, 0x10u, 0x14u, 0x18u, 0x1Cu,
                                  0x20u, 0x24u, 0x28u, 0x2Cu, 0x30u, 0x34u, 0x38u, 0x3Cu,
                                  0x40u, 0x44u, 0x48u, 0x4Cu, 0x50u, 0x54u, 0x58u, 0x5Cu,
                                  0x60u, 0x64u, 0x68u, 0x6Cu, 0x70u, 0x74u, 0x78u, 0x7Cu});
        if (summary.hitAddr != 0u)
        {
            logMohQwordsAround(hitLabel, rdram, summary.hitAddr);
        }
        return summary;
    }

    void logMohQwordsAround(const char *label, const uint8_t *rdram, uint32_t center)
    {
        if (center == 0u)
        {
            return;
        }

        const uint32_t start = center >= 0x20u ? center - 0x20u : center;
        std::cerr << " " << label << "[";
        bool first = true;
        for (uint32_t addr = start; addr <= center + 0x20u; addr += 8u)
        {
            uint64_t value = 0u;
            if (!first)
            {
                std::cerr << ",";
            }
            first = false;
            std::cerr << "0x" << std::hex << addr << "=";
            if (readGuestU64(rdram, addr, value))
            {
                std::cerr << "0x" << value;
            }
            else
            {
                std::cerr << "?";
            }
        }
        std::cerr << "]";
    }

    void logMohRenderCursors(const char *label, const uint8_t *rdram, uint32_t base,
                             const std::array<uint32_t, 8> &offsets)
    {
        std::cerr << " " << label << "Cur[";
        for (size_t i = 0; i < offsets.size(); ++i)
        {
            if (i != 0u)
            {
                std::cerr << ",";
            }

            uint32_t value = 0u;
            std::cerr << "+" << std::hex << offsets[i] << "=";
            if (base != 0u && readGuestU32(rdram, base + offsets[i], value))
            {
                std::cerr << "0x" << value;
            }
            else
            {
                std::cerr << "?";
            }
        }
        std::cerr << "]";
    }

    void logMohRenderDisplayListCursors(const uint8_t *rdram)
    {
        std::cerr << " dlCur[";
        for (size_t i = 0; i < kMohRenderDisplayListOffsets.size(); ++i)
        {
            if (i != 0u)
            {
                std::cerr << ",";
            }

            uint32_t value = 0u;
            const uint32_t off = kMohRenderDisplayListOffsets[i];
            std::cerr << "+" << std::hex << off << "=";
            if (readGuestU32(rdram, kMohDisplayListDescAddr + off, value))
            {
                std::cerr << "0x" << value;
            }
            else
            {
                std::cerr << "?";
            }
        }
        std::cerr << "]";
    }

    void mohRenderScanBegin(const char *tag, uint32_t method, const uint8_t *rdram,
                            uint32_t a0, uint32_t a1, uint32_t a2, uint32_t ra)
    {
        g_mohRenderTrace = {};
        g_mohRenderTrace.method = method;
        g_mohRenderTrace.node = a0;
        g_mohRenderTrace.out = a1;
        g_mohRenderTrace.obj = a2;
        g_mohRenderTrace.ra = ra;

        size_t index = 0u;
        for (const uint32_t off : kMohRenderOutCursorOffsets)
        {
            (void)readGuestU32(rdram, a1 + off, g_mohRenderTrace.before[index++]);
        }
        for (const uint32_t off : kMohRenderDisplayListOffsets)
        {
            (void)readGuestU32(rdram, kMohDisplayListDescAddr + off, g_mohRenderTrace.before[index++]);
        }

        static std::atomic<uint32_t> s_enterLogCount{0u};
        const uint32_t logIndex = s_enterLogCount.fetch_add(1u, std::memory_order_relaxed);
        if (logIndex < 8u)
        {
            uint32_t vtbl = 0u;
            (void)readGuestU32(rdram, a0 + 0x20u, vtbl);
            std::cerr << "[MOH:rmethod:enter] " << tag
                      << " method=0x" << std::hex << method
                      << " node=0x" << a0
                      << " vtbl=0x" << vtbl
                      << " out=0x" << a1
                      << " obj=0x" << a2
                      << " ra=0x" << ra
                      << " node";
            logMohWords(rdram, a0, {0x00u, 0x04u, 0x08u, 0x0Cu, 0x10u, 0x14u,
                                    0x18u, 0x1Cu, 0x20u, 0x24u, 0x28u, 0x2Cu});
            std::cerr << " obj";
            logMohWords(rdram, a2, {0x00u, 0x04u, 0x08u, 0x0Cu, 0x10u, 0x14u,
                                    0x18u, 0x1Cu, 0x20u, 0x24u, 0x28u, 0x2Cu,
                                    0x30u, 0x34u, 0x38u, 0x3Cu, 0x40u, 0x44u,
                                    0x48u, 0x4Cu, 0x50u});
            logMohRenderCursors("out", rdram, a1, kMohRenderOutCursorOffsets);
            logMohRenderDisplayListCursors(rdram);
            std::cerr << std::dec << std::endl;
        }
    }

    void mohRenderScanEnd(const char *tag, uint32_t method, const uint8_t *rdram,
                          uint32_t a0, uint32_t a1, uint32_t a2, uint32_t retV0)
    {
        static std::atomic<uint32_t> s_scanCalls{0};
        if (s_scanCalls.fetch_add(1u, std::memory_order_relaxed) > 32u)
        {
            return;
        }

        bool loggedExit = false;
        uint32_t bestBytes = 0u;
        MohRenderRangeSummary bestSummary{};
        uint32_t bestBefore = 0u;
        uint32_t bestAfter = 0u;
        const char *bestSource = "";
        uint32_t bestOffset = 0u;

        auto considerRange = [&](const char *source, uint32_t offset, uint32_t before, uint32_t after)
        {
            uint32_t start = 0u;
            uint32_t end = 0u;
            if (!isMohPlausibleRenderCursor(before, after, start, end))
            {
                return;
            }

            const MohRenderRangeSummary summary = summarizeMohRenderRange(rdram, start, end);
            if (summary.hitTarget || summary.xyzCount != 0u || summary.gifTags != 0u || summary.bytes > bestBytes)
            {
                bestBytes = summary.bytes;
                bestSummary = summary;
                bestBefore = before;
                bestAfter = after;
                bestSource = source;
                bestOffset = offset;
            }

            static std::atomic<uint32_t> s_rangeLogCount{0u};
            const bool shouldLog = summary.hitTarget ||
                                   (summary.xyzCount != 0u && s_rangeLogCount.load(std::memory_order_relaxed) < 8u);
            if (shouldLog)
            {
                const uint32_t rangeLogIndex = s_rangeLogCount.fetch_add(1u, std::memory_order_relaxed);
                if (summary.hitTarget || rangeLogIndex < 8u)
                {
                    uint32_t vtbl = 0u;
                    (void)readGuestU32(rdram, a0 + 0x20u, vtbl);
                    std::cerr << "[MOH:rscan] " << tag
                              << " method=0x" << std::hex << method
                              << " source=" << source << "+0x" << offset
                              << " before=0x" << before
                              << " after=0x" << after
                              << " bytes=0x" << summary.bytes
                              << " gifTags=" << std::dec << summary.gifTags
                              << " xyz=" << summary.xyzCount
                              << " quads~=" << (summary.xyzCount / 2u)
                              << " first=(" << summary.firstX << "," << summary.firstY << ")"
                              << " second=(" << summary.secondX << "," << summary.secondY << ")"
                              << " hit1548_1903=" << (summary.hitTarget ? 1 : 0)
                              << " hitAddr=0x" << std::hex << summary.hitAddr
                              << " node=0x" << a0
                              << " vtbl=0x" << vtbl
                              << " out=0x" << a1
                              << " obj=0x" << a2
                              << " ret=0x" << retV0
                              << std::dec << std::endl;
                    if (summary.hitTarget)
                    {
                        std::cerr << "[MOH:rscan-hit-chain] " << tag
                                  << " method=0x" << std::hex << method
                                  << " chain=" << ::mohDispatchHistory()
                                  << std::dec << std::endl;
                    }
                }
            }
        };

        size_t index = 0u;
        for (const uint32_t off : kMohRenderOutCursorOffsets)
        {
            uint32_t after = 0u;
            (void)readGuestU32(rdram, a1 + off, after);
            considerRange("out", off, g_mohRenderTrace.before[index++], after);
        }
        for (const uint32_t off : kMohRenderDisplayListOffsets)
        {
            uint32_t after = 0u;
            (void)readGuestU32(rdram, kMohDisplayListDescAddr + off, after);
            considerRange("dl", off, g_mohRenderTrace.before[index++], after);
        }

        static std::atomic<uint32_t> s_exitLogCount{0u};
        const uint32_t exitLogIndex = s_exitLogCount.fetch_add(1u, std::memory_order_relaxed);
        if (bestSummary.hitTarget || exitLogIndex < 8u)
        {
            uint32_t vtbl = 0u;
            (void)readGuestU32(rdram, a0 + 0x20u, vtbl);
            std::cerr << "[MOH:rmethod:exit] " << tag
                      << " method=0x" << std::hex << method
                      << " node=0x" << a0
                      << " vtbl=0x" << vtbl
                      << " out=0x" << a1
                      << " obj=0x" << a2
                      << " ret=0x" << retV0
                      << " best=" << bestSource << "+0x" << bestOffset
                      << " before=0x" << bestBefore
                      << " after=0x" << bestAfter
                      << " bytes=0x" << bestSummary.bytes
                      << " gifTags=" << std::dec << bestSummary.gifTags
                      << " xyz=" << bestSummary.xyzCount
                      << " quads~=" << (bestSummary.xyzCount / 2u)
                      << " first=(" << bestSummary.firstX << "," << bestSummary.firstY << ")"
                      << " second=(" << bestSummary.secondX << "," << bestSummary.secondY << ")"
                      << " hit1548_1903=" << (bestSummary.hitTarget ? 1 : 0)
                      << " hitAddr=0x" << std::hex << bestSummary.hitAddr;
            logMohRenderCursors("out", rdram, a1, kMohRenderOutCursorOffsets);
            logMohRenderDisplayListCursors(rdram);
            std::cerr << std::dec << std::endl;
            loggedExit = true;
        }

        (void)loggedExit;
    }

    void mohGeometry1d6510FrameCapture(
        uint8_t *rdram,
        R5900Context *ctx,
        PS2Runtime *runtime)
    {
        struct MohGeometryCallRecord
        {
            uint32_t object = 0u;
            uint32_t cursor = 0u;
            std::array<uint32_t, 27u> words{};
        };

        const uint32_t object = getRegU32(ctx, 4);
        const uint32_t packetState = getRegU32(ctx, 5);
        const uint32_t packetBase =
            readGuestU32OrZero(rdram, packetState + 0x00u);
        const uint32_t packetLimit =
            readGuestU32OrZero(rdram, packetState + 0x04u);
        const uint32_t packetCursor =
            readGuestU32OrZero(rdram, packetState + 0x08u);
        const bool packetArena =
            packetState == 0x0023F958u &&
            (packetBase == 0x00484100u ||
             packetBase == 0x00505200u) &&
            packetLimit >= packetBase;

        static uint32_t s_frameBase = 0u;
        static uint32_t s_frameLimit = 0u;
        static std::vector<MohGeometryCallRecord> s_records;
        static bool s_dumped = false;

        if (packetArena &&
            (s_frameBase != packetBase ||
             s_frameLimit != packetLimit))
        {
            if (!s_dumped && s_records.size() >= 500u)
            {
                std::ofstream dump(
                    "/tmp/moh-recomp-1d6510-frame.csv",
                    std::ios::trunc);
                if (dump.is_open())
                {
                    dump << "object,cursor";
                    for (size_t i = 0u; i < s_records.front().words.size(); ++i)
                    {
                        dump << ",w" << std::hex << (i * 4u);
                    }
                    dump << '\n';
                    for (const auto &record : s_records)
                    {
                        dump << std::hex << record.object
                             << ',' << record.cursor;
                        for (const uint32_t word : record.words)
                        {
                            dump << ',' << word;
                        }
                        dump << '\n';
                    }
                }
                std::cerr
                    << "[MOH:geometry-frame-capture-v1]"
                    << " base=0x" << std::hex << s_frameBase
                    << " limit=0x" << s_frameLimit
                    << " calls=" << std::dec << s_records.size()
                    << " ok=" << (dump.good() ? 1 : 0)
                    << std::endl;
                s_dumped = true;
            }

            s_records.clear();
            s_frameBase = packetBase;
            s_frameLimit = packetLimit;
        }

        if (packetArena && !s_dumped)
        {
            MohGeometryCallRecord record{};
            record.object = object;
            record.cursor = packetCursor;
            for (size_t i = 0u; i < record.words.size(); ++i)
            {
                record.words[i] =
                    readGuestU32OrZero(
                        rdram,
                        object + static_cast<uint32_t>(i * 4u));
            }
            s_records.push_back(record);
        }

        if (g_mohOriginalGeometry1d6510 &&
            g_mohOriginalGeometry1d6510 != &mohGeometry1d6510FrameCapture)
        {
            g_mohOriginalGeometry1d6510(rdram, ctx, runtime);
        }
        else if (ctx)
        {
            ctx->pc = getRegU32(ctx, 31);
        }
    }

    void mohGeometryQueueBulk1d71d0Trace(
        uint8_t *rdram,
        R5900Context *ctx,
        PS2Runtime *runtime)
    {
        const uint32_t entryPc = ctx ? ctx->pc : 0u;
        const uint32_t collection = getRegU32(ctx, 5);
        const uint32_t records =
            readGuestU32OrZero(rdram, collection + 0x00u);
        const uint32_t count =
            readGuestU32OrZero(rdram, collection + 0x04u);
        const uint32_t ra = getRegU32(ctx, 31);

        uint32_t targetCount = 0u;
        uint32_t firstObject = 0u;
        uint32_t lastObject = 0u;
        uint32_t firstHead = 0u;
        uint32_t lastHead = 0u;
        uint32_t objectXor = 0u;
        const uint32_t scanCount = std::min(count, 1024u);
        for (uint32_t i = 0u; i < scanCount; ++i)
        {
            const uint32_t record = records + i * 0x20u;
            const uint32_t object =
                readGuestU32OrZero(rdram, record + 0x04u);
            const uint32_t vtable =
                readGuestU32OrZero(rdram, object + 0x20u);
            if (vtable != 0x00329FA0u)
            {
                continue;
            }

            if (targetCount == 0u)
            {
                firstObject = object;
                firstHead =
                    readGuestU32OrZero(rdram, object + 0x68u);
            }
            lastObject = object;
            lastHead =
                readGuestU32OrZero(rdram, object + 0x68u);
            objectXor ^= object;
            ++targetCount;
        }

        const bool interesting =
            count >= 32u &&
            count <= 1024u &&
            targetCount >= 32u;
        uint32_t traceIndex = UINT32_MAX;
        if (interesting)
        {
            static std::atomic<uint32_t> s_traceCount{0u};
            traceIndex =
                s_traceCount.fetch_add(1u, std::memory_order_relaxed);
            if (traceIndex < 32u)
            {
                std::cerr
                    << "[MOH:geometry-queue-writer-trace-v1]"
                    << " idx=" << std::dec << traceIndex
                    << " phase=before"
                    << " pc=0x" << std::hex << entryPc
                    << " ra=0x" << ra
                    << " collection=0x" << collection
                    << " records=0x" << records
                    << " count=" << std::dec << count
                    << " targetCount=" << targetCount
                    << " firstObject=0x" << std::hex << firstObject
                    << " lastObject=0x" << lastObject
                    << " firstHead=0x" << firstHead
                    << " lastHead=0x" << lastHead
                    << " objectXor=0x" << objectXor
                    << " packetBase=0x"
                    << readGuestU32OrZero(rdram, 0x0023F958u)
                    << " packetCursor=0x"
                    << readGuestU32OrZero(rdram, 0x0023F960u)
                    << " chain=" << ::mohDispatchHistory()
                    << std::dec << std::endl;
            }
        }

        if (g_mohOriginalGeometryQueueBulk1d71d0 &&
            g_mohOriginalGeometryQueueBulk1d71d0 !=
                &mohGeometryQueueBulk1d71d0Trace)
        {
            g_mohOriginalGeometryQueueBulk1d71d0(
                rdram,
                ctx,
                runtime);
        }
        else if (ctx)
        {
            ctx->pc = ra;
        }

        if (interesting && traceIndex < 32u)
        {
            std::cerr
                << "[MOH:geometry-queue-writer-trace-v1]"
                << " idx=" << std::dec << traceIndex
                << " phase=after"
                << " pc=0x" << std::hex << entryPc
                << " nextPc=0x" << (ctx ? ctx->pc : 0u)
                << " ra=0x" << ra
                << " firstObject=0x" << firstObject
                << " lastObject=0x" << lastObject
                << " firstHead=0x"
                << readGuestU32OrZero(
                       rdram,
                       firstObject + 0x68u)
                << " lastHead=0x"
                << readGuestU32OrZero(
                       rdram,
                       lastObject + 0x68u)
                << std::dec << std::endl;
        }
    }

