            uint32_t frame = 0u;
            uint32_t base = 0u;
            uint32_t limit = 0u;
            uint32_t lastCursor = 0u;
            uint32_t calls = 0u;
            uint32_t bytes = 0u;
            uint32_t unclassifiedCalls = 0u;
