    void mohLoad13d050Trace(uint8_t *rdram, R5900Context *ctx, PS2Runtime *runtime)
    {
        const uint32_t entryPc = ctx ? ctx->pc : 0u;
        const uint32_t a0 = getRegU32(ctx, 4);
        const uint32_t a1 = getRegU32(ctx, 5);
        const uint32_t a2 = getRegU32(ctx, 6);
        const uint32_t finalRa = mohSavedRaOrLive(rdram, ctx, entryPc, 0x0013D050u, 0x130u);
        const bool entryCall = entryPc == 0x0013D050u;
        const uint32_t namePtr = entryCall ? a0 : getRegU32(ctx, 16);
        const uint32_t outSlot = entryCall ? a1 : getRegU32(ctx, 17);
        const std::string name = readGuestStringLimited(rdram, namePtr, 96u);
        uint32_t outBefore = 0u;
        if (outSlot != 0u)
        {
            (void)readGuestU32(rdram, outSlot, outBefore);
        }

        if (g_mohOriginalLoad13d050 && g_mohOriginalLoad13d050 != &mohLoad13d050Trace)
        {
            g_mohOriginalLoad13d050(rdram, ctx, runtime);
        }
        else if (ctx)
        {
            ctx->pc = getRegU32(ctx, 31);
        }

        const uint32_t ret = ctx ? getRegU32(ctx, 2) : 0u;
        uint32_t w0 = 0u, w4 = 0u, w8 = 0u, w40 = 0u, w44 = 0u;
        (void)readGuestU32(rdram, ret + 0x00u, w0);
        (void)readGuestU32(rdram, ret + 0x04u, w4);
        (void)readGuestU32(rdram, ret + 0x08u, w8);
        (void)readGuestU32(rdram, ret + 0x40u, w40);
        (void)readGuestU32(rdram, ret + 0x44u, w44);
        uint32_t outAfter = 0u;
        if (outSlot != 0u)
        {
            (void)readGuestU32(rdram, outSlot, outAfter);
        }

        static std::atomic<uint32_t> s_log{0};
        const uint32_t idx = s_log.fetch_add(1u, std::memory_order_relaxed);
        const uint32_t nextPc = ctx ? ctx->pc : 0u;
        if (idx < 32u || isMohVfsInterestingName(name) || ret == 0u)
        {
            std::cerr << "[MOH:bumload]"
                      << " idx=" << std::dec << idx
                      << " phase=" << mohTracePhase(nextPc, finalRa)
                      << " pc=0x" << std::hex << entryPc
                      << " finalRa=0x" << finalRa
                      << " a0=0x" << a0
                      << " a1=0x" << a1
                      << " a2=0x" << a2
                      << " namePtr=0x" << namePtr
                      << " name='" << name << "'"
                      << " outSlot=0x" << outSlot
                      << " outBefore=0x" << outBefore
                      << " ret=0x" << ret
                      << " nextPc=0x" << nextPc
                      << " outAfter=0x" << outAfter
                      << " count(u16[ret])=" << std::dec << (w0 & 0xFFFFu)
                      << " w0=0x" << std::hex << w0 << " w4=0x" << w4 << " w8=0x" << w8
                      << " w40=0x" << w40 << " w44=0x" << w44
                      << " retWords=";
            logMohGuestWords(rdram, ret, 24u);
            std::cerr << std::dec << std::endl;
        }
    }

    void mohArchiveLookup13d0d0Trace(
        uint8_t *rdram,
        R5900Context *ctx,
        PS2Runtime *runtime)
    {
        const uint32_t entryPc = ctx ? ctx->pc : 0u;
        const bool entryCall = entryPc == 0x0013D0D0u;

        static thread_local bool s_active = false;
        static thread_local uint32_t s_root = 0u;
        static thread_local uint32_t s_namePtr = 0u;
        static thread_local uint32_t s_out = 0u;
        static thread_local uint32_t s_finalRa = 0u;
        static thread_local std::string s_name;

        if (entryCall)
        {
            s_root = getRegU32(ctx, 4);
            s_namePtr = getRegU32(ctx, 5);
            s_out = getRegU32(ctx, 6);
            s_finalRa = getRegU32(ctx, 31);
            s_name = readGuestStringLimited(rdram, s_namePtr, 96u);
            s_active =
                g_mohLevelViv6_1Active.load(std::memory_order_acquire) &&
                isMohExactLevelViv6_1SceneConstructionPath(s_name);
        }

        const uint32_t nativeResultBefore = getRegU32(ctx, 2);
        const uint32_t rootGlobal =
            readGuestU32OrZero(rdram, kMohShellVivObjectPtrAddr);
        const uint32_t rootSize =
            readGuestU32OrZero(rdram, kMohShellVivObjectSizeAddr);
        MohBigfMember member{};
        const bool memberResolved =
            s_active && resolveMohLevelViv6_1Member(s_name, member);
        const uint32_t expectedPtr =
            memberResolved ? s_root + member.offset : 0u;
        const uint32_t outBefore = readGuestU32OrZero(rdram, s_out);

        static std::atomic<uint32_t> s_trace{0u};
        if (entryCall && s_active)
        {
            const uint32_t idx =
                s_trace.fetch_add(1u, std::memory_order_relaxed);
            if (idx < 32u)
            {
                std::cerr
                    << "[MOH:level-scene-direct-lookup-trace-v1]"
                    << " idx=" << std::dec << idx
                    << " stage=entry"
                    << " pc=0x" << std::hex << entryPc
                    << " ra=0x" << s_finalRa
                    << " root=0x" << s_root
                    << " rootGlobal=0x" << rootGlobal
                    << " rootSize=0x" << rootSize
                    << " namePtr=0x" << s_namePtr
                    << " name='" << s_name << "'"
                    << " out=0x" << s_out
                    << " outBefore=0x" << outBefore
                    << " memberOffset=0x" << member.offset
                    << " memberSize=0x" << member.size
                    << " expectedPtr=0x" << expectedPtr
                    << std::dec
                    << " memberResolved=" << (memberResolved ? 1 : 0)
                    << " rootWords=";
                logMohGuestWords(rdram, s_root, 8u);
                std::cerr << std::dec << std::endl;
            }
        }

        if (g_mohOriginalArchiveLookup13d0d0 &&
            g_mohOriginalArchiveLookup13d0d0 !=
                &mohArchiveLookup13d0d0Trace)
        {
            g_mohOriginalArchiveLookup13d0d0(rdram, ctx, runtime);
        }
        else if (ctx)
        {
            ctx->pc = getRegU32(ctx, 31);
        }

        const uint32_t nextPc = ctx ? ctx->pc : 0u;
        const uint32_t ret = getRegU32(ctx, 2);
        if (s_active && s_finalRa != 0u && nextPc == s_finalRa)
        {
            const uint32_t idx =
                s_trace.fetch_add(1u, std::memory_order_relaxed);
            if (idx < 32u)
            {
                std::cerr
                    << "[MOH:level-scene-direct-lookup-trace-v1]"
                    << " idx=" << std::dec << idx
                    << " stage=final"
                    << " pc=0x" << std::hex << entryPc
                    << " finalRa=0x" << s_finalRa
                    << " nativeResultBefore=0x" << nativeResultBefore
                    << " ret=0x" << ret
                    << " nextPc=0x" << nextPc
                    << " root=0x" << s_root
                    << " rootGlobal=0x" << rootGlobal
                    << " rootSize=0x" << rootSize
                    << " name='" << s_name << "'"
                    << " out=0x" << s_out
                    << " outAfter=0x"
                    << readGuestU32OrZero(rdram, s_out)
                    << " memberOffset=0x" << member.offset
                    << " memberSize=0x" << member.size
                    << " expectedPtr=0x" << expectedPtr
                    << std::dec
                    << " memberResolved=" << (memberResolved ? 1 : 0)
                    << " retWords=";
                logMohGuestWords(rdram, ret, 8u);
                logMohVfsManagerState(rdram, "mgr");
                std::cerr << std::dec << std::endl;
            }
            s_active = false;
        }
    }

    const char *mohVfsCallerName(uint32_t ra)
    {
        switch (ra)
        {
        case 0x001F1958u:
            return "openHandler1f1930";
        case 0x001F1A68u:
            return "parseBum1f1a38";
        case 0x001F1BC4u:
            return "vfs1f1b90";
        case 0x001F1D74u:
            return "vfs1f1d6c";
        case 0x001F2018u:
            return "vfs1f2010";
        default:
            return "other";
        }
    }

    bool isMohVfsSizeInteresting(uint32_t ra, std::string_view path)
    {
        return isMohVfsInterestingName(path) ||
               ra == 0x001F1958u ||
               ra == 0x001F1A68u ||
               ra == 0x001F1BC4u ||
               ra == 0x001F1D74u ||
               ra == 0x001F2018u;
    }

    void mohVfsSize1f2558Trace(uint8_t *rdram, R5900Context *ctx, PS2Runtime *runtime)
    {
        mohHeapCanaryCheck(rdram, ctx, "vfs2558");
        const uint32_t entryPc = ctx ? ctx->pc : 0u;
        const uint32_t a0 = getRegU32(ctx, 4);
        const uint32_t a1 = getRegU32(ctx, 5);
        const uint32_t a2 = getRegU32(ctx, 6);
        const uint32_t a3 = getRegU32(ctx, 7);
        const uint32_t liveRa = getRegU32(ctx, 31);
        const uint32_t finalRa = mohSavedRaOrLive(rdram, ctx, entryPc, 0x001F2558u, 0x30u);
        const bool entryCall = entryPc == 0x001F2558u;
        const uint32_t outRecord = entryCall ? a3 : getRegU32(ctx, 17);
        const uint32_t resumeHandle = entryPc == 0x001F257Cu ? getRegU32(ctx, 2) :
                                      (entryCall ? 0u : getRegU32(ctx, 16));

        MohVfsHandleSnapshot resumeSnapshot{};
        const bool resumeSnapshotValid =
            resumeHandle != 0u &&
            readMohVfsHandleSnapshot(
                rdram,
                resumeHandle,
                resumeSnapshot);
        std::string path = entryCall ? readGuestStringLimited(rdram, a0, 96u) : std::string{};
        if (path.empty() && resumeSnapshotValid)
        {
            path = resumeSnapshot.path;
        }

        const bool interesting = isMohVfsSizeInteresting(finalRa, path) ||
                                 (resumeHandle != 0u && isMohVfsInterestingHandle(rdram, resumeHandle));
        uint32_t outBefore = 0u;
        uint32_t rec8Before = 0u;
        uint32_t recCBefore = 0u;
        (void)readGuestU32(rdram, outRecord + 0x00u, outBefore);
        (void)readGuestU32(rdram, outRecord + 0x08u, rec8Before);
        (void)readGuestU32(rdram, outRecord + 0x0Cu, recCBefore);

        // A resumed open may yield again after 1f257c and clear its async
        // entry before this wrapper is re-entered at 1f25a8. Preserve the
        // completed type-2 transaction while every native field is live.
        constexpr uint32_t kLiveResumeTrackManager = 0x0025FC80u;
        const uint32_t liveResumeSlotPool =
            readGuestU32OrZero(
                rdram,
                kMohVfsFileSlotPoolBaseAddr);
        const bool liveGenericLevelBankPath =
            isMohLevel6_1AudioBankPath(path) &&
            !isMohExactLevel6_1MovBankPath(path) &&
            !isMohExactLevel6_1GunBankPath(path) &&
            !isMohExactLevel6_1ImpBankPath(path);
        const bool liveResumeEntryExact =
            resumeSnapshotValid &&
            resumeSnapshot.handle == resumeHandle &&
            (resumeHandle & kMohFrontendAsyncTypeMask) ==
                kMohFrontendFollowupAsyncTypeBits &&
            resumeSnapshot.entryWords[0] == resumeHandle &&
            resumeSnapshot.entryWords[1] == 0u &&
            resumeSnapshot.entryWords[2] == 1u &&
            resumeSnapshot.entryWords[3] == 0u &&
            resumeSnapshot.entryWords[4] == 0x64u &&
            resumeSnapshot.entryWords[5] == 0u &&
            resumeSnapshot.entryWords[6] == 1u &&
            resumeSnapshot.entryWords[7] == 0u &&
            resumeSnapshot.entryWords[8] == 0u &&
            resumeSnapshot.entryWords[9] == resumeSnapshot.slotAddr &&
            resumeSnapshot.entryWords[10] == 0u &&
            resumeSnapshot.entryWords[11] == 0u;
        const bool liveResumeSlotExact =
            liveResumeEntryExact &&
            resumeSnapshot.slotAddr != 0u &&
            isMohVfsFileSlot(rdram, resumeSnapshot.slotAddr) &&
            (resumeSnapshot.slotWords[0] >> 24u) == 1u &&
            resumeSnapshot.slotWords[1] != 0u &&
            resumeSnapshot.slotWords[2] == 0u &&
            resumeSnapshot.path == path &&
            liveGenericLevelBankPath;
        const bool liveResumeManagerExact =
            readGuestU32OrZero(
                rdram,
                kLiveResumeTrackManager + 0x00u) == 0x20u &&
            readGuestU32OrZero(
                rdram,
                kLiveResumeTrackManager + 0x04u) == 0x10u &&
            readGuestU32OrZero(
                rdram,
                kLiveResumeTrackManager + 0x08u) == 0x64u &&
            readGuestU32OrZero(
                rdram,
                kLiveResumeTrackManager + 0x0Cu) != 0u &&
            readGuestU32OrZero(
                rdram,
                kLiveResumeTrackManager + 0x10u) == 0u &&
            readGuestU32OrZero(
                rdram,
                kLiveResumeTrackManager + 0x14u) == 0x0Fu &&
            readGuestU32OrZero(
                rdram,
                kLiveResumeTrackManager + 0x18u) == 0u &&
            readGuestU32OrZero(
                rdram,
                kLiveResumeTrackManager + 0x1Cu) == 0u &&
            readGuestU32OrZero(
                rdram,
                kLiveResumeTrackManager + 0x20u) == 0u &&
            readGuestU32OrZero(
                rdram,
                kLiveResumeTrackManager + 0x24u) ==
                resumeSnapshot.tableBase &&
            liveResumeSlotPool != 0u &&
            readGuestU32OrZero(
                rdram,
                kLiveResumeTrackManager + 0x28u) ==
                liveResumeSlotPool &&
            readGuestU32OrZero(
                rdram,
                kLiveResumeTrackManager + 0x2Cu) == 0u;
        std::filesystem::path liveResumeHostPath;
        std::error_code liveResumeHostError;
        const bool liveResumeHostResolved =
            liveResumeSlotExact &&
            resolveMohHostFilePath(path, liveResumeHostPath);
        const uint64_t liveResumeHostSize =
            liveResumeHostResolved
                ? std::filesystem::file_size(
                      liveResumeHostPath,
                      liveResumeHostError)
                : 0u;
        const bool liveResumeHostExact =
            liveResumeHostResolved &&
            !liveResumeHostError &&
            liveResumeHostSize == resumeSnapshot.slotWords[1];
        const bool liveGenericBankOpenExact =
            g_mohLevelViv6_1Active.load(
                std::memory_order_acquire) &&
            entryPc == 0x001F257Cu &&
            finalRa == 0x001F1A68u &&
            liveResumeSlotExact &&
            liveResumeManagerExact &&
            liveResumeHostExact;
        const uint32_t compC0CdbTrackedHandle =
            g_mohCompC0CdbOpenHandleV1.load(
                std::memory_order_acquire);
        const uint32_t compC0CdbLiveHandle =
            resumeHandle != 0u
                ? resumeHandle
                : (entryCall ? 0u : getRegU32(ctx, 16));
        const bool traceCompC0CdbSizeOpen =
            isMohExactCompC0CdbPath(path) ||
            (compC0CdbTrackedHandle != 0u &&
             compC0CdbLiveHandle == compC0CdbTrackedHandle);
        if (traceCompC0CdbSizeOpen)
        {
            logMohCompC0CdbOpenProtocolTraceV1(
                "size-before-original",
                rdram,
                ctx,
                entryPc,
                compC0CdbLiveHandle,
                0u,
                path);
        }

        if (g_mohOriginalVfsSize1f2558 && g_mohOriginalVfsSize1f2558 != &mohVfsSize1f2558Trace)
        {
            g_mohOriginalVfsSize1f2558(rdram, ctx, runtime);
        }
        else if (ctx)
        {
            ctx->pc = getRegU32(ctx, 31);
        }

        if (traceCompC0CdbSizeOpen)
        {
            logMohCompC0CdbOpenProtocolTraceV1(
                "size-after-original",
                rdram,
                ctx,
                entryPc,
                compC0CdbLiveHandle,
                0u,
                path);
        }

        uint32_t outAfter = 0u;
        uint32_t rec8After = 0u;
        uint32_t recCAfter = 0u;
        (void)readGuestU32(rdram, outRecord + 0x00u, outAfter);
        (void)readGuestU32(rdram, outRecord + 0x08u, rec8After);
        (void)readGuestU32(rdram, outRecord + 0x0Cu, recCAfter);


        // MOH_LOADING_SSH_PARSER_SLOT_SIZE_V1
        //
        // Le premier open fournit correctement la taille du SSH, mais
        // parseBum1f1a38 crée ensuite un nouveau slot. Ce second slot
        // doit recevoir la même taille avant l'appel à vfsread25c8.
        const bool loadingSshPath =
            isMohLoadingSshPath(path);

        const bool parserFinalReturn =
            finalRa == 0x001F1A68u &&
            ctx != nullptr &&
            ctx->pc == finalRa;

        if (loadingSshPath &&
            parserFinalReturn)
        {
            const uint32_t slotState =
                readGuestU32OrZero(
                    rdram,
                    outAfter + 0x00u);

            const uint32_t oldSlotSize =
                readGuestU32OrZero(
                    rdram,
                    outAfter + 0x04u);

            const std::string slotPath =
                readGuestStringLimited(
                    rdram,
                    outAfter + 0x0Cu,
                    128u);
            const bool exactSlot =
                slotState == 1u &&
                isMohLoadingSshPath(slotPath) &&
                sameMohLoadingSshPath(
                    path,
                    slotPath);


            std::filesystem::path hostPath;

            const bool resolved =
                exactSlot &&
                resolveMohHostFilePath(
                    slotPath,
                    hostPath);

            std::error_code sizeError;
            uint64_t hostSize64 = 0u;

            if (resolved)
            {
                hostSize64 =
                    static_cast<uint64_t>(
                        std::filesystem::file_size(
                            hostPath,
                            sizeError));
            }

            const bool sizeValid =
                resolved &&
                !sizeError &&
                hostSize64 >= 8u &&
                hostSize64 <= 0xFFFFFFFFull;

            std::array<uint8_t, 8> header{};

            const bool headerRead =
                sizeValid &&
                readMohHostFileRange(
                    hostPath,
                    0u,
                    header.data(),
                    static_cast<uint32_t>(
                        header.size()));

            const uint32_t magic =
                static_cast<uint32_t>(header[0]) |
                (static_cast<uint32_t>(header[1]) << 8u) |
                (static_cast<uint32_t>(header[2]) << 16u) |
                (static_cast<uint32_t>(header[3]) << 24u);

            const uint32_t headerSize =
                static_cast<uint32_t>(header[4]) |
                (static_cast<uint32_t>(header[5]) << 8u) |
                (static_cast<uint32_t>(header[6]) << 16u) |
                (static_cast<uint32_t>(header[7]) << 24u);

            const uint32_t hostSize =
                sizeValid
                    ? static_cast<uint32_t>(hostSize64)
                    : 0u;

            const bool exactShps =
                headerRead &&
                magic == 0x53504853u &&
                headerSize == hostSize;

            bool sizeWritten = false;
            bool ready = false;

            if (exactShps &&
                oldSlotSize == 0u)
            {
                sizeWritten =
                    writeGuestU32(
                        rdram,
                        outAfter + 0x04u,
                        hostSize);

                ready = sizeWritten;
            }
            else if (exactShps &&
                     oldSlotSize == hostSize)
            {
                ready = true;
            }

            static uint32_t parserSlotLogs = 0u;

            if (parserSlotLogs < 16u)
            {
                std::cerr
                    << (ready
                            ? "[MOH:loading-ssh-parser-slot-ready]"
                            : "[MOH:loading-ssh-parser-slot-reject]")
                    << " pc=0x" << std::hex
                    << (ctx ? ctx->pc : 0u)
                    << " slot=0x" << outAfter
                    << " slotState=0x" << slotState
                    << " oldSize=0x" << oldSlotSize
                    << " hostSize=0x" << hostSize
                    << " headerSize=0x" << headerSize
                    << " magic=0x" << magic
                    << " path='" << path << "'"
                    << " slotPath='" << slotPath << "'"
                    << " host='" << hostPath.string() << "'"
                    << std::dec
                    << " exactSlot="
                    << (exactSlot ? 1 : 0)
                    << " resolved="
                    << (resolved ? 1 : 0)
                    << " headerRead="
                    << (headerRead ? 1 : 0)
                    << " sizeWritten="
                    << (sizeWritten ? 1 : 0)
                    << std::endl;

                ++parserSlotLogs;
            }
        }

        static std::atomic<uint32_t> s_log{0};
        const uint32_t idx = s_log.fetch_add(1u, std::memory_order_relaxed);
        const uint32_t ret = ctx ? getRegU32(ctx, 2) : 0u;
        const uint32_t nextPc = ctx ? ctx->pc : 0u;

        if (liveGenericBankOpenExact)
        {
            const uint32_t previousOpenHandle =
                g_mohLevelBankOpenHandleV1.load(
                    std::memory_order_acquire);
            const uint32_t previousWakeHandle =
                g_mohLevelBankReadWakeHandleV1.load(
                    std::memory_order_acquire);
            g_mohLevelBankOpenHandleV1.store(
                resumeHandle,
                std::memory_order_release);
            // Publish the reset last, so the read waiter observes a matched
            // new-bank pair even when the native continuation yielded.
            g_mohLevelBankReadWakeHandleV1.store(
                0u,
                std::memory_order_release);

            static std::atomic<uint32_t>
                sLiveResumeOpenTrackTraceCount{0u};
            const uint32_t trackTraceIndex =
                sLiveResumeOpenTrackTraceCount.fetch_add(
                    1u,
                    std::memory_order_relaxed);
            if (trackTraceIndex < 16u)
            {
                std::cerr
                    << "[MOH:level-bank-open-live-resume-track-v1]"
                    << " idx=" << std::dec << trackTraceIndex
                    << " pc=0x" << std::hex << entryPc
                    << " finalRa=0x" << finalRa
                    << " nextPc=0x" << nextPc
                    << " handle=0x" << resumeHandle
                    << " previousOpenHandle=0x"
                    << previousOpenHandle
                    << " previousWakeHandle=0x"
                    << previousWakeHandle
                    << " entry=0x" << resumeSnapshot.entryAddr
                    << " slot=0x" << resumeSnapshot.slotAddr
                    << " slotSize=0x"
                    << resumeSnapshot.slotWords[1]
                    << " managerCount=0x"
                    << readGuestU32OrZero(
                           rdram,
                           kLiveResumeTrackManager + 0x0Cu)
                    << " path='" << path << "'"
                    << " host='" << liveResumeHostPath.string() << "'"
                    << std::dec << std::endl;
            }
        }

        // A retried open can finish at the 1f257c resume point without
        // returning through the vfs4270 hook that normally records the audio
        // handle. Capture the still-live type-2 entry before the native resume
        // clears it, then publish the exact completed transaction here.
        constexpr uint32_t kResumeTrackManager = 0x0025FC80u;
        const bool genericLevelBankPath =
            isMohLevel6_1AudioBankPath(path) &&
            !isMohExactLevel6_1MovBankPath(path) &&
            !isMohExactLevel6_1GunBankPath(path) &&
            !isMohExactLevel6_1ImpBankPath(path);
        const uint32_t resumeTrackSlotPool =
            readGuestU32OrZero(
                rdram,
                kMohVfsFileSlotPoolBaseAddr);
        const bool resumeEntryExact =
            resumeSnapshotValid &&
            resumeSnapshot.handle == resumeHandle &&
            (resumeHandle & kMohFrontendAsyncTypeMask) ==
                kMohFrontendFollowupAsyncTypeBits &&
            resumeSnapshot.entryWords[0] == resumeHandle &&
            resumeSnapshot.entryWords[1] == 0u &&
            resumeSnapshot.entryWords[2] == 1u &&
            resumeSnapshot.entryWords[3] == 0u &&
            resumeSnapshot.entryWords[4] == 0x64u &&
            resumeSnapshot.entryWords[5] == 0u &&
            resumeSnapshot.entryWords[6] == 1u &&
            resumeSnapshot.entryWords[7] == 0u &&
            resumeSnapshot.entryWords[8] == 0u &&
            resumeSnapshot.entryWords[9] == resumeSnapshot.slotAddr &&
            resumeSnapshot.entryWords[10] == 0u &&
            resumeSnapshot.entryWords[11] == 0u;
        const bool resumeSlotExact =
            resumeEntryExact &&
            resumeSnapshot.slotAddr != 0u &&
            isMohVfsFileSlot(rdram, resumeSnapshot.slotAddr) &&
            (resumeSnapshot.slotWords[0] >> 24u) == 1u &&
            resumeSnapshot.slotWords[1] != 0u &&
            resumeSnapshot.slotWords[2] == 0u &&
            resumeSnapshot.path == path &&
            genericLevelBankPath;
        const bool resumeManagerExact =
            readGuestU32OrZero(rdram, kResumeTrackManager + 0x00u) ==
                0x20u &&
            readGuestU32OrZero(rdram, kResumeTrackManager + 0x04u) ==
                0x10u &&
            readGuestU32OrZero(rdram, kResumeTrackManager + 0x08u) ==
                0x64u &&
            readGuestU32OrZero(rdram, kResumeTrackManager + 0x0Cu) !=
                0u &&
            readGuestU32OrZero(rdram, kResumeTrackManager + 0x10u) ==
                0u &&
            readGuestU32OrZero(rdram, kResumeTrackManager + 0x14u) ==
                0x0Fu &&
            readGuestU32OrZero(rdram, kResumeTrackManager + 0x18u) ==
                0u &&
            readGuestU32OrZero(rdram, kResumeTrackManager + 0x1Cu) ==
                0u &&
            readGuestU32OrZero(rdram, kResumeTrackManager + 0x20u) ==
                0u &&
            readGuestU32OrZero(rdram, kResumeTrackManager + 0x24u) ==
                resumeSnapshot.tableBase &&
            resumeTrackSlotPool != 0u &&
            readGuestU32OrZero(rdram, kResumeTrackManager + 0x28u) ==
                resumeTrackSlotPool &&
            readGuestU32OrZero(rdram, kResumeTrackManager + 0x2Cu) ==
                0u;
        std::filesystem::path resumeHostPath;
        std::error_code resumeHostError;
        const bool resumeHostResolved =
            resumeSlotExact &&
            resolveMohHostFilePath(path, resumeHostPath);
        const uint64_t resumeHostSize =
            resumeHostResolved
                ? std::filesystem::file_size(
                      resumeHostPath,
                      resumeHostError)
                : 0u;
        const bool resumeHostExact =
            resumeHostResolved &&
            !resumeHostError &&
            resumeHostSize == resumeSnapshot.slotWords[1];
        const bool completedGenericBankOpen =
            g_mohLevelViv6_1Active.load(
                std::memory_order_acquire) &&
            !liveGenericBankOpenExact &&
            entryPc == 0x001F257Cu &&
            finalRa == 0x001F1A68u &&
            nextPc == finalRa &&
            ret == 1u &&
            outAfter == resumeSnapshot.slotAddr &&
            resumeSlotExact &&
            resumeManagerExact &&
            resumeHostExact;
        if (completedGenericBankOpen)
        {
            const uint32_t previousOpenHandle =
                g_mohLevelBankOpenHandleV1.load(
                    std::memory_order_acquire);
            const uint32_t previousWakeHandle =
                g_mohLevelBankReadWakeHandleV1.load(
                    std::memory_order_acquire);
            g_mohLevelBankOpenHandleV1.store(
                resumeHandle,
                std::memory_order_release);
            // Publish the reset last, so a waiter cannot pair a cleared wake
            // token with the preceding bank's open handle.
            g_mohLevelBankReadWakeHandleV1.store(
                0u,
                std::memory_order_release);

            static std::atomic<uint32_t>
                sResumeOpenTrackTraceCount{0u};
            const uint32_t trackTraceIndex =
                sResumeOpenTrackTraceCount.fetch_add(
                    1u,
                    std::memory_order_relaxed);
            if (trackTraceIndex < 16u)
            {
                std::cerr
                    << "[MOH:level-bank-open-resume-track-v1]"
                    << " idx=" << std::dec << trackTraceIndex
                    << " pc=0x" << std::hex << entryPc
                    << " finalRa=0x" << finalRa
                    << " handle=0x" << resumeHandle
                    << " previousOpenHandle=0x"
                    << previousOpenHandle
                    << " previousWakeHandle=0x"
                    << previousWakeHandle
                    << " entry=0x" << resumeSnapshot.entryAddr
                    << " slot=0x" << resumeSnapshot.slotAddr
                    << " slotSize=0x"
                    << resumeSnapshot.slotWords[1]
                    << " managerCount=0x"
                    << readGuestU32OrZero(
                           rdram,
                           kResumeTrackManager + 0x0Cu)
                    << " path='" << path << "'"
                    << " host='" << resumeHostPath.string() << "'"
                    << std::dec << std::endl;
            }
        }

        if ((interesting && idx < 256u) || (ret == 0u && isMohVfsInterestingName(path)))
        {
            std::cerr << "[MOH:vfs2558]"
                      << " idx=" << std::dec << idx
                      << " phase=" << mohTracePhase(nextPc, finalRa)
                      << " pc=0x" << std::hex << entryPc
                      << " caller=" << mohVfsCallerName(finalRa)
                      << " finalRa=0x" << finalRa
                      << " liveRa=0x" << liveRa
                      << " a0=0x" << a0
                      << " a1=0x" << a1
                      << " a2=0x" << a2
                      << " a3=0x" << a3
                      << " outRecord=0x" << outRecord
                      << " resumeHandle=0x" << resumeHandle
                      << " path='" << path << "'"
                      << " outBefore=0x" << outBefore
                      << " rec8Before=0x" << rec8Before
                      << " recCBefore=0x" << recCBefore
                      << " ret=0x" << ret
                      << " nextPc=0x" << nextPc
                      << " outAfter=0x" << outAfter
                      << " rec8After=0x" << rec8After
                      << " recCAfter=0x" << recCAfter;
            if (resumeHandle != 0u)
            {
                logMohVfsHandleSnapshot(rdram, resumeHandle, "resumeHandle");
            }
            if ((ret & kMohFrontendAsyncTypeMask) != 0u)
            {
                logMohVfsHandleSnapshot(rdram, ret, "retHandle");
            }
            logMohVfsManagerState(rdram, "mgr");
            std::cerr << std::dec << std::endl;
        }
    }

    void mohVfsRead1f25c8Trace(uint8_t *rdram, R5900Context *ctx, PS2Runtime *runtime)
    {
        mohHeapCanaryCheck(rdram, ctx, "vfs25c8");
        const uint32_t entryPc = ctx ? ctx->pc : 0u;
        const bool entryCall = entryPc == 0x001F25C8u;
        const uint32_t finalRa = mohSavedRaOrLive(rdram, ctx, entryPc, 0x001F25C8u, 0x0u);
        const uint32_t a0 = getRegU32(ctx, 4);
        const uint32_t a1 = getRegU32(ctx, 5);
        const uint32_t a2 = getRegU32(ctx, 6);
        const uint32_t a3 = getRegU32(ctx, 7);
        const uint32_t t0 = getRegU32(ctx, 8);
        const uint32_t t1 = getRegU32(ctx, 9);

        static uint32_t s_slot = 0u;
        static uint32_t s_dst = 0u;
        static uint32_t s_a1 = 0u;
        static uint32_t s_a3 = 0u;
        static uint32_t s_t0 = 0u;
        static uint32_t s_t1 = 0u;
        static std::string s_path;
        static std::array<uint32_t, 8> s_before{};

        uint32_t slot = s_slot;
        uint32_t dst = s_dst;
        uint32_t savedA1 = s_a1;
        uint32_t savedA3 = s_a3;
        uint32_t savedT0 = s_t0;
        uint32_t savedT1 = s_t1;
        std::string path = s_path;
        if (entryCall)
        {
            slot = a0;
            dst = a2;
            savedA1 = a1;
            savedA3 = a3;
            savedT0 = t0;
            savedT1 = t1;
            path = readGuestStringLimited(rdram, slot + 0x0Cu, 128u);
            s_slot = slot;
            s_dst = dst;
            s_a1 = savedA1;
            s_a3 = savedA3;
            s_t0 = savedT0;
            s_t1 = savedT1;
            s_path = path;
            for (size_t i = 0; i < s_before.size(); ++i)
            {
                s_before[i] = readGuestU32OrZero(rdram, dst + static_cast<uint32_t>(i * 4u));
            }
        }

        // MOH_LOADING_SSH_SYNC_READ_V1
        //
        // Le VFS guest retourne la taille demandée pour les loading SSH,
        // mais ne copie aucun octet dans la destination. Effectuer ici
        // la lecture hôte, uniquement après validation stricte du fichier.
        bool loadingSshReadHandled = false;
        bool levelFileReadHandled = false;
        bool levelArtReadHandled = false;
        bool levelCdbReadHandled = false;
        bool levelSceneResourceReadHandled = false;

        const bool loadingSshRequested =
            entryCall &&
            ctx != nullptr &&
            slot != 0u &&
            dst != 0u &&
            a1 == 0u &&
            a3 != 0u &&
            (
                isMohLoadingSshPath(path)
            );

        if (loadingSshRequested)
        {
            const uint32_t slotState =
                readGuestU32OrZero(
                    rdram,
                    slot + 0x00u);

            const uint32_t slotSize =
                readGuestU32OrZero(
                    rdram,
                    slot + 0x04u);

            const std::string slotPath =
                readGuestStringLimited(
                    rdram,
                    slot + 0x0Cu,
                    128u);
            const bool exactSlot =
                slotState == 1u &&
                isMohLoadingSshPath(slotPath) &&
                sameMohLoadingSshPath(
                    path,
                    slotPath);


            std::filesystem::path hostPath;

            const bool resolved =
                exactSlot &&
                resolveMohHostFilePath(
                    slotPath,
                    hostPath);

            std::error_code sizeError;
            uint64_t hostSize64 = 0u;

            if (resolved)
            {
                hostSize64 =
                    static_cast<uint64_t>(
                        std::filesystem::file_size(
                            hostPath,
                            sizeError));
            }

            const bool hostSizeValid =
                resolved &&
                !sizeError &&
                hostSize64 >= 8u &&
                hostSize64 <= 0xFFFFFFFFull;

            const uint32_t hostSize =
                hostSizeValid
                    ? static_cast<uint32_t>(hostSize64)
                    : 0u;

            std::array<uint8_t, 8> header{};

            const bool headerRead =
                hostSizeValid &&
                readMohHostFileRange(
                    hostPath,
                    0u,
                    header.data(),
                    static_cast<uint32_t>(
                        header.size()));

            const uint32_t magic =
                static_cast<uint32_t>(header[0]) |
                (static_cast<uint32_t>(header[1]) << 8u) |
                (static_cast<uint32_t>(header[2]) << 16u) |
                (static_cast<uint32_t>(header[3]) << 24u);

            const uint32_t headerSize =
                static_cast<uint32_t>(header[4]) |
                (static_cast<uint32_t>(header[5]) << 8u) |
                (static_cast<uint32_t>(header[6]) << 16u) |
                (static_cast<uint32_t>(header[7]) << 24u);

            const bool exactShps =
                headerRead &&
                magic == 0x53504853u &&
                headerSize == hostSize &&
                slotSize == hostSize &&
                a3 == hostSize;

            uint32_t dstOffset = 0u;
            bool dstScratch = false;

            const bool dstValid =
                exactShps &&
                ps2ResolveGuestPointer(
                    dst,
                    dstOffset,
                    dstScratch) &&
                !dstScratch &&
                dstOffset < PS2_RAM_SIZE &&
                a3 <= PS2_RAM_SIZE - dstOffset;

            uint8_t *dstPtr =
                dstValid
                    ? getMemPtr(rdram, dst)
                    : nullptr;

            const bool copied =
                dstPtr != nullptr &&
                readMohHostFileRange(
                    hostPath,
                    static_cast<uint64_t>(a1),
                    dstPtr,
                    a3);

            if (copied)
            {
                setReturnU32(ctx, a3);
                ctx->pc = finalRa;
                loadingSshReadHandled = true;
            }

            static uint32_t syncReadLogs = 0u;

            if (syncReadLogs < 16u)
            {
                std::cerr
                    << (loadingSshReadHandled
                            ? "[MOH:loading-ssh-read-sync-ready]"
                            : "[MOH:loading-ssh-read-sync-reject]")
                    << " slot=0x" << std::hex << slot
                    << " dst=0x" << dst
                    << " offset=0x" << a1
                    << " requested=0x" << a3
                    << " slotState=0x" << slotState
                    << " slotSize=0x" << slotSize
                    << " hostSize=0x" << hostSize
                    << " headerSize=0x" << headerSize
                    << " magic=0x" << magic
                    << " path='" << path << "'"
                    << " slotPath='" << slotPath << "'"
                    << " host='" << hostPath.string() << "'"
                    << std::dec
                    << " exactSlot="
                    << (exactSlot ? 1 : 0)
                    << " resolved="
                    << (resolved ? 1 : 0)
                    << " dstValid="
                    << (dstValid ? 1 : 0)
                    << " copied="
                    << (copied ? 1 : 0)
                    << std::endl;

                ++syncReadLogs;
            }
        }

        // MOH_LEVELFILE_SYNC_READ_V1
        //
        // levelfile.lfc is the first member of the active 6_1 LEVEL.VIV, not a
        // standalone host file. Complete only an exact, bounded member read.
        const std::string normalizedReadPath =
            mohLowerAscii(
                normalizeMohCdPath(path));

        const bool levelFileRequested =
            entryCall &&
            ctx != nullptr &&
            slot != 0u &&
            dst != 0u &&
            a3 != 0u &&
            normalizedReadPath ==
                "levelfile.lfc";

        if (levelFileRequested)
        {
            const uint32_t slotState =
                readGuestU32OrZero(
                    rdram,
                    slot + 0x00u);

            const uint32_t slotSize =
                readGuestU32OrZero(
                    rdram,
                    slot + 0x04u);

            const std::string slotPath =
                readGuestStringLimited(
                    rdram,
                    slot + 0x0Cu,
                    128u);

            const std::string normalizedSlotPath =
                mohLowerAscii(
                    normalizeMohCdPath(
                        slotPath));

            const bool exactSlot =
                slotState == 1u &&
                normalizedSlotPath ==
                    "levelfile.lfc" &&
                normalizedSlotPath ==
                    normalizedReadPath;

            const bool levelVivActive =
                g_mohLevelViv6_1Active.load(
                    std::memory_order_acquire) &&
                readGuestU32OrZero(
                    rdram,
                    kMohShellVivObjectSizeAddr) ==
                    0x010E6130u;

            MohBigfMember member{};

            const bool memberResolved =
                exactSlot &&
                levelVivActive &&
                resolveMohLevelViv6_1Member(
                    "levelfile.lfc",
                    member);

            const bool rangeValid =
                memberResolved &&
                slotSize == member.size &&
                a1 <= member.size &&
                a3 <= member.size - a1;

            uint32_t dstOffset = 0u;
            bool dstScratch = false;

            const bool dstValid =
                rangeValid &&
                ps2ResolveGuestPointer(
                    dst,
                    dstOffset,
                    dstScratch) &&
                !dstScratch &&
                dstOffset < PS2_RAM_SIZE &&
                a3 <= PS2_RAM_SIZE - dstOffset;

            uint8_t *dstPtr =
                dstValid
                    ? getMemPtr(rdram, dst)
                    : nullptr;

            const bool copied =
                dstPtr != nullptr &&
                readMohHostFileRange(
                    member.archivePath,
                    static_cast<uint64_t>(
                        member.offset) +
                        a1,
                    dstPtr,
                    a3);

            if (copied)
            {
                setReturnU32(ctx, a3);
                ctx->pc = finalRa;
                levelFileReadHandled = true;
                g_mohLevelFileReadReadySlotV1.store(
                    slot,
                    std::memory_order_release);
            }

            static std::atomic<uint32_t>
                sLevelFileReadLogs{0u};

            const uint32_t logIndex =
                sLevelFileReadLogs.fetch_add(
                    1u,
                    std::memory_order_relaxed);

            if (logIndex < 16u)
            {
                std::cerr
                    << (levelFileReadHandled
                            ? "[MOH:levelfile-read-sync-ready-v1]"
                            : "[MOH:levelfile-read-sync-reject-v1]")
                    << " idx=" << std::dec << logIndex
                    << " slot=0x" << std::hex << slot
                    << " dst=0x" << dst
                    << " offset=0x" << a1
                    << " requested=0x" << a3
                    << " slotState=0x" << slotState
                    << " slotSize=0x" << slotSize
                    << " memberOffset=0x" << member.offset
                    << " memberSize=0x" << member.size
                    << " path='" << path << "'"
                    << " slotPath='" << slotPath << "'"
                    << " archive='"
                    << member.archivePath.string()
                    << "'"
                    << std::dec
                    << " exactSlot="
                    << (exactSlot ? 1 : 0)
                    << " levelVivActive="
                    << (levelVivActive ? 1 : 0)
                    << " memberResolved="
                    << (memberResolved ? 1 : 0)
                    << " rangeValid="
                    << (rangeValid ? 1 : 0)
                    << " dstValid="
                    << (dstValid ? 1 : 0)
                    << " copied="
                    << (copied ? 1 : 0)
                    << std::endl;
            }
        }

        // MOH_LEVEL_ART_BIGF_SYNC_READ_V1
        //
        // The synthetic archive-member slot has no encoded type-1 backend
        // handle, so the native type-4 worker receives a0=1 and performs no
        // I/O. Read only the exact active ART member before an async entry is
        // created; the caller then follows the normal synchronous VFS return.
        const bool levelArtRequested =
            entryCall &&
            ctx != nullptr &&
            finalRa == 0x001F1AB4u &&
            slot != 0u &&
            dst != 0u &&
            a1 == 0u &&
            a3 != 0u &&
            t0 == 0x63u &&
            isMohExactLevelViv6_1ArtPath(path);

        if (levelArtRequested)
        {
            constexpr uint32_t kAsyncManagerBase = 0x0025FC80u;
            const uint32_t slotPool =
                readGuestU32OrZero(
                    rdram,
                    kMohVfsFileSlotPoolBaseAddr);
            const uint32_t slotCount =
                readGuestU32OrZero(
                    rdram,
                    kMohVfsFileSlotCountAddr);
            const uint32_t slotDelta =
                slotPool != 0u && slot >= slotPool
                    ? slot - slotPool
                    : 0xFFFFFFFFu;
            const uint32_t slotState =
                readGuestU32OrZero(rdram, slot + 0x00u);
            const uint32_t slotSize =
                readGuestU32OrZero(rdram, slot + 0x04u);
            const uint32_t slotOffset =
                readGuestU32OrZero(rdram, slot + 0x08u);
            const std::string slotPath =
                readGuestStringLimited(
                    rdram,
                    slot + 0x0Cu,
                    128u);

            MohBigfMember member{};
            const bool memberResolved =
                g_mohLevelViv6_1Active.load(
                    std::memory_order_acquire) &&
                resolveMohLevelViv6_1Member(
                    "6_1_art.cpt",
                    member);
            std::error_code archiveError;
            const bool archiveRegular =
                memberResolved &&
                std::filesystem::is_regular_file(
                    member.archivePath,
                    archiveError) &&
                !archiveError;
            const uint64_t archiveSize =
                archiveRegular
                    ? static_cast<uint64_t>(
                          std::filesystem::file_size(
                              member.archivePath,
                              archiveError))
                    : 0u;
            const uint32_t levelVivObject =
                readGuestU32OrZero(
                    rdram,
                    kMohShellVivObjectPtrAddr);
            const uint32_t levelVivObjectSize =
                readGuestU32OrZero(
                    rdram,
                    kMohShellVivObjectSizeAddr);
            const bool archiveObjectExact =
                !archiveError &&
                levelVivObject != 0u &&
                archiveSize != 0u &&
                archiveSize <= 0xFFFFFFFFull &&
                levelVivObjectSize ==
                    static_cast<uint32_t>(archiveSize);

            const bool slotPoolExact =
                slotPool != 0u &&
                slotCount != 0u &&
                slotDelta != 0xFFFFFFFFu &&
                slotDelta % kMohVfsFileSlotStride == 0u &&
                slotDelta / kMohVfsFileSlotStride < slotCount;
            const bool slotExact =
                slotPoolExact &&
                slotState == 1u &&
                slotOffset == 0u &&
                memberResolved &&
                slotSize == member.size &&
                isMohExactLevelViv6_1ArtPath(slotPath);

            const uint32_t preparedHandle =
                g_mohLevelVivMemberOpenPreparedHandleV1.load(
                    std::memory_order_acquire);
            const uint32_t directCompWake =
                g_mohCompVivFrontendReadWakeHandleV1.load(
                    std::memory_order_acquire);
            const uint32_t preparedSerial =
                preparedHandle & 0x000FFFFFu;
            const uint32_t directCompSerial =
                directCompWake & 0x000FFFFFu;
            const bool sequenceExact =
                (preparedHandle & kMohFrontendAsyncTypeMask) ==
                    kMohFrontendFollowupAsyncTypeBits &&
                (directCompWake & kMohFrontendAsyncTypeMask) ==
                    kMohFrontendAsyncTypeBits &&
                preparedSerial > directCompSerial &&
                preparedSerial - directCompSerial <= 8u;

            const uint32_t table =
                readGuestU32OrZero(
                    rdram,
                    kMohAsyncTableBaseAddr);
            const bool managerExact =
                table != 0u &&
                readGuestU32OrZero(
                    rdram,
                    kAsyncManagerBase + 0x00u) == 0x20u &&
                readGuestU32OrZero(
                    rdram,
                    kAsyncManagerBase + 0x04u) == 0x10u &&
                readGuestU32OrZero(
                    rdram,
                    kAsyncManagerBase + 0x08u) == 0x64u &&
                readGuestU32OrZero(
                    rdram,
                    kAsyncManagerBase + 0x0Cu) != 0u &&
                readGuestU32OrZero(
                    rdram,
                    kAsyncManagerBase + 0x10u) == 0u &&
                readGuestU32OrZero(
                    rdram,
                    kAsyncManagerBase + 0x14u) == 0x0Fu &&
                readGuestU32OrZero(
                    rdram,
                    kAsyncManagerBase + 0x18u) == 0u &&
                readGuestU32OrZero(
                    rdram,
                    kAsyncManagerBase + 0x1Cu) == 0u &&
                readGuestU32OrZero(
                    rdram,
                    kAsyncManagerBase + 0x20u) == 0u &&
                readGuestU32OrZero(
                    rdram,
                    kAsyncManagerBase + 0x24u) == table &&
                readGuestU32OrZero(
                    rdram,
                    kAsyncManagerBase + 0x28u) == slotPool &&
                readGuestU32OrZero(
                    rdram,
                    kAsyncManagerBase + 0x2Cu) == 0u;
            const bool memberRangeExact =
                memberResolved &&
                archiveObjectExact &&
                a3 == member.size &&
                a1 <= member.size &&
                a3 <= member.size - a1 &&
                static_cast<uint64_t>(member.offset) + a1 <=
                    archiveSize &&
                static_cast<uint64_t>(a3) <=
                    archiveSize -
                        (static_cast<uint64_t>(member.offset) + a1);

            uint32_t dstOffset = 0u;
            bool dstScratch = false;
            const bool dstExact =
                slotExact &&
                sequenceExact &&
                managerExact &&
                memberRangeExact &&
                (dst & 0x3Fu) == 0u &&
                ps2ResolveGuestPointer(
                    dst,
                    dstOffset,
                    dstScratch) &&
                !dstScratch &&
                dstOffset < PS2_RAM_SIZE &&
                a3 <= PS2_RAM_SIZE - dstOffset;
            uint8_t *dstPtr =
                dstExact ? getMemPtr(rdram, dst) : nullptr;
            const bool copied =
                dstPtr != nullptr &&
                readMohHostFileRange(
                    member.archivePath,
                    static_cast<uint64_t>(member.offset) + a1,
                    dstPtr,
                    a3);

            if (copied)
            {
                setReturnU32(ctx, a3);
                ctx->pc = finalRa;
                levelArtReadHandled = true;
            }

            static std::atomic<uint32_t> sLevelArtReadLogs{0u};
            const uint32_t logIndex =
                sLevelArtReadLogs.fetch_add(
                    1u,
                    std::memory_order_relaxed);
            if (logIndex < 8u)
            {
                std::cerr
                    << (levelArtReadHandled
                            ? "[MOH:level-art-read-sync-ready-v1]"
                            : "[MOH:level-art-read-sync-reject-v1]")
                    << " idx=" << std::dec << logIndex
                    << " pc=0x" << std::hex << entryPc
                    << " finalRa=0x" << finalRa
                    << " slot=0x" << slot
                    << " dst=0x" << dst
                    << " offset=0x" << a1
                    << " requested=0x" << a3
                    << " slotState=0x" << slotState
                    << " slotSize=0x" << slotSize
                    << " slotOffset=0x" << slotOffset
                    << " preparedHandle=0x" << preparedHandle
                    << " directCompWake=0x" << directCompWake
                    << " table=0x" << table
                    << " managerCount=0x"
                    << readGuestU32OrZero(
                           rdram,
                           kAsyncManagerBase + 0x0Cu)
                    << " memberOffset=0x" << member.offset
                    << " memberSize=0x" << member.size
                    << " archiveSize=0x" << archiveSize
                    << " destinationHash=0x"
                    << (copied
                            ? hashMohGuestBytes(rdram, dst, a3)
                            : 0u)
                    << " path='" << path << "'"
                    << " slotPath='" << slotPath << "'"
                    << " archive='" << member.archivePath.string()
                    << "'"
                    << std::dec
                    << " slotExact=" << (slotExact ? 1 : 0)
                    << " sequenceExact=" << (sequenceExact ? 1 : 0)
                    << " managerExact=" << (managerExact ? 1 : 0)
                    << " archiveObjectExact="
                    << (archiveObjectExact ? 1 : 0)
                    << " memberRangeExact="
                    << (memberRangeExact ? 1 : 0)
                    << " dstExact=" << (dstExact ? 1 : 0)
                    << " copied=" << (copied ? 1 : 0)
                    << std::endl;
            }
        }

        // MOH_LEVEL_CDB_BIGF_SYNC_READ_V1
        //
        // CDB is the next exact virtual member and has the same type-4
        // no-backend protocol as ART. Keep this as a separate transaction so
        // the validated ART branch and its invariants remain unchanged.
        const bool levelCdbRequested =
            entryCall &&
            ctx != nullptr &&
            finalRa == 0x001F1AB4u &&
            slot != 0u &&
            dst != 0u &&
            a1 == 0u &&
            a3 != 0u &&
            t0 == 0x63u &&
            isMohExactLevelViv6_1CdbPath(path);

        if (levelCdbRequested)
        {
            constexpr uint32_t kAsyncManagerBase = 0x0025FC80u;
            const uint32_t slotPool =
                readGuestU32OrZero(
                    rdram,
                    kMohVfsFileSlotPoolBaseAddr);
            const uint32_t slotCount =
                readGuestU32OrZero(
                    rdram,
                    kMohVfsFileSlotCountAddr);
            const uint32_t slotDelta =
                slotPool != 0u && slot >= slotPool
                    ? slot - slotPool
                    : 0xFFFFFFFFu;
            const uint32_t slotState =
                readGuestU32OrZero(rdram, slot + 0x00u);
            const uint32_t slotSize =
                readGuestU32OrZero(rdram, slot + 0x04u);
            const uint32_t slotOffset =
                readGuestU32OrZero(rdram, slot + 0x08u);
            const std::string slotPath =
                readGuestStringLimited(
                    rdram,
                    slot + 0x0Cu,
                    128u);

            MohBigfMember member{};
            const bool memberResolved =
                g_mohLevelViv6_1Active.load(
                    std::memory_order_acquire) &&
                resolveMohLevelViv6_1Member(
                    "6_1_c.cdb",
                    member);
            std::error_code archiveError;
            const bool archiveRegular =
                memberResolved &&
                std::filesystem::is_regular_file(
                    member.archivePath,
                    archiveError) &&
                !archiveError;
            const uint64_t archiveSize =
                archiveRegular
                    ? static_cast<uint64_t>(
                          std::filesystem::file_size(
                              member.archivePath,
                              archiveError))
                    : 0u;
            const uint32_t levelVivObject =
                readGuestU32OrZero(
                    rdram,
                    kMohShellVivObjectPtrAddr);
            const uint32_t levelVivObjectSize =
                readGuestU32OrZero(
                    rdram,
                    kMohShellVivObjectSizeAddr);
            const bool archiveObjectExact =
                !archiveError &&
                levelVivObject != 0u &&
                archiveSize != 0u &&
                archiveSize <= 0xFFFFFFFFull &&
                levelVivObjectSize ==
                    static_cast<uint32_t>(archiveSize);
            const bool slotExact =
                slotPool != 0u &&
                slotCount != 0u &&
                slotDelta != 0xFFFFFFFFu &&
                slotDelta % kMohVfsFileSlotStride == 0u &&
                slotDelta / kMohVfsFileSlotStride < slotCount &&
                slotState == 1u &&
                slotOffset == 0u &&
                memberResolved &&
                slotSize == member.size &&
                isMohExactLevelViv6_1CdbPath(slotPath);

            const uint32_t preparedHandle =
                g_mohLevelVivMemberOpenPreparedHandleV1.load(
                    std::memory_order_acquire);
            const uint32_t directCompWake =
                g_mohCompVivFrontendReadWakeHandleV1.load(
                    std::memory_order_acquire);
            const uint32_t preparedSerial =
                preparedHandle & 0x000FFFFFu;
            const uint32_t directCompSerial =
                directCompWake & 0x000FFFFFu;
            const bool sequenceExact =
                (preparedHandle & kMohFrontendAsyncTypeMask) ==
                    kMohFrontendFollowupAsyncTypeBits &&
                (directCompWake & kMohFrontendAsyncTypeMask) ==
                    kMohFrontendAsyncTypeBits &&
                preparedSerial > directCompSerial &&
                preparedSerial - directCompSerial <= 12u;

            const uint32_t table =
                readGuestU32OrZero(
                    rdram,
                    kMohAsyncTableBaseAddr);
            const bool managerExact =
                table != 0u &&
                readGuestU32OrZero(
                    rdram,
                    kAsyncManagerBase + 0x00u) == 0x20u &&
                readGuestU32OrZero(
                    rdram,
                    kAsyncManagerBase + 0x04u) == 0x10u &&
                readGuestU32OrZero(
                    rdram,
                    kAsyncManagerBase + 0x08u) == 0x64u &&
                readGuestU32OrZero(
                    rdram,
                    kAsyncManagerBase + 0x0Cu) != 0u &&
                readGuestU32OrZero(
                    rdram,
                    kAsyncManagerBase + 0x10u) == 0u &&
                readGuestU32OrZero(
                    rdram,
                    kAsyncManagerBase + 0x14u) == 0x0Fu &&
                readGuestU32OrZero(
                    rdram,
                    kAsyncManagerBase + 0x18u) == 0u &&
                readGuestU32OrZero(
                    rdram,
                    kAsyncManagerBase + 0x1Cu) == 0u &&
                readGuestU32OrZero(
                    rdram,
                    kAsyncManagerBase + 0x20u) == 0u &&
                readGuestU32OrZero(
                    rdram,
                    kAsyncManagerBase + 0x24u) == table &&
                readGuestU32OrZero(
                    rdram,
                    kAsyncManagerBase + 0x28u) == slotPool &&
                readGuestU32OrZero(
                    rdram,
                    kAsyncManagerBase + 0x2Cu) == 0u;
            const bool memberRangeExact =
                memberResolved &&
                archiveObjectExact &&
                a3 == member.size &&
                a1 <= member.size &&
                a3 <= member.size - a1 &&
                static_cast<uint64_t>(member.offset) + a1 <=
                    archiveSize &&
                static_cast<uint64_t>(a3) <=
                    archiveSize -
                        (static_cast<uint64_t>(member.offset) + a1);

            uint32_t dstOffset = 0u;
            bool dstScratch = false;
            const bool dstExact =
                slotExact &&
                sequenceExact &&
                managerExact &&
                memberRangeExact &&
                (dst & 0x3Fu) == 0u &&
                ps2ResolveGuestPointer(
                    dst,
                    dstOffset,
                    dstScratch) &&
                !dstScratch &&
                dstOffset < PS2_RAM_SIZE &&
                a3 <= PS2_RAM_SIZE - dstOffset;
            uint8_t *dstPtr =
                dstExact ? getMemPtr(rdram, dst) : nullptr;
            const bool copied =
                dstPtr != nullptr &&
                readMohHostFileRange(
                    member.archivePath,
                    static_cast<uint64_t>(member.offset) + a1,
                    dstPtr,
                    a3);

            if (copied)
            {
                setReturnU32(ctx, a3);
                ctx->pc = finalRa;
                levelCdbReadHandled = true;
            }

            static std::atomic<uint32_t> sLevelCdbReadLogs{0u};
            const uint32_t logIndex =
                sLevelCdbReadLogs.fetch_add(
                    1u,
                    std::memory_order_relaxed);
            if (logIndex < 8u)
            {
                std::cerr
                    << (levelCdbReadHandled
                            ? "[MOH:level-cdb-read-sync-ready-v1]"
                            : "[MOH:level-cdb-read-sync-reject-v1]")
                    << " idx=" << std::dec << logIndex
                    << " pc=0x" << std::hex << entryPc
                    << " finalRa=0x" << finalRa
                    << " slot=0x" << slot
                    << " dst=0x" << dst
                    << " offset=0x" << a1
                    << " requested=0x" << a3
                    << " slotState=0x" << slotState
                    << " slotSize=0x" << slotSize
                    << " slotOffset=0x" << slotOffset
                    << " preparedHandle=0x" << preparedHandle
                    << " directCompWake=0x" << directCompWake
                    << " table=0x" << table
                    << " managerCount=0x"
                    << readGuestU32OrZero(
                           rdram,
                           kAsyncManagerBase + 0x0Cu)
                    << " memberOffset=0x" << member.offset
                    << " memberSize=0x" << member.size
                    << " archiveSize=0x" << archiveSize
                    << " destinationHash=0x"
                    << (copied
                            ? hashMohGuestBytes(rdram, dst, a3)
                            : 0u)
                    << " path='" << path << "'"
                    << " slotPath='" << slotPath << "'"
                    << " archive='" << member.archivePath.string()
                    << "'"
                    << std::dec
                    << " slotExact=" << (slotExact ? 1 : 0)
                    << " sequenceExact=" << (sequenceExact ? 1 : 0)
                    << " managerExact=" << (managerExact ? 1 : 0)
                    << " archiveObjectExact="
                    << (archiveObjectExact ? 1 : 0)
                    << " memberRangeExact="
                    << (memberRangeExact ? 1 : 0)
                    << " dstExact=" << (dstExact ? 1 : 0)
                    << " copied=" << (copied ? 1 : 0)
                    << std::endl;
            }
        }

        // MOH_LEVEL_SCENE_RESOURCE_BIGF_SYNC_READ_V1
        //
        // BM01.dmf, BM36.dmf, Soldier.skl, and UHM6_1.dmf are consumed by
        // sub_0015FBC8's two scene-construction passes.
        // The guest VFS has already selected their LEVEL.VIV records, but its
        // no-backend type-2 open otherwise publishes -2 and leaves both
        // materializer results null. Deliver only these exact archive members
        // after the same slot/manager checks used by the validated data reads.
        const bool levelSceneResourceRequested =
            entryCall &&
            ctx != nullptr &&
            finalRa == 0x001F1AB4u &&
            slot != 0u &&
            dst != 0u &&
            a1 == 0u &&
            a3 != 0u &&
            t0 == 0x63u &&
            isMohExactLevelViv6_1SceneConstructionPath(path);

        if (levelSceneResourceRequested)
        {
            constexpr uint32_t kAsyncManagerBase = 0x0025FC80u;
            const std::string memberName =
                mohLowerAscii(normalizeMohCdPath(path));
            const uint32_t slotPool =
                readGuestU32OrZero(
                    rdram,
                    kMohVfsFileSlotPoolBaseAddr);
            const uint32_t slotCount =
                readGuestU32OrZero(
                    rdram,
                    kMohVfsFileSlotCountAddr);
            const uint32_t slotDelta =
                slotPool != 0u && slot >= slotPool
                    ? slot - slotPool
                    : 0xFFFFFFFFu;
            const uint32_t slotState =
                readGuestU32OrZero(rdram, slot + 0x00u);
            const uint32_t slotSize =
                readGuestU32OrZero(rdram, slot + 0x04u);
            const uint32_t slotOffset =
                readGuestU32OrZero(rdram, slot + 0x08u);
            const std::string slotPath =
                readGuestStringLimited(
                    rdram,
                    slot + 0x0Cu,
                    128u);
            const std::string normalizedSlotPath =
                mohLowerAscii(normalizeMohCdPath(slotPath));

            MohBigfMember member{};
            const bool memberResolved =
                g_mohLevelViv6_1Active.load(
                    std::memory_order_acquire) &&
                resolveMohLevelViv6_1Member(
                    memberName,
                    member);
            std::error_code archiveError;
            const bool archiveRegular =
                memberResolved &&
                std::filesystem::is_regular_file(
                    member.archivePath,
                    archiveError) &&
                !archiveError;
            const uint64_t archiveSize =
                archiveRegular
                    ? static_cast<uint64_t>(
                          std::filesystem::file_size(
                              member.archivePath,
                              archiveError))
                    : 0u;
            const uint32_t levelVivObject =
                readGuestU32OrZero(
                    rdram,
                    kMohShellVivObjectPtrAddr);
            const uint32_t levelVivObjectSize =
                readGuestU32OrZero(
                    rdram,
                    kMohShellVivObjectSizeAddr);
            const bool archiveObjectExact =
                !archiveError &&
                levelVivObject != 0u &&
                archiveSize != 0u &&
                archiveSize <= 0xFFFFFFFFull &&
                levelVivObjectSize ==
                    static_cast<uint32_t>(archiveSize);
            const bool slotExact =
                slotPool != 0u &&
                slotCount != 0u &&
                slotDelta != 0xFFFFFFFFu &&
                slotDelta % kMohVfsFileSlotStride == 0u &&
                slotDelta / kMohVfsFileSlotStride < slotCount &&
                slotState == 1u &&
                slotOffset == 0u &&
                memberResolved &&
                slotSize == member.size &&
                isMohExactLevelViv6_1SceneConstructionPath(slotPath) &&
                normalizedSlotPath == memberName;

            const uint32_t preparedHandle =
                g_mohLevelVivMemberOpenPreparedHandleV1.load(
                    std::memory_order_acquire);
            const uint32_t directCompWake =
                g_mohCompVivFrontendReadWakeHandleV1.load(
                    std::memory_order_acquire);
            const uint32_t preparedSerial =
                preparedHandle & 0x000FFFFFu;
            const uint32_t directCompSerial =
                directCompWake & 0x000FFFFFu;
            const bool sequenceExact =
                (preparedHandle & kMohFrontendAsyncTypeMask) ==
                    kMohFrontendFollowupAsyncTypeBits &&
                (directCompWake & kMohFrontendAsyncTypeMask) ==
                    kMohFrontendAsyncTypeBits &&
                preparedSerial > directCompSerial;

            const uint32_t table =
                readGuestU32OrZero(
                    rdram,
                    kMohAsyncTableBaseAddr);
            const bool managerExact =
                table != 0u &&
                readGuestU32OrZero(
                    rdram,
                    kAsyncManagerBase + 0x00u) == 0x20u &&
                readGuestU32OrZero(
                    rdram,
                    kAsyncManagerBase + 0x04u) == 0x10u &&
                readGuestU32OrZero(
                    rdram,
                    kAsyncManagerBase + 0x08u) == 0x64u &&
                readGuestU32OrZero(
                    rdram,
                    kAsyncManagerBase + 0x0Cu) != 0u &&
                readGuestU32OrZero(
                    rdram,
                    kAsyncManagerBase + 0x10u) == 0u &&
                readGuestU32OrZero(
                    rdram,
                    kAsyncManagerBase + 0x14u) == 0x0Fu &&
                readGuestU32OrZero(
                    rdram,
                    kAsyncManagerBase + 0x18u) == 0u &&
                readGuestU32OrZero(
                    rdram,
                    kAsyncManagerBase + 0x1Cu) == 0u &&
                readGuestU32OrZero(
                    rdram,
                    kAsyncManagerBase + 0x20u) == 0u &&
                readGuestU32OrZero(
                    rdram,
                    kAsyncManagerBase + 0x24u) == table &&
                readGuestU32OrZero(
                    rdram,
                    kAsyncManagerBase + 0x28u) == slotPool &&
                readGuestU32OrZero(
                    rdram,
                    kAsyncManagerBase + 0x2Cu) == 0u;
            const bool memberRangeExact =
                memberResolved &&
                archiveObjectExact &&
                a3 == member.size &&
                a3 <= member.size &&
                static_cast<uint64_t>(member.offset) <= archiveSize &&
                static_cast<uint64_t>(member.size) <=
                    archiveSize - static_cast<uint64_t>(member.offset);

            uint32_t dstOffset = 0u;
            bool dstScratch = false;
            const bool dstExact =
                slotExact &&
                sequenceExact &&
                managerExact &&
                memberRangeExact &&
                (dst & 0x3Fu) == 0u &&
                ps2ResolveGuestPointer(
                    dst,
                    dstOffset,
                    dstScratch) &&
                !dstScratch &&
                dstOffset < PS2_RAM_SIZE &&
                a3 <= PS2_RAM_SIZE - dstOffset;
            uint8_t *dstPtr =
                dstExact ? getMemPtr(rdram, dst) : nullptr;
            const bool copied =
                dstPtr != nullptr &&
                readMohHostFileRange(
                    member.archivePath,
                    member.offset,
                    dstPtr,
                    a3);

            if (copied)
            {
                setReturnU32(ctx, a3);
                ctx->pc = finalRa;
                levelSceneResourceReadHandled = true;
            }

            static std::atomic<uint32_t> sLogCount{0u};
            const uint32_t logIndex =
                sLogCount.fetch_add(1u, std::memory_order_relaxed);
            if (logIndex < 8u)
            {
                std::cerr
                    << (levelSceneResourceReadHandled
                            ? "[MOH:level-scene-resource-read-ready-v1]"
                            : "[MOH:level-scene-resource-read-reject-v1]")
                    << " idx=" << std::dec << logIndex
                    << " pc=0x" << std::hex << entryPc
                    << " finalRa=0x" << finalRa
                    << " slot=0x" << slot
                    << " dst=0x" << dst
                    << " requested=0x" << a3
                    << " slotState=0x" << slotState
                    << " slotSize=0x" << slotSize
                    << " preparedHandle=0x" << preparedHandle
                    << " directCompWake=0x" << directCompWake
                    << " memberOffset=0x" << member.offset
                    << " memberSize=0x" << member.size
                    << " archiveSize=0x" << archiveSize
                    << " destinationHash=0x"
                    << (copied
                            ? hashMohGuestBytes(rdram, dst, a3)
                            : 0u)
                    << " path='" << path << "'"
                    << " slotPath='" << slotPath << "'"
                    << " archive='" << member.archivePath.string()
                    << "'"
                    << std::dec
                    << " slotExact=" << (slotExact ? 1 : 0)
                    << " sequenceExact=" << (sequenceExact ? 1 : 0)
                    << " managerExact=" << (managerExact ? 1 : 0)
                    << " archiveObjectExact="
                    << (archiveObjectExact ? 1 : 0)
                    << " memberRangeExact="
                    << (memberRangeExact ? 1 : 0)
                    << " dstExact=" << (dstExact ? 1 : 0)
                    << " copied=" << (copied ? 1 : 0)
                    << std::endl;
            }
        }

        // SHELL.VIV is already force-loaded at 0xb0bf80; the original full-file read
        // here YIELDS on an async wait our runtime never completes (every FS handle
        // collides on slot 0, so func_1F3F60 sees a handle mismatch and returns -3
        // forever). The data is already in place, so complete the read synchronously
        // and return the byte count to the caller (the VFS parser at finalRa).
        if (entryCall && dst == kMohShellVivGuestAddr && a3 == kMohShellVivSize && ctx)
        {
            setReturnU32(ctx, a3);
            ctx->pc = finalRa;
            return;
        }

        const bool exactLevelVivReadTrace =
            g_mohLevelViv6_1Active.load(std::memory_order_acquire) &&
            isMohExactLevelViv6_1Path(path) &&
            slot != 0u &&
            dst != 0u &&
            savedA1 == 0u &&
            savedA3 ==
                readGuestU32OrZero(rdram, kMohShellVivObjectSizeAddr);
        if (exactLevelVivReadTrace)
        {
            logMohLevelHeapSentinelSnapshotV1(
                rdram,
                ctx,
                "vfs-read-before",
                dst,
                savedA3);
        }

        if (!loadingSshReadHandled &&
            !levelFileReadHandled &&
            !levelArtReadHandled &&
            !levelCdbReadHandled &&
            !levelSceneResourceReadHandled &&
            g_mohOriginalVfsRead1f25c8 &&
            g_mohOriginalVfsRead1f25c8 !=
                &mohVfsRead1f25c8Trace)
        {
            g_mohOriginalVfsRead1f25c8(
                rdram,
                ctx,
                runtime);
        }
        else if (!loadingSshReadHandled &&
                 !levelFileReadHandled &&
                 !levelArtReadHandled &&
                 !levelCdbReadHandled &&
                 !levelSceneResourceReadHandled &&
                 ctx)
        {
            ctx->pc = getRegU32(ctx, 31);
        }

        if (exactLevelVivReadTrace)
        {
            logMohLevelHeapSentinelSnapshotV1(
                rdram,
                ctx,
                "vfs-read-after",
                dst,
                savedA3);
        }

        std::array<uint32_t, 8> after{};
        for (size_t i = 0; i < after.size(); ++i)
        {
            after[i] = readGuestU32OrZero(rdram, dst + static_cast<uint32_t>(i * 4u));
        }

        const bool changed = after != s_before;

        // MOH_LEVEL_VIV_SYNC_READ_COMPLETE
        //
        // Le backend hôte a déjà copié la plage demandée avant que
        // sub_1F25C8 ne rende la main, mais l'entrée async générique reste
        // parfois à status=0. Le wait 1F3F60 ne peut alors jamais terminer.
        //
        // Validation stricte :
        //   - appel initial de lecture ;
        //   - données réellement modifiées ;
        //   - chemin level.viv ;
        //   - entrée type 4 ;
        //   - même destination et même slot ;
        //   - callback et taille valides.
        //
        // On ne déclenche pas le callback ici : mohWaitAsyncFrontendCompat
        // le fera dans le contexte normal du wait après avoir vu status=1.
        if (entryCall &&
            changed &&
            containsAsciiInsensitive(path, "level.viv"))
        {
            const uint32_t table =
                readGuestU32OrZero(
                    rdram, kMohAsyncTableBaseAddr);

            if (table >= 0x00010000u &&
                table + 8u * kMohAsyncEntryStride <
                    0x02000000u)
            {
                for (uint32_t index = 0u; index < 8u; ++index)
                {
                    const uint32_t entry =
                        table + index * kMohAsyncEntryStride;

                    const uint32_t handle =
                        readGuestU32OrZero(
                            rdram, entry + 0x00u);

                    const uint32_t status =
                        readGuestU32OrZero(
                            rdram, entry + 0x08u);

                    const uint32_t byteCount =
                        readGuestU32OrZero(
                            rdram, entry + 0x1Cu);

                    const uint32_t entryDst =
                        readGuestU32OrZero(
                            rdram, entry + 0x20u);

                    const uint32_t entrySlot =
                        readGuestU32OrZero(
                            rdram, entry + 0x24u);

                    const uint32_t callback =
                        readGuestU32OrZero(
                            rdram, entry + 0x28u);

                    const bool exactRead =
                        (handle & 0x00F00000u) ==
                            0x00400000u &&
                        status == 0u &&
                        byteCount != 0u &&
                        entryDst == dst &&
                        entrySlot == slot &&
                        callback != 0u;

                    if (!exactRead)
                    {
                        continue;
                    }

                    const bool written =
                        writeGuestU32(
                            rdram, entry + 0x08u, 1u);

                    std::cerr
                        << "[MOH:vfs-read-sync-complete]"
                        << " handle=0x" << std::hex << handle
                        << " entry=0x" << entry
                        << " path='" << path << "'"
                        << " dst=0x" << entryDst
                        << " bytes=0x" << byteCount
                        << " slot=0x" << entrySlot
                        << " callback=0x" << callback
                        << std::dec
                        << " written=" << (written ? 1 : 0)
                        << std::endl;

                    break;
                }
            }
        }

        const bool interesting = isMohVfsInterestingName(path) || containsAsciiInsensitive(path, "data\\");
        static std::atomic<uint32_t> s_log{0};
        const uint32_t idx = s_log.fetch_add(1u, std::memory_order_relaxed);
        const uint32_t ret = ctx ? getRegU32(ctx, 2) : 0u;
        const uint32_t nextPc = ctx ? ctx->pc : 0u;
        if ((interesting && idx < 256u) || (changed && idx < 256u) || idx < 48u)
        {
            std::cerr << "[MOH:vfsread25c8]"
                      << " idx=" << std::dec << idx
                      << " phase=" << mohTracePhase(nextPc, finalRa)
                      << " pc=0x" << std::hex << entryPc
                      << " finalRa=0x" << finalRa
                      << " a0=0x" << a0
                      << " a1=0x" << a1
                      << " a2=0x" << a2
                      << " a3=0x" << a3
                      << " t0=0x" << t0
                      << " t1=0x" << t1
                      << " saved=(slot=0x" << slot
                      << ",dst=0x" << dst
                      << ",a1=0x" << savedA1
                      << ",a3=0x" << savedA3
                      << ",t0=0x" << savedT0
                      << ",t1=0x" << savedT1 << ")"
                      << " path='" << path << "'"
                      << " ret=0x" << ret
                      << " nextPc=0x" << nextPc
                      << " changed=" << (changed ? 1 : 0)
                      << " before=(";
            for (size_t i = 0; i < s_before.size(); ++i)
            {
                if (i != 0u)
                {
                    std::cerr << ",";
                }
                std::cerr << "0x" << s_before[i];
            }
            std::cerr << ") after=(";
            for (size_t i = 0; i < after.size(); ++i)
            {
                if (i != 0u)
                {
                    std::cerr << ",";
                }
                std::cerr << "0x" << after[i];
            }
            std::cerr << ") slotWords=";
            logMohGuestWords(rdram, slot, 8u);
            logMohVfsManagerState(rdram, "mgr");
            std::cerr << std::dec << std::endl;
        }
    }

    void mohVfsClose1f2608Trace(uint8_t *rdram, R5900Context *ctx, PS2Runtime *runtime)
    {
        mohHeapCanaryCheck(rdram, ctx, "vfs2608");
        const uint32_t entryPc = ctx ? ctx->pc : 0u;
        const bool entryCall = entryPc == 0x001F2608u;
        const uint32_t finalRa = mohSavedRaOrLive(rdram, ctx, entryPc, 0x001F2608u, 0x20u);
        const uint32_t a0 = getRegU32(ctx, 4);
        const uint32_t a1 = getRegU32(ctx, 5);
        const uint32_t a2 = getRegU32(ctx, 6);
        const uint32_t a3 = getRegU32(ctx, 7);
        const uint32_t liveRa = getRegU32(ctx, 31);

        static uint32_t s_slot = 0u;
        static uint32_t s_a1 = 0u;
        static std::string s_path;
        uint32_t slot = s_slot;
        uint32_t savedA1 = s_a1;
        std::string path = s_path;
        if (entryCall)
        {
            slot = a0;
            savedA1 = a1;
            path = readGuestStringLimited(rdram, slot + 0x0Cu, 128u);
            s_slot = slot;
            s_a1 = savedA1;
            s_path = path;
        }

        const bool exactLevelFileClose =
            isMohExactLevelFilePath(path) &&
            g_mohLevelViv6_1Active.load(
                std::memory_order_acquire) &&
            readGuestU32OrZero(
                rdram,
                kMohShellVivObjectSizeAddr) ==
                0x010E6130u;

        if (entryCall && exactLevelFileClose)
        {
            g_mohLevelFileCloseTraceHandle.store(
                0u,
                std::memory_order_release);
            g_mohLevelFileCloseTraceEntry.store(
                0u,
                std::memory_order_release);
            g_mohLevelFileCloseTraceSlot.store(
                slot,
                std::memory_order_release);
            g_mohLevelFileCloseTraceFinalRa.store(
                finalRa,
                std::memory_order_release);
        }

        if (exactLevelFileClose)
        {
            logMohLevelFileCloseTransitionV1(
                rdram,
                "vfs-before",
                entryPc,
                entryPc,
                liveRa,
                finalRa,
                slot,
                g_mohLevelFileCloseTraceEntry.load(
                    std::memory_order_acquire),
                g_mohLevelFileCloseTraceHandle.load(
                    std::memory_order_acquire),
                getRegU32(ctx, 2));
        }

        if (g_mohOriginalVfsClose1f2608 && g_mohOriginalVfsClose1f2608 != &mohVfsClose1f2608Trace)
        {
            g_mohOriginalVfsClose1f2608(rdram, ctx, runtime);
        }
        else if (ctx)
        {
            ctx->pc = getRegU32(ctx, 31);
        }

        const bool interesting = isMohVfsInterestingName(path) || containsAsciiInsensitive(path, "data\\");
        static std::atomic<uint32_t> s_log{0};
        const uint32_t idx = s_log.fetch_add(1u, std::memory_order_relaxed);
        const uint32_t ret = ctx ? getRegU32(ctx, 2) : 0u;
        const uint32_t nextPc = ctx ? ctx->pc : 0u;

        if (exactLevelFileClose)
        {
            const uint32_t closeEntry =
                findMohLevelFileCloseEntry(
                    rdram,
                    slot);

            if (closeEntry != 0u)
            {
                g_mohLevelFileCloseTraceEntry.store(
                    closeEntry,
                    std::memory_order_release);
                g_mohLevelFileCloseTraceHandle.store(
                    readGuestU32OrZero(
                        rdram,
                        closeEntry + 0x00u),
                    std::memory_order_release);
            }

            logMohLevelFileCloseTransitionV1(
                rdram,
                "vfs-after",
                entryPc,
                nextPc,
                liveRa,
                finalRa,
                slot,
                g_mohLevelFileCloseTraceEntry.load(
                    std::memory_order_acquire),
                g_mohLevelFileCloseTraceHandle.load(
                    std::memory_order_acquire),
                ret);
        }

        const bool completed = ctx && (nextPc < 0x001F2608u || nextPc >= 0x001F2660u);
        const bool movieSlot = containsAsciiInsensitive(path, "movies") &&
                               containsAsciiInsensitive(path, ".mpc");
        bool freedSlot = false;
        // PS2_MOH_NO_SLOT_FREE=1 disables the movie slot recycling: the close(-2)
        // freed here is a NORMAL stream flush of a transient handle — the player
        // keeps using the slot for its reads afterwards, and freeing it leaves the
        // player's read waiting forever (3 movie-updates per 150s, no decode).
        static const bool s_mohSlotFreeEnabled = [] {
            const char *v = std::getenv("PS2_MOH_NO_SLOT_FREE");
            return !(v && std::strcmp(v, "1") == 0);
        }();
        if (s_mohSlotFreeEnabled && completed && ret != 0u && movieSlot && slot != 0u)
        {
            freedSlot = clearMohVfsFileSlot(rdram, slot);
            static std::atomic<uint32_t> s_freeLog{0};
            const uint32_t freeIdx = s_freeLog.fetch_add(1u, std::memory_order_relaxed);
            if (freeIdx < 64u)
            {
                std::cerr << "[MOH:vfs-slot-free]"
                          << " idx=" << std::dec << freeIdx
                          << " slot=0x" << std::hex << slot
                          << " path='" << path << "'"
                          << " ret=0x" << ret
                          << " nextPc=0x" << nextPc
                          << " freed=" << (freedSlot ? 1 : 0)
                          << std::dec << std::endl;
            }
        }
        if ((interesting && idx < 256u) || idx < 48u)
        {
            std::cerr << "[MOH:vfsclose2608]"
                      << " idx=" << std::dec << idx
                      << " phase=" << mohTracePhase(nextPc, finalRa)
                      << " pc=0x" << std::hex << entryPc
                      << " finalRa=0x" << finalRa
                      << " a0=0x" << a0
                      << " a1=0x" << a1
                      << " a2=0x" << a2
                      << " a3=0x" << a3
                      << " saved=(slot=0x" << slot
                      << ",a1=0x" << savedA1 << ")"
                      << " path='" << path << "'"
                      << " ret=0x" << ret
                      << " nextPc=0x" << nextPc
                      << " freedSlot=" << (freedSlot ? 1 : 0)
                      << " slotWords=";
            logMohGuestWords(rdram, slot, 8u);
            logMohVfsManagerState(rdram, "mgr");
            std::cerr << std::dec << std::endl;
        }
    }

    void mohVfsCleanup1f4098Fix(uint8_t *rdram, R5900Context *ctx, PS2Runtime *runtime)
    {
        const uint32_t entryPc = ctx ? ctx->pc : 0u;
        const bool entryCall = entryPc == 0x001F4098u;
        const uint32_t a0 = getRegU32(ctx, 4);

        static uint32_t s_entry = 0u;
        static uint32_t s_handle = 0u;
        static uint32_t s_slot = 0u;
        static std::string s_path;

        uint32_t entry = s_entry;
        uint32_t handle = s_handle;
        uint32_t slot = s_slot;
        std::string path = s_path;
        if (entryCall)
        {
            handle = a0;
            uint32_t tableBase = 0u;
            (void)readGuestU32(rdram, kMohAsyncTableBaseAddr, tableBase);
            entry = tableBase + (((handle >> 24u) & 0xFFu) * kMohAsyncEntryStride);
            slot = readGuestU32OrZero(rdram, entry + 0x24u);
            path = slot != 0u ? readGuestStringLimited(rdram, slot + 0x0Cu, 128u) : std::string{};
            s_entry = entry;
            s_handle = handle;
            s_slot = slot;
            s_path = path;
        }

        if (g_mohOriginalVfsCleanup1f4098 && g_mohOriginalVfsCleanup1f4098 != &mohVfsCleanup1f4098Fix)
        {
            g_mohOriginalVfsCleanup1f4098(rdram, ctx, runtime);
        }
        else if (ctx)
        {
            ctx->pc = getRegU32(ctx, 31);
        }

        const uint32_t nextPc = ctx ? ctx->pc : 0u;
        const bool completed = ctx && (nextPc < 0x001F4098u || nextPc >= 0x001F41C0u);
        const bool movieFileSlot = (handle & kMohFrontendAsyncTypeMask) == kMohMovieFileAsyncTypeBits &&
                                   containsAsciiInsensitive(path, "movies") &&
                                   containsAsciiInsensitive(path, ".mpc");
        if (completed && movieFileSlot && slot != 0u)
        {
            const bool freedSlot = clearMohVfsFileSlot(rdram, slot);
            static std::atomic<uint32_t> s_log{0};
            const uint32_t idx = s_log.fetch_add(1u, std::memory_order_relaxed);
            if (idx < 64u)
            {
                std::cerr << "[MOH:vfs-cleanup-slot-free]"
                          << " idx=" << std::dec << idx
                          << " entry=0x" << std::hex << entry
                          << " handle=0x" << handle
                          << " slot=0x" << slot
                          << " path='" << path << "'"
                          << " nextPc=0x" << nextPc
                          << " freed=" << (freedSlot ? 1 : 0)
                          << std::dec << std::endl;
            }
        }
    }

    void mohVfsParse1f1a38Trace(uint8_t *rdram, R5900Context *ctx, PS2Runtime *runtime)
    {
        mohHeapCanaryCheck(rdram, ctx, "vfs1a38");
        const uint32_t entryPc = ctx ? ctx->pc : 0u;
        const uint32_t a0 = getRegU32(ctx, 4);
        const uint32_t a1 = getRegU32(ctx, 5);
        const uint32_t spBefore = getRegU32(ctx, 29);
        const uint32_t gp = getRegU32(ctx, 28);
        const uint32_t liveRa = getRegU32(ctx, 31);
        const uint32_t finalRa = mohSavedRaOrLive(rdram, ctx, entryPc, 0x001F1A38u, 0x40u);
        const bool entryCall = entryPc == 0x001F1A38u;
        const uint32_t record = entryCall ? a1 : getRegU32(ctx, 16);
        uint32_t rec0Before = 0u;
        uint32_t rec8Before = 0u;
        uint32_t recCBefore = 0u;
        (void)readGuestU32(rdram, record + 0x00u, rec0Before);
        (void)readGuestU32(rdram, record + 0x08u, rec8Before);
        (void)readGuestU32(rdram, record + 0x0Cu, recCBefore);
        const std::string path = readGuestStringLimited(rdram, rec0Before, 96u);
        const bool interesting = isMohVfsInterestingName(path);
        const uint32_t stackOutBefore = readGuestU32OrZero(rdram, spBefore);
        const uint32_t parserFnBefore = readGuestU32OrZero(rdram, gp + 4294935064u);
        const uint32_t parserArgBefore = readGuestU32OrZero(rdram, gp + 4294935068u);

        // Mark the two packed .bum parses so the func_1F2660 size-getter repair can
        // supply the sizes observed on original hardware.  Returning zero for chars
        // reserved only 0x80 bytes at 0x59FD80; later frontend objects occupied the
        // unreserved range and were overwritten when the delayed chars payload landed.
        if (entryCall && path.find("chars") != std::string::npos)
        {
            g_mohCharsActive = true;
        }
        else if (entryCall && path.find("binum") != std::string::npos)
        {
            g_mohBinumActive = true;
        }

        if (g_mohOriginalVfsParse1f1a38 && g_mohOriginalVfsParse1f1a38 != &mohVfsParse1f1a38Trace)
        {
            g_mohOriginalVfsParse1f1a38(rdram, ctx, runtime);
        }
        else if (ctx)
        {
            ctx->pc = getRegU32(ctx, 31);
        }

        uint32_t rec0After = 0u;
        uint32_t rec8After = 0u;
        uint32_t recCAfter = 0u;
        (void)readGuestU32(rdram, record + 0x00u, rec0After);
        (void)readGuestU32(rdram, record + 0x08u, rec8After);
        (void)readGuestU32(rdram, record + 0x0Cu, recCAfter);

        const uint32_t ret = ctx ? getRegU32(ctx, 2) : 0u;
        uint32_t ret0 = 0u, ret4 = 0u, ret8 = 0u, retC = 0u;
        (void)readGuestU32(rdram, ret + 0x00u, ret0);
        (void)readGuestU32(rdram, ret + 0x04u, ret4);
        (void)readGuestU32(rdram, ret + 0x08u, ret8);
        (void)readGuestU32(rdram, ret + 0x0Cu, retC);
        const uint32_t stackOutAfter = readGuestU32OrZero(rdram, spBefore);
        const uint32_t parserFnAfter = readGuestU32OrZero(rdram, gp + 4294935064u);
        const uint32_t parserArgAfter = readGuestU32OrZero(rdram, gp + 4294935068u);
        const uint32_t nextPc = ctx ? ctx->pc : 0u;
        const bool finalPhase = finalRa != 0u && nextPc == finalRa;
        if (finalPhase)
        {
            g_mohCharsActive = false;
            g_mohBinumActive = false; // .bum files parse sequentially; clear on this parse's return
        }

        static std::atomic<uint32_t> s_log{0};
        const uint32_t idx = s_log.fetch_add(1u, std::memory_order_relaxed);
        if ((interesting && idx < 256u) || idx < 64u || (finalPhase && ret == 0u && isMohVfsInterestingName(path)))
        {
            std::cerr << "[MOH:vfsparse1a38]"
                      << " idx=" << std::dec << idx
                      << " phase=" << mohTracePhase(nextPc, finalRa)
                      << " pc=0x" << std::hex << entryPc
                      << " finalRa=0x" << finalRa
                      << " liveRa=0x" << liveRa
                      << " a0=0x" << a0
                      << " a1=0x" << a1
                      << " rec=0x" << record
                      << " pathPtr=0x" << rec0Before
                      << " path='" << path << "'"
                      << " recBefore=(0x" << rec0Before << ",0x" << rec8Before << ",0x" << recCBefore << ")"
                      << " recAfter=(0x" << rec0After << ",0x" << rec8After << ",0x" << recCAfter << ")"
                      << " stackOutBefore=0x" << stackOutBefore
                      << " stackOutAfter=0x" << stackOutAfter
                      << " parserBefore=(0x" << parserFnBefore << ",0x" << parserArgBefore << ")"
                      << " parserAfter=(0x" << parserFnAfter << ",0x" << parserArgAfter << ")"
                      << " ret=0x" << ret
                      << " nextPc=0x" << nextPc
                      << " retWords=(0x" << ret0 << ",0x" << ret4 << ",0x" << ret8 << ",0x" << retC << ")";
            logMohVfsManagerState(rdram, "mgr");
            std::cerr << std::dec << std::endl;
        }
    }

    // func_1F2660 returns the packed .bum file size received by materializer 0x1F68D0.
    // Original hardware resolves chars=0x64CC and binum=0x61C; the recompiled VFS
    // currently reports zero for both late SHELL.VIV entries.  Repairing both sizes
    // restores the original heap layout (chars @0x59FD80, binum @0x5A6300) and keeps
    // frontend objects from being allocated inside the eventual chars payload.
    void mohSize1f2660Repair(uint8_t *rdram, R5900Context *ctx, PS2Runtime *runtime)
    {
        const uint32_t entryPc = ctx ? ctx->pc : 0u;
        const bool entryCall = entryPc == 0x001F2660u;
        const uint32_t liveRa = getRegU32(ctx, 31);
        const uint32_t finalRa = mohSavedRaOrLive(rdram, ctx, entryPc, 0x001F2660u, 0x20u);

        static thread_local uint32_t s_levelMemberSlot = 0u;
        static thread_local uint32_t s_levelMemberOperation = 0u;
        static thread_local std::string s_levelMemberPath;

        if (entryCall)
        {
            s_levelMemberSlot = getRegU32(ctx, 4);
            s_levelMemberOperation = getRegU32(ctx, 5);
            s_levelMemberPath = readGuestStringLimited(
                rdram,
                s_levelMemberSlot + 0x0Cu,
                128u);
        }

        const bool exactLevelMember =
            isMohExactLevelViv6_1DataMemberPath(s_levelMemberPath);
        const uint32_t v0Before = getRegU32(ctx, 2);
        const uint32_t s0Before = getRegU32(ctx, 16);
        const uint32_t s1Before = getRegU32(ctx, 17);

        static std::atomic<uint32_t> s_levelMemberTrace{0u};
        const uint32_t beforeIdx = exactLevelMember
            ? s_levelMemberTrace.fetch_add(1u, std::memory_order_relaxed)
            : 32u;
        if (beforeIdx < 32u)
        {
            const uint32_t candidateHandle =
                entryPc == 0x001F267Cu ? v0Before : s0Before;
            std::cerr
                << "[MOH:level-member-size-chain-trace-v1]"
                << " idx=" << std::dec << beforeIdx
                << " stage=before-native"
                << " pc=0x" << std::hex << entryPc
                << " liveRa=0x" << liveRa
                << " finalRa=0x" << finalRa
                << " slot=0x" << s_levelMemberSlot
                << " operation=0x" << s_levelMemberOperation
                << " v0=0x" << v0Before
                << " s0=0x" << s0Before
                << " s1=0x" << s1Before
                << " path='" << s_levelMemberPath << "'"
                << " slotWords=";
            logMohGuestWords(rdram, s_levelMemberSlot, 8u);
            logMohVfsHandleSnapshot(rdram, candidateHandle, "candidate");
            logMohVfsManagerState(rdram, "mgr");
            std::cerr << std::dec << std::endl;
        }

        if (g_mohOriginalSize1f2660 && g_mohOriginalSize1f2660 != &mohSize1f2660Repair)
        {
            g_mohOriginalSize1f2660(rdram, ctx, runtime);
        }
        else if (ctx)
        {
            ctx->pc = getRegU32(ctx, 31);
        }

        const uint32_t nextPc = ctx ? ctx->pc : 0u;
        const uint32_t ret = ctx ? getRegU32(ctx, 2) : 0u;
        const uint32_t afterIdx = exactLevelMember
            ? s_levelMemberTrace.fetch_add(1u, std::memory_order_relaxed)
            : 32u;
        if (afterIdx < 32u)
        {
            const uint32_t candidateHandle = getRegU32(ctx, 16);
            std::cerr
                << "[MOH:level-member-size-chain-trace-v1]"
                << " idx=" << std::dec << afterIdx
                << " stage=after-native"
                << " pc=0x" << std::hex << entryPc
                << " nextPc=0x" << nextPc
                << " liveRa=0x" << liveRa
                << " finalRa=0x" << finalRa
                << " slot=0x" << s_levelMemberSlot
                << " operation=0x" << s_levelMemberOperation
                << " ret=0x" << ret
                << " s0=0x" << candidateHandle
                << " s1=0x" << getRegU32(ctx, 17)
                << " path='" << s_levelMemberPath << "'"
                << " slotWords=";
            logMohGuestWords(rdram, s_levelMemberSlot, 8u);
            logMohVfsHandleSnapshot(rdram, candidateHandle, "candidate");
            logMohVfsManagerState(rdram, "mgr");
            std::cerr << std::dec << std::endl;
        }

        if (finalRa != 0u && nextPc == finalRa && ret == 0u &&
            (g_mohCharsActive || g_mohBinumActive))
        {
            const bool chars = g_mohCharsActive;
            const uint32_t repairedSize = chars ? 0x64CCu : 0x61Cu;
            setReturnU32(ctx, repairedSize);
            static std::atomic<uint32_t> s_fix{0};
            if (s_fix.fetch_add(1u, std::memory_order_relaxed) < 8u)
            {
                std::cerr << "[MOH:size2660-fix] " << (chars ? "chars" : "binum")
                          << " func_1F2660 returned 0 -> patched size=0x" << std::hex
                          << repairedSize
                          << " finalRa=0x" << std::hex << finalRa << std::dec << std::endl;
            }
        }
    }

    void mohVfsOpenCommonTrace(const char *tag,
                               PS2Runtime::RecompiledFunction original,
                               uint8_t *rdram,
                               R5900Context *ctx,
                               PS2Runtime *runtime)
    {
        const uint32_t entryPc = ctx ? ctx->pc : 0u;
        const uint32_t a0 = getRegU32(ctx, 4);
        const uint32_t a1 = getRegU32(ctx, 5);
        const uint32_t spBefore = getRegU32(ctx, 29);
        const uint32_t liveRa = getRegU32(ctx, 31);
        const bool is19f0 = std::strcmp(tag, "vfs19f0") == 0;
        const uint32_t functionEntryPc = is19f0 ? 0x001F19F0u : 0x001F1B40u;
        const uint32_t finalRa = mohSavedRaOrLive(rdram, ctx, entryPc, functionEntryPc, 0x20u);
        uint32_t pathPtr = a0;
        if (entryPc != functionEntryPc)
        {
            pathPtr = readGuestU32OrZero(rdram, spBefore);
        }

        const std::string path = readGuestStringLimited(rdram, pathPtr, 128u);
        const bool interesting = isMohVfsInterestingName(path);

        if (original)
        {
            original(rdram, ctx, runtime);
        }
        else if (ctx)
        {
            ctx->pc = getRegU32(ctx, 31);
        }

        const uint32_t ret = ctx ? getRegU32(ctx, 2) : 0u;
        uint32_t ret0 = 0u, ret4 = 0u, ret8 = 0u, retC = 0u;
        (void)readGuestU32(rdram, ret + 0x00u, ret0);
        (void)readGuestU32(rdram, ret + 0x04u, ret4);
        (void)readGuestU32(rdram, ret + 0x08u, ret8);
        (void)readGuestU32(rdram, ret + 0x0Cu, retC);

        static std::atomic<uint32_t> s_log{0};
        const uint32_t idx = s_log.fetch_add(1u, std::memory_order_relaxed);
        const uint32_t nextPc = ctx ? ctx->pc : 0u;
        if ((interesting && idx < 256u) || idx < 48u || (ret == 0u && interesting))
        {
            std::cerr << "[MOH:" << tag << "]"
                      << " idx=" << std::dec << idx
                      << " phase=" << mohTracePhase(nextPc, finalRa)
                      << " pc=0x" << std::hex << entryPc
                      << " finalRa=0x" << finalRa
                      << " liveRa=0x" << liveRa
                      << " a0=0x" << a0
                      << " a1=0x" << a1
                      << " pathPtr=0x" << pathPtr
                      << " path='" << path << "'"
                      << " ret=0x" << ret
                      << " nextPc=0x" << nextPc
                      << " retWords=(0x" << ret0 << ",0x" << ret4 << ",0x" << ret8 << ",0x" << retC << ")";
            logMohVfsManagerState(rdram, "mgr");
            std::cerr << std::dec << std::endl;
        }
    }

    void mohVfsOpen1f19f0Trace(uint8_t *rdram, R5900Context *ctx, PS2Runtime *runtime)
    {
        mohVfsOpenCommonTrace("vfs19f0", g_mohOriginalVfsOpen1f19f0, rdram, ctx, runtime);
    }

    void mohVfsOpen1f1b40Trace(uint8_t *rdram, R5900Context *ctx, PS2Runtime *runtime)
    {
        mohVfsOpenCommonTrace("vfs1b40", g_mohOriginalVfsOpen1f1b40, rdram, ctx, runtime);
    }

    uint32_t mohAllocGameBlock13c370(uint8_t *rdram, const R5900Context *ctx, PS2Runtime *runtime, uint32_t size)
    {
        if (!rdram || !ctx || !runtime || !g_mohOriginalAlloc13c370)
        {
            return 0u;
        }

        R5900Context allocCtx = *ctx;
        allocCtx.pc = 0x0013C370u;
        allocCtx.in_delay_slot = false;
        allocCtx.branch_pc = 0u;
        setMohRegU32(&allocCtx, 4, size);
        setMohRegU32(&allocCtx, 31, 0u);

        g_mohOriginalAlloc13c370(rdram, &allocCtx, runtime);
        const uint32_t ptr = getRegU32(&allocCtx, 2);
        if (allocCtx.pc != 0u)
        {
            std::cerr << "[MOH:binum-synth] alloc yielded pc=0x" << std::hex << allocCtx.pc
                      << " ptr=0x" << ptr << std::dec << std::endl;
            return 0u;
        }

        return ptr;
    }

    bool mohBinumSynthesisEnabled()
    {
        static const bool enabled = [] {
            const char *value = std::getenv("PS2_MOH_SYNTH_BINUM");
            if (!value)
            {
                return true;
            }

            return std::strcmp(value, "0") != 0 &&
                   std::strcmp(value, "false") != 0 &&
                   std::strcmp(value, "FALSE") != 0 &&
                   std::strcmp(value, "off") != 0 &&
                   std::strcmp(value, "OFF") != 0;
        }();
        return enabled;
    }

    uint32_t mohSynthesizeBinumLayout(uint8_t *rdram, R5900Context *ctx, PS2Runtime *runtime)
    {
        constexpr uint32_t kSource = kMohShellVivGuestAddr + kMohBinumShellVivOffset;

        // The binum layout is sourced from the SHELL.VIV image at kSource. The
        // first binum.bum read happens while SHELL.VIV is still resident, but a
        // later (2nd) binum.bum read occurs after the shell region has been
        // overwritten by level data (the source count reads back 0). binum.bum
        // is a static file, so snapshot the validated layout bytes on the first
        // good read and reuse them when the live source is gone. This keeps the
        // first-read path byte-identical and fixes the 2nd-read stall at
        // 0x1f4018 without any file/handle-specific runtime state.
        static std::vector<uint8_t> s_cachedBinumLayout;
        static std::mutex s_cachedBinumMutex;

        uint16_t sourceCount = 0u;
        const bool liveSourceValid =
            readGuestU16(rdram, kSource, sourceCount) &&
            sourceCount == kMohBinumCount;

        if (liveSourceValid)
        {
            const uint8_t *srcPtr = getConstMemPtr(rdram, kSource);
            if (srcPtr)
            {
                std::lock_guard<std::mutex> lk(s_cachedBinumMutex);
                s_cachedBinumLayout.assign(srcPtr, srcPtr + kMohBinumSize);
            }
        }

        bool haveLayout = false;
        {
            std::lock_guard<std::mutex> lk(s_cachedBinumMutex);
            haveLayout = s_cachedBinumLayout.size() == kMohBinumSize;
        }
        if (!haveLayout)
        {
            std::cerr << "[MOH:binum-synth] missing source bytes source=0x" << std::hex << kSource
                      << " count=0x" << sourceCount
                      << " expected=0x" << kMohBinumCount
                      << " (no cache)"
                      << std::dec << std::endl;
            return 0u;
        }

        const uint32_t dst = mohAllocGameBlock13c370(rdram, ctx, runtime, kMohBinumSize);
        if (dst == 0u)
        {
            return 0u;
        }

        uint8_t *dstPtr = getMemPtr(rdram, dst);
        if (!dstPtr)
        {
            std::cerr << "[MOH:binum-synth] copy failed dst=0x" << std::hex << dst
                      << " source=0x" << kSource << std::dec << std::endl;
            return 0u;
        }
        {
            std::lock_guard<std::mutex> lk(s_cachedBinumMutex);
            std::memcpy(dstPtr, s_cachedBinumLayout.data(), kMohBinumSize);
        }

        std::cerr << "[MOH:binum-synth] copied binum layout dst=0x" << std::hex << dst
                  << " source=" << (liveSourceValid ? "live" : "cache")
                  << " bytes=0x" << kMohBinumSize
                  << " count=0x" << kMohBinumCount
                  << std::dec << std::endl;
        return dst;
    }

    void mohBumParser1f68d0Trace(uint8_t *rdram, R5900Context *ctx, PS2Runtime *runtime)
    {
        mohHeapCanaryCheck(rdram, ctx, "bum68d0");
        const uint32_t entryPc = ctx ? ctx->pc : 0u;
        const uint32_t a0 = getRegU32(ctx, 4);
        const uint32_t a1 = getRegU32(ctx, 5);
        const uint32_t a2 = getRegU32(ctx, 6);
        const uint32_t a3 = getRegU32(ctx, 7);
        const uint32_t t0 = getRegU32(ctx, 8);
        const uint32_t t1 = getRegU32(ctx, 9);
        const uint32_t liveRa = getRegU32(ctx, 31);
        const uint32_t finalRa = mohSavedRaOrLive(rdram, ctx, entryPc, 0x001F68D0u, 0x0u);
        const bool entryCall = entryPc == 0x001F68D0u;

        static std::string s_pendingPath;
        static uint32_t s_pendingPathPtr = 0u;
        static uint32_t s_pendingA1 = 0u;
        static uint32_t s_pendingA2 = 0u;
        static uint32_t s_pendingA3 = 0u;
        static uint32_t s_pendingT0 = 0u;
        static uint32_t s_pendingT1 = 0u;

        std::string path;
        uint32_t pathPtr = 0u;
        uint32_t inputData = 0u;
        uint32_t recordArg = 0u;
        uint32_t originalA3 = 0u;
        uint32_t originalT0 = 0u;
        uint32_t originalT1 = 0u;
        if (entryCall)
        {
            pathPtr = a0;
            path = readGuestStringLimited(rdram, pathPtr, 128u);
            inputData = a1;
            recordArg = a2;
            originalA3 = a3;
            originalT0 = t0;
            originalT1 = t1;

            s_pendingPath = path;
            s_pendingPathPtr = pathPtr;
            s_pendingA1 = inputData;
            s_pendingA2 = recordArg;
            s_pendingA3 = originalA3;
            s_pendingT0 = originalT0;
            s_pendingT1 = originalT1;
        }
        else
        {
            path = s_pendingPath;
            pathPtr = s_pendingPathPtr;
            inputData = s_pendingA1;
            recordArg = s_pendingA2;
            originalA3 = s_pendingA3;
            originalT0 = s_pendingT0;
            originalT1 = s_pendingT1;
        }

        const bool synthesizeBinum = entryCall && mohBinumSynthesisEnabled() && containsAsciiInsensitive(path, "binum.bum");
        if (synthesizeBinum)
        {
            const uint32_t synthetic = mohSynthesizeBinumLayout(rdram, ctx, runtime);
            if (synthetic != 0u)
            {
                setMohRegU32(ctx, 2, synthetic);
                if (ctx)
                {
                    ctx->pc = finalRa;
                }
            }
            else if (g_mohOriginalBumParser1f68d0 && g_mohOriginalBumParser1f68d0 != &mohBumParser1f68d0Trace)
            {
                g_mohOriginalBumParser1f68d0(rdram, ctx, runtime);
            }
            else if (ctx)
            {
                ctx->pc = getRegU32(ctx, 31);
            }
        }
        else if (g_mohOriginalBumParser1f68d0 && g_mohOriginalBumParser1f68d0 != &mohBumParser1f68d0Trace)
        {
            g_mohOriginalBumParser1f68d0(rdram, ctx, runtime);
        }
        else if (ctx)
        {
            ctx->pc = getRegU32(ctx, 31);
        }

        const uint32_t ret = ctx ? getRegU32(ctx, 2) : 0u;
        const uint32_t nextPc = ctx ? ctx->pc : 0u;
        const bool interesting = isMohVfsInterestingName(path);
        const bool exactLevelMember =
            isMohExactLevelViv6_1DataMemberPath(path);

        static std::atomic<uint32_t> s_levelMemberTrace{0u};
        if (exactLevelMember)
        {
            const uint32_t levelMemberIdx =
                s_levelMemberTrace.fetch_add(1u, std::memory_order_relaxed);
            if (levelMemberIdx < 32u)
            {
                std::cerr
                    << "[MOH:level-member-materializer-trace-v1]"
                    << " idx=" << std::dec << levelMemberIdx
                    << " phase=" << mohTracePhase(nextPc, finalRa)
                    << " pc=0x" << std::hex << entryPc
                    << " liveRa=0x" << liveRa
                    << " finalRa=0x" << finalRa
                    << " pathPtr=0x" << pathPtr
                    << " path='" << path << "'"
                    << " requestedSize=0x" << inputData
                    << " record=0x" << recordArg
                    << " ret=0x" << ret
                    << " nextPc=0x" << nextPc
                    << " dataWords=";
                logMohGuestWords(rdram, inputData, 8u);
                std::cerr << " retWords=";
                logMohGuestWords(rdram, ret, 8u);
                logMohVfsManagerState(rdram, "mgr");
                std::cerr << std::dec << std::endl;
            }
        }

        static std::atomic<uint32_t> s_log{0};
        const uint32_t idx = s_log.fetch_add(1u, std::memory_order_relaxed);
        if ((interesting && idx < 256u) || idx < 32u || (ret == 0u && interesting))
        {
            std::cerr << "[MOH:bumparser68d0]"
                      << " idx=" << std::dec << idx
                      << " phase=" << mohTracePhase(nextPc, finalRa)
                      << " pc=0x" << std::hex << entryPc
                      << " finalRa=0x" << finalRa
                      << " liveRa=0x" << liveRa
                      << " pathPtr=0x" << pathPtr
                      << " path='" << path << "'"
                      << " a0=0x" << a0
                      << " a1=0x" << a1
                      << " a2=0x" << a2
                      << " a3=0x" << a3
                      << " t0=0x" << t0
                      << " t1=0x" << t1
                      << " saved=(data=0x" << inputData
                      << ",record=0x" << recordArg
                      << ",a3=0x" << originalA3
                      << ",t0=0x" << originalT0
                      << ",t1=0x" << originalT1 << ")"
                      << " ret=0x" << ret
                      << " nextPc=0x" << nextPc
                      << " dataWords=";
            logMohGuestWords(rdram, inputData, 8u);
            std::cerr << " retWords=";
            logMohGuestWords(rdram, ret, 24u);
            std::cerr << std::dec << std::endl;
        }
    }

