    bool isMohCompC0FinalMutexCallV1(
        const uint8_t *rdram,
        uint32_t mutex,
        uint32_t outerRa,
        uint32_t expectedOuterRa)
    {
        if (mutex != 0x0036B0A0u ||
            outerRa != expectedOuterRa)
        {
            return false;
        }

        const uint32_t object =
            g_mohCompC0FinalCallbackObjectV1.load(
                std::memory_order_acquire);
        const uint32_t handle =
            g_mohCompC0FinalCallbackHandleV1.load(
                std::memory_order_acquire);
        const uint32_t slot =
            readGuestU32OrZero(rdram, object + 0x20u);
        return object != 0u &&
               handle != 0u &&
               isMohExactCompC0ArtPath(
                   readGuestStringLimited(
                       rdram,
                       slot + 0x0Cu,
                       128u));
    }

