    bool prepareMohLevelVivMemberOpenWorkerV1(
        uint8_t *rdram,
        R5900Context *ctx,
        uint32_t current,
        uint32_t handle)
    {
        constexpr uint32_t kManagerBase = 0x0025FC80u;

        if (!rdram ||
            !ctx ||
            ctx->pc != 0x001F5148u ||
            getRegU32(ctx, 31) != 0x001F5030u ||
            getRegU32(ctx, 4) != 0u ||
            !g_mohLevelViv6_1Active.load(
                std::memory_order_acquire) ||
            readGuestU32OrZero(
                rdram,
                kMohShellVivObjectSizeAddr) != 0x010E6130u)
        {
            return false;
        }

        const uint32_t directCompWake =
            g_mohCompVivFrontendReadWakeHandleV1.load(
                std::memory_order_acquire);
        const uint32_t wakeSerial = directCompWake & 0x000FFFFFu;
        const uint32_t handleSerial = handle & 0x000FFFFFu;
        const uint32_t serialDelta = handleSerial - wakeSerial;
        const uint32_t previousPreparedHandle =
            g_mohLevelVivMemberOpenPreparedHandleV1.load(
                std::memory_order_acquire);
        const uint32_t previousPreparedSerial =
            previousPreparedHandle & 0x000FFFFFu;
        const bool firstMemberOpen =
            previousPreparedHandle == 0u &&
            handleSerial > wakeSerial &&
            serialDelta >= 2u &&
            serialDelta <= 4u;
        const bool chainedMemberOpen =
            (previousPreparedHandle & kMohFrontendAsyncTypeMask) ==
                kMohFrontendFollowupAsyncTypeBits &&
            previousPreparedSerial > wakeSerial &&
            handleSerial > previousPreparedSerial &&
            handleSerial - previousPreparedSerial <= 4u;
        const uint32_t table =
            readGuestU32OrZero(
                rdram,
                kMohAsyncTableBaseAddr);
        const uint32_t index = (handle >> 24u) & 0xFFu;
        const uint32_t slot =
            readGuestU32OrZero(
                rdram,
                current + 0x24u);
        const uint32_t slotPool =
            readGuestU32OrZero(
                rdram,
                kMohVfsFileSlotPoolBaseAddr);
        const uint32_t slotCount =
            readGuestU32OrZero(
                rdram,
                kMohVfsFileSlotCountAddr);

        if ((directCompWake & kMohFrontendAsyncTypeMask) !=
                kMohFrontendAsyncTypeBits ||
            wakeSerial == 0u ||
            table == 0u ||
            current != table + index * kMohAsyncEntryStride ||
            (handle & kMohFrontendAsyncTypeMask) !=
                kMohFrontendFollowupAsyncTypeBits ||
            readGuestU32OrZero(rdram, current + 0x00u) != handle ||
            readGuestU32OrZero(rdram, current + 0x04u) != 0u ||
            readGuestU32OrZero(rdram, current + 0x08u) != 0u ||
            readGuestU32OrZero(rdram, current + 0x0Cu) != 0u ||
            readGuestU32OrZero(rdram, current + 0x10u) != 0x64u ||
            readGuestU32OrZero(rdram, current + 0x14u) != 0u ||
            readGuestU32OrZero(rdram, current + 0x18u) != 1u ||
            readGuestU32OrZero(rdram, current + 0x1Cu) != 0u ||
            readGuestU32OrZero(rdram, current + 0x20u) != 0u ||
            slot == 0u ||
            readGuestU32OrZero(rdram, current + 0x28u) != 0u ||
            readGuestU32OrZero(rdram, current + 0x2Cu) != 0u ||
            slotPool == 0u ||
            slotCount == 0u ||
            slot < slotPool)
        {
            return false;
        }

        const uint32_t slotDelta = slot - slotPool;
        if (slotDelta % kMohVfsFileSlotStride != 0u ||
            slotDelta / kMohVfsFileSlotStride >= slotCount ||
            readGuestU32OrZero(rdram, slot + 0x00u) != 0u ||
            readGuestU32OrZero(rdram, slot + 0x04u) != 0u ||
            readGuestU32OrZero(rdram, slot + 0x08u) != 0u)
        {
            return false;
        }

        const std::string slotPath =
            readGuestStringLimited(
                rdram,
                slot + 0x0Cu,
                128u);
        const std::string memberName =
            mohLowerAscii(
                normalizeMohCdPath(
                    slotPath));

        const bool initialDataMember =
            memberName == "6_1_art.cpt" ||
            memberName == "6_1_c.cdb";
        const bool sceneConstructionMember =
            isMohExactLevelViv6_1SceneConstructionPath(memberName);
        const bool sceneConstructionSequence =
            sceneConstructionMember &&
            handleSerial > wakeSerial &&
            (previousPreparedHandle == 0u ||
             ((previousPreparedHandle & kMohFrontendAsyncTypeMask) ==
                  kMohFrontendFollowupAsyncTypeBits &&
              previousPreparedSerial > wakeSerial &&
              handleSerial > previousPreparedSerial));
        const bool sequenceAccepted =
            initialDataMember
                ? (firstMemberOpen || chainedMemberOpen)
                : sceneConstructionSequence;

        if ((!initialDataMember && !sceneConstructionMember) ||
            !sequenceAccepted)
        {
            return false;
        }

        const uint32_t sequenceDelta =
            previousPreparedHandle == 0u
                ? serialDelta
                : handleSerial - previousPreparedSerial;

        MohBigfMember member{};
        if (!resolveMohLevelViv6_1Member(
                memberName,
                member) ||
            member.size == 0u ||
            readGuestU32OrZero(rdram, kManagerBase + 0x00u) != 0x20u ||
            readGuestU32OrZero(rdram, kManagerBase + 0x04u) != 0x10u ||
            readGuestU32OrZero(rdram, kManagerBase + 0x08u) != 0x64u ||
            readGuestU32OrZero(rdram, kManagerBase + 0x0Cu) == 0u ||
            readGuestU32OrZero(rdram, kManagerBase + 0x10u) != 0u ||
            readGuestU32OrZero(rdram, kManagerBase + 0x14u) != 0x0Fu ||
            readGuestU32OrZero(rdram, kManagerBase + 0x18u) != 0u ||
            readGuestU32OrZero(rdram, kManagerBase + 0x1Cu) != 0u ||
            readGuestU32OrZero(rdram, kManagerBase + 0x20u) != current ||
            readGuestU32OrZero(rdram, kManagerBase + 0x24u) != table ||
            readGuestU32OrZero(rdram, kManagerBase + 0x28u) != slotPool ||
            readGuestU32OrZero(rdram, kManagerBase + 0x2Cu) != 0u)
        {
            return false;
        }

        uint32_t expectedPreviousHandle = previousPreparedHandle;
        if (!g_mohLevelVivMemberOpenPreparedHandleV1.compare_exchange_strong(
                expectedPreviousHandle,
                handle,
                std::memory_order_acq_rel))
        {
            return false;
        }

        const bool stateWritten =
            writeGuestU32(
                rdram,
                slot + 0x00u,
                1u);
        const bool sizeWritten =
            stateWritten &&
            writeGuestU32(
                rdram,
                slot + 0x04u,
                member.size);

        if (!sizeWritten)
        {
            if (stateWritten)
            {
                (void)writeGuestU32(
                    rdram,
                    slot + 0x00u,
                    0u);
            }

            uint32_t expected = handle;
            (void)g_mohLevelVivMemberOpenPreparedHandleV1.compare_exchange_strong(
                expected,
                previousPreparedHandle,
                std::memory_order_acq_rel);
            return false;
        }

        ctx->r[4] = _mm_set_epi64x(0, 1);

        static std::atomic<uint32_t> sLogCount{0u};
        const uint32_t logIndex =
            sLogCount.fetch_add(
                1u,
                std::memory_order_relaxed);
        if (logIndex < 8u)
        {
            std::cerr
                << "[MOH:level-member-open-worker-prepare-v1]"
                << " idx=" << std::dec << logIndex
                << " pc=0x" << std::hex << ctx->pc
                << " ra=0x" << getRegU32(ctx, 31)
                << " handle=0x" << handle
                << " table=0x" << table
                << " entry=0x" << current
                << " operation=0x64"
                << " context=0x0"
                << " slot=0x" << slot
                << " callback=0x0"
                << " startFn=0x0"
                << " memberOffset=0x" << member.offset
                << " memberSize=0x" << member.size
                << " directCompWake=0x" << directCompWake
                << " serialDelta=0x" << serialDelta
                << " previousMemberHandle=0x"
                << previousPreparedHandle
                << " sequenceDelta=0x" << sequenceDelta
                << " managerCurrent=0x" << current
                << " managerQueue=0x0"
                << " managerDepth=0x0"
                << " managerCount=0x"
                << readGuestU32OrZero(rdram, kManagerBase + 0x0Cu)
                << " path='" << slotPath << "'"
                << " archive='" << member.archivePath.string() << "'"
                << std::dec
                << " slotState=0->1"
                << " slotSize=0->" << member.size
                << " workerResult=0->1"
                << " sequence="
                << (sceneConstructionMember
                        ? "scene-construction"
                        : (firstMemberOpen ? "first" : "chained"))
                << std::endl;
        }

        return true;
    }

    void logMohCompC0ManagerProtocolTraceV1(
        bool zeroCurrentFinish,
        const char *stage,
        const uint8_t *rdram,
        const R5900Context *ctx,
        uint32_t entryPc,
        uint32_t focusEntry,
        uint32_t callerRa,
        uint32_t finalRa,
        uint32_t result)
    {
        static std::atomic<uint32_t> sZeroCurrentLogCount{0u};
        static std::atomic<uint32_t> sNextRequestLogCount{0u};
        std::atomic<uint32_t> &counter =
            zeroCurrentFinish
                ? sZeroCurrentLogCount
                : sNextRequestLogCount;
        const uint32_t limit = zeroCurrentFinish ? 16u : 8u;
        const uint32_t index =
            counter.fetch_add(1u, std::memory_order_relaxed);
        if (index >= limit)
        {
            return;
        }

        constexpr uint32_t kManagerBase = 0x0025FC80u;
        constexpr uint32_t kDvdManagerBase = 0x0025AB10u;
        constexpr uint32_t kDvdDescriptor = 0x0025AB34u;
        constexpr uint32_t kType2PendingRequest = 0x0036B0B0u;
        const uint32_t table =
            readGuestU32OrZero(rdram, kMohAsyncTableBaseAddr);
        const uint32_t managerCurrent =
            readGuestU32OrZero(rdram, kManagerBase + 0x20u);
        const uint32_t managerQueue =
            readGuestU32OrZero(rdram, kManagerBase + 0x2Cu);
        const uint32_t trackedEntry =
            g_mohCompC0Type4TraceEntry.load(
                std::memory_order_acquire);
        if (focusEntry == 0u)
        {
            focusEntry =
                managerCurrent != 0u
                    ? managerCurrent
                    : (managerQueue != 0u
                           ? managerQueue
                           : trackedEntry);
        }

        const uint32_t handle =
            readGuestU32OrZero(rdram, focusEntry + 0x00u);
        const uint32_t context =
            readGuestU32OrZero(rdram, focusEntry + 0x14u);
        const uint32_t slot =
            readGuestU32OrZero(rdram, focusEntry + 0x24u);
        const uint32_t stackPointer = ctx ? getRegU32(ctx, 29) : 0u;
        const std::string path =
            slot != 0u
                ? readGuestStringLimited(rdram, slot + 0x0Cu, 128u)
                : std::string{};

        std::cerr
            << (zeroCurrentFinish
                    ? "[MOH:comp-c0-zero-current-finish-trace-v1]"
                    : "[MOH:comp-c0-next-request-enqueue-trace-v1]")
            << " idx=" << std::dec << index
            << " stage=" << stage
            << " pc=0x" << std::hex << entryPc
            << " nextPc=0x" << (ctx ? ctx->pc : 0u)
            << " ra=0x" << (ctx ? getRegU32(ctx, 31) : 0u)
            << " callerRa=0x" << callerRa
            << " finalRa=0x" << finalRa
            << " sp=0x" << stackPointer
            << " result=0x" << result
            << " table=0x" << table
            << " entry=0x" << focusEntry
            << " trackedEntry=0x" << trackedEntry
            << " handle=0x" << handle
            << " type=0x" << (handle & kMohFrontendAsyncTypeMask)
            << " status=0x"
            << readGuestU32OrZero(rdram, focusEntry + 0x08u)
            << " operation=0x"
            << readGuestU32OrZero(rdram, focusEntry + 0x10u)
            << " context=0x" << context
            << " offset=0x"
            << readGuestU32OrZero(rdram, focusEntry + 0x18u)
            << " chunk=0x"
            << readGuestU32OrZero(rdram, focusEntry + 0x1Cu)
            << " destination=0x"
            << readGuestU32OrZero(rdram, focusEntry + 0x20u)
            << " slot=0x" << slot
            << " callback=0x"
            << readGuestU32OrZero(rdram, focusEntry + 0x28u)
            << " startFn=0x"
            << readGuestU32OrZero(rdram, focusEntry + 0x2Cu)
            << " managerCurrent=0x" << managerCurrent
            << " managerQueue=0x" << managerQueue
            << " managerDepth=0x"
            << readGuestU32OrZero(rdram, kManagerBase + 0x10u)
            << " managerCount=0x"
            << readGuestU32OrZero(rdram, kManagerBase + 0x0Cu)
            << " type2Pending=0x"
            << readGuestU32OrZero(rdram, kType2PendingRequest)
            << " path='" << path << "'"
            << " regs=";
        if (ctx)
        {
            std::cerr << "(v0=0x" << getRegU32(ctx, 2)
                      << ",v1=0x" << getRegU32(ctx, 3)
                      << ",a0=0x" << getRegU32(ctx, 4)
                      << ",a1=0x" << getRegU32(ctx, 5)
                      << ",a2=0x" << getRegU32(ctx, 6)
                      << ",a3=0x" << getRegU32(ctx, 7)
                      << ",t0=0x" << getRegU32(ctx, 8)
                      << ",t1=0x" << getRegU32(ctx, 9)
                      << ",s0=0x" << getRegU32(ctx, 16)
                      << ",s1=0x" << getRegU32(ctx, 17)
                      << ",s2=0x" << getRegU32(ctx, 18)
                      << ",s3=0x" << getRegU32(ctx, 19)
                      << ",s4=0x" << getRegU32(ctx, 20)
                      << ",gp=0x" << getRegU32(ctx, 28)
                      << ")";
        }
        else
        {
            std::cerr << "()";
        }
        std::cerr << " entryWords=";
        logMohGuestWords(rdram, focusEntry, 12u);
        std::cerr << " contextWords=";
        logMohGuestWords(rdram, context, 16u);
        std::cerr << " managerWords=";
        logMohGuestWords(rdram, kManagerBase, 16u);
        std::cerr << " dvdManagerWords=";
        logMohGuestWords(rdram, kDvdManagerBase, 20u);
        std::cerr << " dvdDescriptorWords=";
        logMohGuestWords(rdram, kDvdDescriptor, 12u);
        std::cerr << " stackWords=";
        logMohGuestWords(rdram, stackPointer, 24u);
        std::cerr << std::dec << std::endl;
    }

