    uint32_t mohC0FbHeaderLength(const uint8_t *rdram, uint32_t archiveBase)
    {
        uint8_t b0 = 0u, b1 = 0u, b2 = 0u, b3 = 0u;
        if (!readGuestU8(rdram, archiveBase + 0u, b0) ||
            !readGuestU8(rdram, archiveBase + 1u, b1) ||
            !readGuestU8(rdram, archiveBase + 2u, b2) ||
            !readGuestU8(rdram, archiveBase + 3u, b3) ||
            b0 != 0xC0u || b1 != 0xFBu)
        {
            return 0u;
        }

        return (static_cast<uint32_t>(b2) << 8u) |
               static_cast<uint32_t>(b3) |
               4u;
    }

    void logMohCompC0ResolveTraceV1(const char *phase,
                                    const uint8_t *rdram,
                                    const R5900Context *ctx,
                                    uint32_t entryPc,
                                    const MohCompC0ResolveTraceState &state)
    {
        static std::atomic<uint32_t> s_logs{0u};
        const uint32_t index = s_logs.fetch_add(1u, std::memory_order_relaxed);
        if (index >= 32u)
        {
            return;
        }

        const uint32_t archiveHead = readGuestU32OrZero(rdram, 0x0025FCB0u);
        const uint32_t archiveBase = readGuestU32OrZero(rdram, archiveHead + 0x00u);
        const uint32_t archiveNameObject = readGuestU32OrZero(rdram, archiveHead + 0x08u);
        const uint32_t headerLength = mohC0FbHeaderLength(rdram, archiveBase);
        const uint32_t outSize = readGuestU32OrZero(rdram, state.outSizePtr);

        std::cerr << "[MOH:comp-c0-resolve-trace-v1]"
                  << " idx=" << std::dec << index
                  << " phase=" << phase
                  << " pc=0x" << std::hex << entryPc
                  << " nextPc=0x" << (ctx ? ctx->pc : 0u)
                  << " ra=0x" << (ctx ? getRegU32(ctx, 31) : 0u)
                  << " caller=0x" << state.callerRa
                  << " finalRa=0x" << state.finalRa
                  << " pathPtr=0x" << state.pathPtr
                  << " flags=0x" << state.flags
                  << " outSizePtr=0x" << state.outSizePtr
                  << " outSize=0x" << outSize
                  << " ret=0x" << (ctx ? getRegU32(ctx, 2) : 0u)
                  << " archiveHead=0x" << archiveHead
                  << " node=0x" << archiveHead
                  << " archiveBase=0x" << archiveBase
                  << " headerWord=0x" << readGuestU32OrZero(rdram, archiveBase)
                  << " headerLength=0x" << headerLength
                  << " headerEnd=0x" << (archiveBase + headerLength)
                  << " nextNode=0x" << readGuestU32OrZero(rdram, archiveHead + 0x10u)
                  << " path='" << state.path << "'"
                  << " archivePath='"
                  << readGuestStringLimited(rdram, archiveNameObject + 0x0Cu, 128u)
                  << "'";
        logMohVfsManagerState(rdram, "mgr");
        std::cerr << std::dec << std::endl;
    }

    void mohCompC0ArchiveResolve1f51f8Trace(uint8_t *rdram,
                                            R5900Context *ctx,
                                            PS2Runtime *runtime)
    {
        const uint32_t entryPc = ctx ? ctx->pc : 0u;
        if (ctx && entryPc == 0x001F51F8u)
        {
            const std::string path =
                readGuestStringLimited(rdram, getRegU32(ctx, 4), 128u);
            if (isMohExactCompC0ArtPath(path))
            {
                g_mohCompC0ResolveTrace.active = true;
                g_mohCompC0ResolveTrace.pathPtr = getRegU32(ctx, 4);
                g_mohCompC0ResolveTrace.flags = getRegU32(ctx, 5);
                g_mohCompC0ResolveTrace.outSizePtr = getRegU32(ctx, 6);
                g_mohCompC0ResolveTrace.callerRa = getRegU32(ctx, 31);
                g_mohCompC0ResolveTrace.finalRa = getRegU32(ctx, 31);
                g_mohCompC0ResolveTrace.path = path;
            }
        }

        const bool tracked = g_mohCompC0ResolveTrace.active;
        if (tracked)
        {
            logMohCompC0ResolveTraceV1(
                "before", rdram, ctx, entryPc, g_mohCompC0ResolveTrace);
        }

        if (g_mohOriginalArchiveResolve1f51f8 &&
            g_mohOriginalArchiveResolve1f51f8 != &mohCompC0ArchiveResolve1f51f8Trace)
        {
            g_mohOriginalArchiveResolve1f51f8(rdram, ctx, runtime);
        }
        else if (ctx)
        {
            ctx->pc = g_mohCompC0ResolveTrace.finalRa != 0u
                          ? g_mohCompC0ResolveTrace.finalRa
                          : getRegU32(ctx, 31);
        }

        if (tracked)
        {
            logMohCompC0ResolveTraceV1(
                "after", rdram, ctx, entryPc, g_mohCompC0ResolveTrace);
            if (ctx && ctx->pc == g_mohCompC0ResolveTrace.finalRa)
            {
                g_mohCompC0ResolveTrace = {};
            }
        }
    }

    void logMohCompC0MemberTraceV1(const char *phase,
                                   const uint8_t *rdram,
                                   const R5900Context *ctx,
                                   uint32_t entryPc,
                                   const MohCompC0MemberTraceState &state)
    {
        static std::atomic<uint32_t> s_logs{0u};
        const uint32_t index = s_logs.fetch_add(1u, std::memory_order_relaxed);
        if (index >= 32u)
        {
            return;
        }

        const uint32_t headerLength = mohC0FbHeaderLength(rdram, state.archiveBase);
        std::cerr << "[MOH:comp-c0-member-lookup-trace-v1]"
                  << " idx=" << std::dec << index
                  << " phase=" << phase
                  << " pc=0x" << std::hex << entryPc
                  << " nextPc=0x" << (ctx ? ctx->pc : 0u)
                  << " ra=0x" << (ctx ? getRegU32(ctx, 31) : 0u)
                  << " caller=0x" << state.callerRa
                  << " finalRa=0x" << state.finalRa
                  << " archiveBase=0x" << state.archiveBase
                  << " headerWord=0x" << readGuestU32OrZero(rdram, state.archiveBase)
                  << " headerLength=0x" << headerLength
                  << " headerEnd=0x" << (state.archiveBase + headerLength)
                  << " firstEntry=0x" << (state.archiveBase + 6u)
                  << " memberPtr=0x" << state.memberPtr
                  << " requestedIndex=0x" << state.requestedIndex
                  << " outOffsetPtr=0x" << state.outOffsetPtr
                  << " outOffset=0x" << readGuestU32OrZero(rdram, state.outOffsetPtr)
                  << " outSizePtr=0x" << state.outSizePtr
                  << " outSize=0x" << readGuestU32OrZero(rdram, state.outSizePtr)
                  << " ret=0x" << (ctx ? getRegU32(ctx, 2) : 0u)
                  << " member='" << state.member << "'";
        logMohVfsManagerState(rdram, "mgr");
        std::cerr << std::dec << std::endl;
    }

    void mohCompC0ArchiveMemberLookup1f5788Trace(uint8_t *rdram,
                                                 R5900Context *ctx,
                                                 PS2Runtime *runtime)
    {
        const uint32_t entryPc = ctx ? ctx->pc : 0u;
        if (ctx && entryPc == 0x001F5788u)
        {
            const std::string member =
                readGuestStringLimited(rdram, getRegU32(ctx, 5), 128u);
            if (isMohExactCompC0ArtPath(member))
            {
                g_mohCompC0MemberTrace.active = true;
                g_mohCompC0MemberTrace.archiveBase = getRegU32(ctx, 4);
                g_mohCompC0MemberTrace.memberPtr = getRegU32(ctx, 5);
                g_mohCompC0MemberTrace.requestedIndex = getRegU32(ctx, 6);
                g_mohCompC0MemberTrace.outOffsetPtr = getRegU32(ctx, 7);
                g_mohCompC0MemberTrace.outSizePtr = getRegU32(ctx, 8);
                g_mohCompC0MemberTrace.callerRa = getRegU32(ctx, 31);
                g_mohCompC0MemberTrace.finalRa = getRegU32(ctx, 31);
                g_mohCompC0MemberTrace.member = member;
            }
        }

        const bool tracked = g_mohCompC0MemberTrace.active;
        if (tracked)
        {
            logMohCompC0MemberTraceV1(
                "before", rdram, ctx, entryPc, g_mohCompC0MemberTrace);
        }

        if (g_mohOriginalArchiveMemberLookup1f5788 &&
            g_mohOriginalArchiveMemberLookup1f5788 != &mohCompC0ArchiveMemberLookup1f5788Trace)
        {
            g_mohOriginalArchiveMemberLookup1f5788(rdram, ctx, runtime);
        }
        else if (ctx)
        {
            ctx->pc = g_mohCompC0MemberTrace.finalRa != 0u
                          ? g_mohCompC0MemberTrace.finalRa
                          : getRegU32(ctx, 31);
        }

        if (tracked)
        {
            logMohCompC0MemberTraceV1(
                "after", rdram, ctx, entryPc, g_mohCompC0MemberTrace);
            if (ctx && ctx->pc == g_mohCompC0MemberTrace.finalRa)
            {
                g_mohCompC0MemberTrace = {};
            }
        }
    }

    void logMohCompC0OpenLifecycleV1(const char *phase,
                                     const uint8_t *rdram,
                                     const R5900Context *ctx,
                                     uint32_t entryPc,
                                     uint32_t entry,
                                     uint32_t handle,
                                     const MohCompC0OpenTraceState &state)
    {
        static std::atomic<uint32_t> s_logs{0u};
        const uint32_t index = s_logs.fetch_add(1u, std::memory_order_relaxed);
        if (index >= 32u)
        {
            return;
        }

        const uint32_t entryHandle = readGuestU32OrZero(rdram, entry);
        std::cerr << "[MOH:comp-c0-open-lifecycle-v1]"
                  << " idx=" << std::dec << index
                  << " phase=" << phase
                  << " pc=0x" << std::hex << entryPc
                  << " nextPc=0x" << (ctx ? ctx->pc : 0u)
                  << " ra=0x" << (ctx ? getRegU32(ctx, 31) : 0u)
                  << " caller=0x" << state.callerRa
                  << " finalRa=0x" << state.finalRa
                  << " sp=0x" << (ctx ? getRegU32(ctx, 29) : 0u)
                  << " entry=0x" << entry
                  << " entryHandle=0x" << entryHandle
                  << " handle=0x" << handle
                  << " path='" << state.path << "'"
                  << " entryWords=";
        logMohGuestWords(rdram, entry, 12u);
        if (entryHandle != 0u)
        {
            logMohVfsHandleSnapshot(rdram, entryHandle, "entrySnapshot");
        }
        else if (handle != 0u)
        {
            logMohVfsHandleSnapshot(rdram, handle, "handleSnapshot");
        }
        logMohVfsManagerState(rdram, "mgr");
        std::cerr << std::dec << std::endl;
    }

    void mohVfsCreate1f4270Trace(uint8_t *rdram, R5900Context *ctx, PS2Runtime *runtime)
    {
        mohHeapCanaryCheck(rdram, ctx, "vfs4270");
        const uint32_t entryPc = ctx ? ctx->pc : 0u;
        const uint32_t a0 = getRegU32(ctx, 4);
        const uint32_t a1 = getRegU32(ctx, 5);
        const uint32_t a2 = getRegU32(ctx, 6);
        const uint32_t a3 = getRegU32(ctx, 7);
        const uint32_t ra = getRegU32(ctx, 31);
        const uint32_t liveS3 = getRegU32(ctx, 19);
        const uint32_t liveS4 = getRegU32(ctx, 20);
        const std::string path = readGuestStringLimited(rdram, a0, 128u);
        const std::string compC0Path =
            entryPc == 0x001F4270u
                ? path
                : readGuestStringLimited(rdram, liveS4, 128u);
        const bool traceCompC0CdbCreate =
            isMohExactCompC0CdbPath(compC0Path);
        const bool trackCompC1CdbCreate =
            entryPc == 0x001F4270u &&
            isMohExactCompC1CdbPath(compC0Path);
        const uint32_t compC0CdbEntryBefore =
            entryPc == 0x001F4270u
                ? 0u
                : (entryPc == 0x001F42A0u
                       ? getRegU32(ctx, 2)
                       : liveS3);
        if (traceCompC0CdbCreate)
        {
            logMohCompC0CdbOpenProtocolTraceV1(
                "create-before-original",
                rdram,
                ctx,
                entryPc,
                compC0CdbEntryBefore != 0u
                    ? readGuestU32OrZero(
                          rdram,
                          compC0CdbEntryBefore + 0x00u)
                    : 0u,
                compC0CdbEntryBefore,
                compC0Path);
        }
        if (entryPc == 0x001F4270u && isMohExactCompC0ArtPath(compC0Path))
        {
            g_mohCompC0RequestSeenV1.store(true, std::memory_order_release);
            g_mohCompC0OpenTrace.active = true;
            g_mohCompC0OpenTrace.callerRa = ra;
            g_mohCompC0OpenTrace.finalRa = ra;
            g_mohCompC0OpenTrace.entry = 0u;
            g_mohCompC0OpenTrace.path = compC0Path;
        }
        const bool trackedCompC0Open = g_mohCompC0OpenTrace.active;
        uint32_t compC0EntryBefore = g_mohCompC0OpenTrace.entry;
        if (trackedCompC0Open && entryPc == 0x001F42A0u)
        {
            compC0EntryBefore = getRegU32(ctx, 2);
        }
        else if (trackedCompC0Open && entryPc != 0x001F4270u)
        {
            compC0EntryBefore = liveS3;
        }
        if (trackedCompC0Open)
        {
            logMohCompC0OpenLifecycleV1(
                "before",
                rdram,
                ctx,
                entryPc,
                compC0EntryBefore,
                readGuestU32OrZero(rdram, compC0EntryBefore),
                g_mohCompC0OpenTrace);
        }
        const bool exactCompTransition =
            entryPc == 0x001F4270u &&
            ra == 0x001F4934u &&
            isMohExactCompViv6_1Path(path);
        const uint32_t wrapperEntry =
            exactCompTransition
                ? readGuestU32OrZero(
                      rdram,
                      a3 + 0x0Cu)
                : 0u;
        const uint32_t wrapperHandle =
            readGuestU32OrZero(
                rdram,
                wrapperEntry + 0x00u);

        if (exactCompTransition &&
            (wrapperHandle & kMohFrontendAsyncTypeMask) ==
                kMohCompositeAsyncTypeBits)
        {
            g_mohHandle9TraceHandle.store(
                wrapperHandle,
                std::memory_order_release);
            g_mohHandle9TraceEntry.store(
                wrapperEntry,
                std::memory_order_release);
            g_mohHandle9TraceContext.store(
                a3,
                std::memory_order_release);

            logMohHandle9TraceV1(
                "[MOH:comp-viv-transition-v1]",
                "child-open-before",
                rdram,
                ctx,
                entryPc,
                wrapperHandle,
                wrapperEntry,
                path,
                ra);
        }

        const bool entryInteresting = isMohVfsInterestingName(path) ||
                                      ra == 0x001F257Cu ||
                                      entryPc == 0x001F4304u;

        if (g_mohOriginalVfsCreate1f4270 && g_mohOriginalVfsCreate1f4270 != &mohVfsCreate1f4270Trace)
        {
            g_mohOriginalVfsCreate1f4270(rdram, ctx, runtime);
        }
        else if (ctx)
        {
            ctx->pc = getRegU32(ctx, 31);
        }

        const uint32_t ret = ctx ? getRegU32(ctx, 2) : 0u;
        MohVfsHandleSnapshot compC1CdbOpenSnapshot{};
        const bool compC1CdbHandlePublished =
            trackCompC1CdbCreate &&
            (ret & kMohFrontendAsyncTypeMask) ==
                kMohFrontendFollowupAsyncTypeBits &&
            readMohVfsHandleSnapshot(
                rdram,
                ret,
                compC1CdbOpenSnapshot) &&
            isMohExactCompC1CdbPath(
                compC1CdbOpenSnapshot.path);
        if (compC1CdbHandlePublished)
        {
            g_mohCompC1CdbOpenEntryV1.store(
                compC1CdbOpenSnapshot.entryAddr,
                std::memory_order_release);
            g_mohCompC1CdbOpenSlotV1.store(
                compC1CdbOpenSnapshot.slotAddr,
                std::memory_order_release);
            g_mohCompC1CdbOpenHandleV1.store(
                ret,
                std::memory_order_release);
        }
        MohVfsHandleSnapshot compC0CdbOpenSnapshot{};
        const bool compC0CdbHandlePublished =
            traceCompC0CdbCreate &&
            (ret & kMohFrontendAsyncTypeMask) ==
                kMohFrontendFollowupAsyncTypeBits &&
            readMohVfsHandleSnapshot(
                rdram,
                ret,
                compC0CdbOpenSnapshot) &&
            isMohExactCompC0CdbPath(
                compC0CdbOpenSnapshot.path);
        if (compC0CdbHandlePublished)
        {
            g_mohCompC0CdbOpenEntryV1.store(
                compC0CdbOpenSnapshot.entryAddr,
                std::memory_order_release);
            g_mohCompC0CdbOpenSlotV1.store(
                compC0CdbOpenSnapshot.slotAddr,
                std::memory_order_release);
            g_mohCompC0CdbOpenHandleV1.store(
                ret,
                std::memory_order_release);
        }
        if (traceCompC0CdbCreate)
        {
            logMohCompC0CdbOpenProtocolTraceV1(
                "create-after-original",
                rdram,
                ctx,
                entryPc,
                compC0CdbHandlePublished ? ret : 0u,
                compC0CdbHandlePublished
                    ? compC0CdbOpenSnapshot.entryAddr
                    : compC0CdbEntryBefore,
                compC0Path);
        }

        if (trackedCompC0Open)
        {
            const bool final = ctx && ctx->pc == g_mohCompC0OpenTrace.finalRa;
            uint32_t compC0EntryAfter = g_mohCompC0OpenTrace.entry;
            if (!final && getRegU32(ctx, 19) != 0u)
            {
                compC0EntryAfter = getRegU32(ctx, 19);
                g_mohCompC0OpenTrace.entry = compC0EntryAfter;
            }
            logMohCompC0OpenLifecycleV1(
                final ? "final" : "after",
                rdram,
                ctx,
                entryPc,
                compC0EntryAfter,
                final ? ret : readGuestU32OrZero(rdram, compC0EntryAfter),
                g_mohCompC0OpenTrace);
            if (final)
            {
                g_mohCompC0OpenTrace = {};
            }
        }

        if ((ret & kMohFrontendAsyncTypeMask) ==
                kMohFrontendFollowupAsyncTypeBits &&
            g_mohLevelViv6_1Active.load(
                std::memory_order_acquire))
        {
            MohVfsHandleSnapshot audioOpen{};
            if (readMohVfsHandleSnapshot(
                    rdram,
                    ret,
                    audioOpen) &&
                audioOpen.entryWords[2] == 1u &&
                audioOpen.entryWords[4] == 0x64u &&
                audioOpen.entryWords[5] == 0u &&
                audioOpen.entryWords[6] == 1u &&
                audioOpen.entryWords[10] == 0u &&
                audioOpen.entryWords[11] == 0u &&
                audioOpen.slotAddr != 0u &&
                (audioOpen.slotWords[0] >> 24u) == 1u &&
                audioOpen.slotWords[1] != 0u &&
                audioOpen.slotWords[2] == 0u)
            {
                if (isMohExactLevel6_1MovBankPath(audioOpen.path))
                {
                    g_mohLevelAudioOpenHandleV1.store(
                        ret,
                        std::memory_order_release);
                }
                else if (isMohExactLevel6_1GunBankPath(audioOpen.path))
                {
                    g_mohLevelGunBankOpenHandleV1.store(
                        ret,
                        std::memory_order_release);
                    g_mohLevelGunBankReadWakeHandleV1.store(
                        0u,
                        std::memory_order_release);
                }
                else if (isMohExactLevel6_1ImpBankPath(audioOpen.path))
                {
                    g_mohLevelImpBankOpenHandleV1.store(
                        ret,
                        std::memory_order_release);
                    g_mohLevelImpBankReadWakeHandleV1.store(
                        0u,
                        std::memory_order_release);
                }
                else if (isMohLevel6_1AudioBankPath(audioOpen.path))
                {
                    g_mohLevelBankOpenHandleV1.store(
                        ret,
                        std::memory_order_release);
                    g_mohLevelBankReadWakeHandleV1.store(
                        0u,
                        std::memory_order_release);
                }
            }
        }

        if (exactCompTransition &&
            (ret & kMohFrontendAsyncTypeMask) ==
                kMohFrontendFollowupAsyncTypeBits)
        {
            const uint32_t table =
                readGuestU32OrZero(
                    rdram,
                    kMohAsyncTableBaseAddr);
            const uint32_t childEntry =
                table +
                ((ret >> 24u) & 0xFFu) *
                    kMohAsyncEntryStride;

            g_mohHandle9TraceChildHandle.store(
                ret,
                std::memory_order_release);
            g_mohHandle9TraceChildEntry.store(
                childEntry,
                std::memory_order_release);

            logMohHandle9TraceV1(
                "[MOH:comp-viv-transition-v1]",
                "child-open-after",
                rdram,
                ctx,
                entryPc,
                ret,
                childEntry,
                path,
                ra);
        }

        // MOH_LOADING_SSH_HOST_SIZE_V2
        //
        // Les fichiers SHPS existent sur l'hôte, mais le slot VFS
        // reste à taille zéro. Publier leur taille réelle juste après
        // la création du handle, avant les appels à 1F2558/1F19F0.
        if (entryPc == 0x001F4270u &&
            ret != 0u &&
            (
                isMohLoadingSshPath(path)
            ))
        {
            MohVfsHandleSnapshot sshSnap{};

            const bool snapshotValid =
                readMohVfsHandleSnapshot(
                    rdram,
                    ret,
                    sshSnap) &&
                sshSnap.entryWords[0] == ret &&
                sshSnap.slotAddr != 0u &&
                (
                    isMohLoadingSshPath(sshSnap.path)
                );

            std::filesystem::path hostPath;

            const bool resolved =
                snapshotValid &&
                resolveMohHostFilePath(
                    sshSnap.path,
                    hostPath);

            std::error_code sizeError;
            uint64_t hostSize64 = 0u;

            if (resolved)
            {
                hostSize64 =
                    static_cast<uint64_t>(
                        std::filesystem::file_size(
                            hostPath,
                            sizeError));
            }

            const bool sizeValid =
                resolved &&
                !sizeError &&
                hostSize64 >= 8u &&
                hostSize64 <= 0xFFFFFFFFull;

            std::array<uint8_t, 8> header{};

            const bool headerRead =
                sizeValid &&
                readMohHostFileRange(
                    hostPath,
                    0u,
                    header.data(),
                    static_cast<uint32_t>(
                        header.size()));

            const uint32_t magic =
                static_cast<uint32_t>(header[0]) |
                (static_cast<uint32_t>(header[1]) << 8u) |
                (static_cast<uint32_t>(header[2]) << 16u) |
                (static_cast<uint32_t>(header[3]) << 24u);

            const uint32_t headerSize =
                static_cast<uint32_t>(header[4]) |
                (static_cast<uint32_t>(header[5]) << 8u) |
                (static_cast<uint32_t>(header[6]) << 16u) |
                (static_cast<uint32_t>(header[7]) << 24u);

            const uint32_t hostSize =
                sizeValid
                    ? static_cast<uint32_t>(hostSize64)
                    : 0u;

            const bool exactShps =
                headerRead &&
                magic == 0x53504853u &&
                headerSize == hostSize;

            const uint32_t oldSize =
                snapshotValid
                    ? readGuestU32OrZero(
                          rdram,
                          sshSnap.slotAddr + 0x04u)
                    : 0u;

            bool sizeWritten = false;
            bool ready = false;

            if (exactShps &&
                oldSize == 0u)
            {
                sizeWritten =
                    writeGuestU32(
                        rdram,
                        sshSnap.slotAddr + 0x04u,
                        hostSize);

                ready = sizeWritten;
            }
            else if (exactShps &&
                     oldSize == hostSize)
            {
                ready = true;
            }

            static uint32_t sshSizeLogs = 0u;

            if (sshSizeLogs < 32u)
            {
                std::cerr
                    << (ready
                            ? "[MOH:loading-ssh-size-ready-v2]"
                            : "[MOH:loading-ssh-size-reject-v2]")
                    << " handle=0x" << std::hex << ret
                    << " entry=0x" << sshSnap.entryAddr
                    << " slot=0x" << sshSnap.slotAddr
                    << " oldSize=0x" << oldSize
                    << " hostSize=0x" << hostSize
                    << " headerSize=0x" << headerSize
                    << " magic=0x" << magic
                    << " path='" << sshSnap.path << "'"
                    << " host='" << hostPath.string() << "'"
                    << std::dec
                    << " snapshotValid="
                    << (snapshotValid ? 1 : 0)
                    << " resolved="
                    << (resolved ? 1 : 0)
                    << " headerRead="
                    << (headerRead ? 1 : 0)
                    << " sizeWritten="
                    << (sizeWritten ? 1 : 0)
                    << std::endl;

                ++sshSizeLogs;
            }
        }

        const bool interesting = entryInteresting || isMohVfsInterestingHandle(rdram, ret);
        static std::atomic<uint32_t> s_log{0};
        const uint32_t idx = s_log.fetch_add(1u, std::memory_order_relaxed);
        if ((interesting && idx < 256u) || (ret == 0u && entryInteresting))
        {
            std::cerr << "[MOH:vfs4270]"
                      << " idx=" << std::dec << idx
                      << " pc=0x" << std::hex << entryPc
                      << " ra=0x" << ra
                      << " a0=0x" << a0
                      << " a1=0x" << a1
                      << " a2=0x" << a2
                      << " a3=0x" << a3
                      << " path='" << path << "'"
                      << " liveS3=0x" << liveS3
                      << " liveS4=0x" << liveS4
                      << " ret=0x" << ret
                      << " nextPc=0x" << (ctx ? ctx->pc : 0u);
            logMohVfsHandleSnapshot(rdram, ret, "handle");
            if (entryPc == 0x001F4304u && liveS3 != 0u)
            {
                uint32_t resumeHandle = 0u;
                (void)readGuestU32(rdram, liveS3, resumeHandle);
                logMohVfsHandleSnapshot(rdram, resumeHandle, "resumeHandle");
            }
            logMohVfsManagerState(rdram, "mgr");
            std::cerr << std::dec << std::endl;
        }
    }

    std::atomic<uint32_t> g_mohLevelMainExitCauseV1{0u};

    void logMohLevelMainExitTraceV1(const char *phase,
                                    const uint8_t *rdram,
                                    const R5900Context *ctx,
                                    uint32_t entryPc)
    {
        static std::atomic<uint32_t> s_logs{0u};
        const uint32_t index = s_logs.fetch_add(1u, std::memory_order_relaxed);
        if (index >= 32u)
        {
            return;
        }

        uint8_t exitByte = 0u;
        (void)readGuestU8(rdram, 0x0023FA47u, exitByte);
        std::cerr << "[MOH:level-main-exit-predicate-trace-v1]"
                  << " idx=" << std::dec << index
                  << " phase=" << phase
                  << " pc=0x" << std::hex << entryPc
                  << " nextPc=0x" << (ctx ? ctx->pc : 0u)
                  << " ra=0x" << (ctx ? getRegU32(ctx, 31) : 0u)
                  << " sp=0x" << (ctx ? getRegU32(ctx, 29) : 0u)
                  << " v0=0x" << (ctx ? getRegU32(ctx, 2) : 0u)
                  << " s0=0x" << (ctx ? getRegU32(ctx, 16) : 0u)
                  << " exitByte=0x" << static_cast<uint32_t>(exitByte)
                  << " flags=0x" << readGuestU32OrZero(rdram, 0x00240F54u)
                  << " cause=0x" << g_mohLevelMainExitCauseV1.load(std::memory_order_acquire)
                  << " levelTaskState=0x" << readGuestU32OrZero(rdram, 0x00241830u);
        logMohVfsManagerState(rdram, "mgr");
        std::cerr << std::dec << std::endl;
    }

    void mohLevelMainExitPredicateTrace(uint8_t *rdram,
                                        R5900Context *ctx,
                                        PS2Runtime *runtime)
    {
        const uint32_t entryPc = ctx ? ctx->pc : 0u;
        if (ctx && entryPc == 0x0010B528u && getRegU32(ctx, 16) != 0u)
        {
            g_mohLevelMainExitCauseV1.store(1u, std::memory_order_release);
        }
        else if (ctx && entryPc == 0x0010B53Cu && getRegU32(ctx, 2) != 0u)
        {
            g_mohLevelMainExitCauseV1.store(2u, std::memory_order_release);
        }

        logMohLevelMainExitTraceV1("before", rdram, ctx, entryPc);
        if (g_mohOriginalLevelMain10a838 &&
            g_mohOriginalLevelMain10a838 != &mohLevelMainExitPredicateTrace)
        {
            g_mohOriginalLevelMain10a838(rdram, ctx, runtime);
        }
        else if (ctx)
        {
            ctx->pc = getRegU32(ctx, 31);
        }
        logMohLevelMainExitTraceV1("after", rdram, ctx, entryPc);
    }

    struct MohLevelExit194ba8TraceState
    {
        bool active = false;
        uint32_t argument = 0u;
        uint32_t callerRa = 0u;
        uint32_t finalRa = 0u;
    };

    thread_local MohLevelExit194ba8TraceState g_mohLevelExit194ba8Trace{};

    void logMohLevelExit194ba8TraceV1(const char *phase,
                                      const uint8_t *rdram,
                                      const R5900Context *ctx,
                                      uint32_t entryPc,
                                      const MohLevelExit194ba8TraceState &state)
    {
        static std::atomic<uint32_t> s_logs{0u};
        const uint32_t index = s_logs.fetch_add(1u, std::memory_order_relaxed);
        if (index >= 16u)
        {
            return;
        }

        uint8_t exitByte = 0u;
        (void)readGuestU8(rdram, 0x0023FA47u, exitByte);
        std::cerr << "[MOH:level-exit-194ba8-trace-v1]"
                  << " idx=" << std::dec << index
                  << " phase=" << phase
                  << " pc=0x" << std::hex << entryPc
                  << " nextPc=0x" << (ctx ? ctx->pc : 0u)
                  << " ra=0x" << (ctx ? getRegU32(ctx, 31) : 0u)
                  << " caller=0x" << state.callerRa
                  << " finalRa=0x" << state.finalRa
                  << " argument=0x" << state.argument
                  << " argumentWord=0x" << readGuestU32OrZero(rdram, state.argument)
                  << " exitByte=0x" << static_cast<uint32_t>(exitByte)
                  << " flags=0x" << readGuestU32OrZero(rdram, 0x00240F54u)
                  << " tableBase=0x" << readGuestU32OrZero(rdram, 0x00244A3Cu)
                  << " tableIndex=0x" << readGuestU32OrZero(rdram, 0x00244A40u)
                  << " levelTaskState=0x" << readGuestU32OrZero(rdram, 0x00241830u)
                  << std::dec << std::endl;
    }

    void mohLevelExit194ba8Trace(uint8_t *rdram,
                                 R5900Context *ctx,
                                 PS2Runtime *runtime)
    {
        const uint32_t entryPc = ctx ? ctx->pc : 0u;
        if (ctx && entryPc == 0x00194BA8u)
        {
            g_mohLevelExit194ba8Trace.active = true;
            g_mohLevelExit194ba8Trace.argument = getRegU32(ctx, 4);
            g_mohLevelExit194ba8Trace.callerRa = getRegU32(ctx, 31);
            g_mohLevelExit194ba8Trace.finalRa = getRegU32(ctx, 31);
        }

        const bool tracked = g_mohLevelExit194ba8Trace.active;
        if (tracked)
        {
            logMohLevelExit194ba8TraceV1(
                "before", rdram, ctx, entryPc, g_mohLevelExit194ba8Trace);
        }

        if (g_mohOriginalLevelExit194ba8 &&
            g_mohOriginalLevelExit194ba8 != &mohLevelExit194ba8Trace)
        {
            g_mohOriginalLevelExit194ba8(rdram, ctx, runtime);
        }
        else if (ctx)
        {
            ctx->pc = g_mohLevelExit194ba8Trace.finalRa != 0u
                          ? g_mohLevelExit194ba8Trace.finalRa
                          : getRegU32(ctx, 31);
        }

        if (tracked)
        {
            logMohLevelExit194ba8TraceV1(
                "after", rdram, ctx, entryPc, g_mohLevelExit194ba8Trace);
            if (ctx && ctx->pc == g_mohLevelExit194ba8Trace.finalRa)
            {
                g_mohLevelExit194ba8Trace = {};
            }
        }
    }

    void mohCall112030Trace(uint8_t *rdram, R5900Context *ctx, PS2Runtime *runtime)
    {
        const uint32_t entryPc = ctx ? ctx->pc : 0u;
        const uint32_t a0 = getRegU32(ctx, 4);
        const uint32_t a1 = getRegU32(ctx, 5);
        const uint32_t a2 = getRegU32(ctx, 6);
        const uint32_t a3 = getRegU32(ctx, 7);
        const uint32_t sp = getRegU32(ctx, 29);
        const uint32_t liveRa = getRegU32(ctx, 31);
        uint32_t savedRa = 0u;
        if (entryPc == 0x00112078u)
        {
            (void)readGuestU32(rdram, sp, savedRa);
        }
        const uint32_t callerRa = savedRa != 0u ? savedRa : liveRa;

        auto fbits = [](float value)
        {
            uint32_t bits = 0u;
            std::memcpy(&bits, &value, sizeof(bits));
            return bits;
        };

        const float f0 = ctx ? ctx->f[0] : 0.0f;
        const float f12 = ctx ? ctx->f[12] : 0.0f;
        const float f13 = ctx ? ctx->f[13] : 0.0f;
        const float f20 = ctx ? ctx->f[20] : 0.0f;
        const float f21 = ctx ? ctx->f[21] : 0.0f;
        const float f23 = ctx ? ctx->f[23] : 0.0f;
        const float f25 = ctx ? ctx->f[25] : 0.0f;
        const uint32_t f12Bits = fbits(f12);
        const uint32_t f13Bits = fbits(f13);

        uint32_t style = 0u;
        (void)readGuestU32(rdram, a1, style);

        constexpr uint32_t kPacketAddr = 0x00332628u;
        uint32_t packetObjBefore = 0u;
        uint32_t packetF12Before = 0u;
        uint32_t packetF13Before = 0u;
        uint32_t packetStyleBefore = 0u;
        (void)readGuestU32(rdram, kPacketAddr + 0x00u, packetObjBefore);
        (void)readGuestU32(rdram, kPacketAddr + 0x14u, packetF12Before);
        (void)readGuestU32(rdram, kPacketAddr + 0x18u, packetF13Before);
        (void)readGuestU32(rdram, kPacketAddr + 0x1Cu, packetStyleBefore);

        const bool knownCaller = callerRa == 0x00144D30u ||
                                 callerRa == 0x001DAD2Cu ||
                                 callerRa == 0x001DAE68u ||
                                 callerRa == 0x001DB004u;
        const bool badPlacement = f12Bits == 0xC3340000u && f13Bits == 0x429E0000u;
        const bool targetObject = a0 == 0x01FBF6D0u || packetObjBefore == 0x01FBF6D0u;
        const bool interesting = knownCaller || badPlacement || targetObject || entryPc == 0x00112078u;

        MohRenderRangeSummary buf4841Before{};
        MohRenderRangeSummary buf5052Before{};
        uint32_t traceIndex = UINT32_MAX;
        if (interesting)
        {
            buf4841Before = summarizeMohRenderRange(rdram, 0x00484100u, 0x00484300u);
            buf5052Before = summarizeMohRenderRange(rdram, 0x00505200u, 0x00505400u);

            static std::atomic<uint32_t> s_traceCount{0u};
            traceIndex = s_traceCount.fetch_add(1u, std::memory_order_relaxed);
            const bool buffersStillClean = !buf4841Before.hitTarget && !buf5052Before.hitTarget;
            if (traceIndex < 64u || buffersStillClean)
            {
                uint32_t a0Vtable = 0u;
                (void)readGuestU32(rdram, a0 + 0x20u, a0Vtable);
                std::cerr << "[MOH:call112030:enter]"
                          << " idx=" << std::dec << traceIndex
                          << " pc=0x" << std::hex << entryPc
                          << " caller=" << mohCall112030CallerName(callerRa)
                          << " callerRa=0x" << callerRa
                          << " liveRa=0x" << liveRa
                          << " savedRa=0x" << savedRa
                          << " a0=0x" << a0
                          << " a1=0x" << a1
                          << " a2=0x" << a2
                          << " a3=0x" << a3
                          << " sp=0x" << sp
                          << " style=0x" << style
                          << " f0=" << std::dec << f0
                          << " f12=" << f12
                          << " f13=" << f13
                          << " f20=" << f20
                          << " f21=" << f21
                          << " f23=" << f23
                          << " f25=" << f25
                          << " f12Bits=0x" << std::hex << f12Bits
                          << " f13Bits=0x" << f13Bits
                          << " a0Vtable=0x" << a0Vtable
                          << " chain=" << ::mohDispatchHistory()
                          << " a0w";
                logMohWords(rdram, a0, {0x00u, 0x04u, 0x08u, 0x0Cu, 0x10u, 0x14u,
                                        0x18u, 0x1Cu, 0x20u, 0x24u, 0x28u, 0x2Cu,
                                        0x30u, 0x34u, 0x38u, 0x3Cu, 0x40u, 0x44u,
                                        0x48u, 0x4Cu, 0x50u});
                std::cerr << " a1w";
                logMohWords(rdram, a1, {0x00u, 0x04u, 0x08u, 0x0Cu});
                std::cerr << " callerStack";
                logMohWords(rdram, sp, {0x00u, 0x30u, 0x190u, 0x1E8u, 0x1F0u});
                std::cerr << " packetBefore";
                logMohWords(rdram, kPacketAddr, {0x00u, 0x04u, 0x08u, 0x0Cu, 0x10u,
                                                 0x14u, 0x18u, 0x1Cu, 0x20u});
                std::cerr << " buf4841Pre";
                logMohRenderSummary(buf4841Before);
                std::cerr << " buf5052Pre";
                logMohRenderSummary(buf5052Before);
                std::cerr << std::dec << std::endl;
            }
        }

        if (g_mohOriginalCall112030 && g_mohOriginalCall112030 != &mohCall112030Trace)
        {
            g_mohOriginalCall112030(rdram, ctx, runtime);
        }
        else if (ctx)
        {
            ctx->pc = callerRa;
        }

        if (!interesting)
        {
            return;
        }

        uint32_t packetObjAfter = 0u;
        uint32_t packetF12After = 0u;
        uint32_t packetF13After = 0u;
        uint32_t packetStyleAfter = 0u;
        (void)readGuestU32(rdram, kPacketAddr + 0x00u, packetObjAfter);
        (void)readGuestU32(rdram, kPacketAddr + 0x14u, packetF12After);
        (void)readGuestU32(rdram, kPacketAddr + 0x18u, packetF13After);
        (void)readGuestU32(rdram, kPacketAddr + 0x1Cu, packetStyleAfter);

        const MohRenderRangeSummary buf4841After = summarizeMohRenderRange(rdram, 0x00484100u, 0x00484300u);
        const MohRenderRangeSummary buf5052After = summarizeMohRenderRange(rdram, 0x00505200u, 0x00505400u);
        const bool becameHit = (!buf4841Before.hitTarget && buf4841After.hitTarget) ||
                               (!buf5052Before.hitTarget && buf5052After.hitTarget);

        if (traceIndex < 64u || becameHit)
        {
            std::cerr << "[MOH:call112030:exit]"
                      << " idx=" << std::dec << traceIndex
                      << " pc=0x" << std::hex << entryPc
                      << " nextPc=0x" << (ctx ? ctx->pc : 0u)
                      << " caller=" << mohCall112030CallerName(callerRa)
                      << " callerRa=0x" << callerRa
                      << " packetObjBefore=0x" << packetObjBefore
                      << " packetObjAfter=0x" << packetObjAfter
                      << " packetF12Before=0x" << packetF12Before
                      << " packetF12After=0x" << packetF12After
                      << " packetF13Before=0x" << packetF13Before
                      << " packetF13After=0x" << packetF13After
                      << " packetStyleBefore=0x" << packetStyleBefore
                      << " packetStyleAfter=0x" << packetStyleAfter
                      << " buf4841Post";
            logMohRenderSummary(buf4841After);
            std::cerr << " buf5052Post";
            logMohRenderSummary(buf5052After);
            if (buf4841After.hitAddr != 0u)
            {
                logMohQwordsAround("buf4841HitQ", rdram, buf4841After.hitAddr);
            }
            if (buf5052After.hitAddr != 0u)
            {
                logMohQwordsAround("buf5052HitQ", rdram, buf5052After.hitAddr);
            }
            std::cerr << std::dec << std::endl;
        }
    }

    void mohBuild112128Trace(uint8_t *rdram, R5900Context *ctx, PS2Runtime *runtime)
    {
        const uint32_t entryPc = ctx ? ctx->pc : 0u;
        const uint32_t a0 = getRegU32(ctx, 4);
        const uint32_t a1 = getRegU32(ctx, 5);
        const uint32_t a2 = getRegU32(ctx, 6);
        const uint32_t a3 = getRegU32(ctx, 7);
        const uint32_t ra = getRegU32(ctx, 31);
        const uint32_t s2 = getRegU32(ctx, 18);
        const uint32_t s4 = getRegU32(ctx, 20);
        const uint32_t s5 = getRegU32(ctx, 21);

        const uint32_t obj = entryPc == 0x00112128u ? a0 : s2;
        const uint32_t out = entryPc == 0x00112128u ? a1 : s4;
        const uint32_t packet = entryPc == 0x00112128u ? a2 : s5;

        uint32_t cursorBefore = 0u;
        (void)readGuestU32(rdram, out + 0x08u, cursorBefore);

        const bool targetObject = a0 == 0x01FBF6D0u || obj == 0x01FBF6D0u || s2 == 0x01FBF6D0u;
        const bool targetPacket = a2 == 0x00332628u || packet == 0x00332628u || s5 == 0x00332628u;
        const bool targetOut = out == 0x0023F958u || a1 == 0x0023F958u ||
                               (out >= 0x0023F900u && out <= 0x0023FA20u);
        const bool interesting = targetObject || targetPacket || targetOut ||
                                 isMohMenuDisplayListBuffer(cursorBefore) ||
                                 ra == 0x0010C744u;

        MohRenderRangeSummary buf4841Before{};
        MohRenderRangeSummary buf5052Before{};
        uint32_t traceIndex = UINT32_MAX;
        if (interesting)
        {
            static std::atomic<uint32_t> s_traceCount{0u};
            traceIndex = s_traceCount.fetch_add(1u, std::memory_order_relaxed);
            if (traceIndex < 8u)
            {
                buf4841Before = summarizeMohRenderRange(rdram, 0x00484100u, 0x00484300u);
                buf5052Before = summarizeMohRenderRange(rdram, 0x00505200u, 0x00505400u);
                uint32_t vtbl = 0u;
                (void)readGuestU32(rdram, obj + 0x20u, vtbl);
                std::cerr << "[MOH:build112128:enter]"
                          << " idx=" << std::dec << traceIndex
                          << " pc=0x" << std::hex << entryPc
                          << " obj=0x" << obj
                          << " out=0x" << out
                          << " packet=0x" << packet
                          << " ra=0x" << ra
                          << " cursorBefore=0x" << cursorBefore
                          << " a0=0x" << a0
                          << " a1=0x" << a1
                          << " a2=0x" << a2
                          << " a3=0x" << a3
                          << " s2=0x" << s2
                          << " s4=0x" << s4
                          << " s5=0x" << s5
                          << " vtbl=0x" << vtbl
                          << " chain=" << ::mohDispatchHistory()
                          << " out";
                logMohWords(rdram, out, {0x00u, 0x04u, 0x08u, 0x0Cu, 0x10u, 0x14u,
                                         0x18u, 0x1Cu, 0x20u, 0x24u, 0x28u, 0x2Cu});
                std::cerr << " obj";
                logMohWords(rdram, obj, {0x00u, 0x04u, 0x08u, 0x0Cu, 0x10u, 0x14u,
                                         0x18u, 0x1Cu, 0x20u, 0x24u, 0x28u, 0x2Cu,
                                         0x30u, 0x34u, 0x38u, 0x3Cu, 0x40u, 0x44u,
                                         0x48u, 0x4Cu, 0x50u});
                std::cerr << " packet";
                logMohWords(rdram, packet, {0x00u, 0x04u, 0x08u, 0x0Cu, 0x10u, 0x14u,
                                            0x18u, 0x1Cu, 0x20u, 0x24u, 0x28u, 0x2Cu,
                                            0x30u, 0x34u, 0x38u, 0x3Cu, 0x40u, 0x44u,
                                            0x48u, 0x4Cu, 0x50u});
                // Decisive: the vertex-source temp the builder reads (packet[+8]).
                // If these coords are already offset-only, the collapse is upstream
                // of 112128; if 112128 collapses them, the bug is inside 112128.
                uint32_t vtxSrc = 0u;
                (void)readGuestU32(rdram, packet + 0x08u, vtxSrc);
                std::cerr << " vtxSrc=0x" << std::hex << vtxSrc << " cnt=0x"
                          << readGuestU32OrZero(rdram, packet + 0x0Cu)
                          << " stride=0x" << readGuestU32OrZero(rdram, packet + 0x10u)
                          << " vtx";
                if (vtxSrc >= 0x10000u && vtxSrc + 0x40u <= 0x02000000u)
                {
                    logMohWords(rdram, vtxSrc, {0x00u, 0x04u, 0x08u, 0x0Cu, 0x10u, 0x14u,
                                                0x18u, 0x1Cu, 0x20u, 0x24u, 0x28u, 0x2Cu,
                                                0x30u, 0x34u, 0x38u, 0x3Cu});
                }
                std::cerr << " buf4841Pre";
                logMohRenderSummary(buf4841Before);
                std::cerr << " buf5052Pre";
                logMohRenderSummary(buf5052Before);
                logMohRenderDisplayListCursors(rdram);
                std::cerr << std::dec << std::endl;
            }
        }

        if (g_mohOriginalBuild112128 && g_mohOriginalBuild112128 != &mohBuild112128Trace)
        {
            g_mohOriginalBuild112128(rdram, ctx, runtime);
        }
        else if (ctx)
        {
            ctx->pc = ra;
        }

        if (!interesting || traceIndex >= 8u)
        {
            return;
        }

        uint32_t cursorAfter = 0u;
        (void)readGuestU32(rdram, out + 0x08u, cursorAfter);

        uint32_t start = 0u;
        uint32_t end = 0u;
        MohRenderRangeSummary cursorSummary{};
        if (isMohPlausibleRenderCursor(cursorBefore, cursorAfter, start, end))
        {
            cursorSummary = summarizeMohRenderRange(rdram, start, end);
        }

        if (traceIndex < 8u)
        {
            std::cerr << "[MOH:build112128:exit]"
                      << " idx=" << std::dec << traceIndex
                      << " pc=0x" << std::hex << entryPc
                      << " nextPc=0x" << (ctx ? ctx->pc : 0u)
                      << " obj=0x" << obj
                      << " out=0x" << out
                      << " packet=0x" << packet
                      << " cursorBefore=0x" << cursorBefore
                      << " cursorAfter=0x" << cursorAfter
                      << " ret=0x" << (ctx ? getRegU32(ctx, 2) : 0u)
                      << " range=0x" << start << "-0x" << end
                      << " cursorSummary";
            logMohRenderSummary(cursorSummary);
            if (cursorSummary.hitAddr != 0u)
            {
                logMohQwordsAround("cursorHitQ", rdram, cursorSummary.hitAddr);
            }
            logMohRenderDisplayListCursors(rdram);
            (void)logMohMenuBufferState(" buf4841Post", " buf4841Head", "buf4841HitQ",
                                        rdram, 0x00484100u, 0x200u);
            (void)logMohMenuBufferState(" buf5052Post", " buf5052Head", "buf5052HitQ",
                                        rdram, 0x00505200u, 0x200u);
            std::cerr << std::dec << std::endl;
        }
    }

