    void mohFrontendUploadPump10bfe8Trace(uint8_t *rdram, R5900Context *ctx, PS2Runtime *runtime)
    {
        const uint32_t entryPc = ctx ? ctx->pc : 0u;
        const bool functionEntry = entryPc == 0x0010BFE8u;
        const uint32_t callerRa = ctx ? getRegU32(ctx, 31) : 0u;
        const uint32_t queueBefore = readGuestU32OrZero(rdram, 0x002410F4u);
        const uint32_t packetBefore = readGuestU32OrZero(rdram, queueBefore);
        const uint32_t gifChannel = readGuestU32OrZero(rdram, 0x00241460u);
        static std::atomic<uint32_t> s_emptyCount{0u};
        static std::atomic<uint32_t> s_submitCount{0u};
        const bool hasPacket = packetBefore != 0u;
        const uint32_t traceIndex = hasPacket
                                        ? s_submitCount.fetch_add(1u, std::memory_order_relaxed)
                                        : s_emptyCount.fetch_add(1u, std::memory_order_relaxed);
        const uint32_t traceCap = 8u;

        if (traceIndex < traceCap)
        {
            std::cerr << "[MOH:frontend-upload-pump:enter]"
                      << " idx=" << std::dec << traceIndex
                      << " submit=" << (hasPacket ? 1 : 0)
                      << " pc=0x" << std::hex << entryPc
                      << " ra=0x" << callerRa
                      << " queue=0x" << queueBefore
                      << " packet=0x" << packetBefore
                      << " gif=0x" << gifChannel
                      << " qwords";
            logMohWords(rdram, queueBefore,
                        {0x00u, 0x04u, 0x08u, 0x0Cu, 0x10u, 0x14u,
                         0x18u, 0x1Cu, 0x20u, 0x24u, 0x28u, 0x2Cu});
            std::cerr << std::dec << std::endl;
        }

        if (g_mohOriginalFrontendUploadPump10bfe8 &&
            g_mohOriginalFrontendUploadPump10bfe8 != &mohFrontendUploadPump10bfe8Trace)
        {
            g_mohOriginalFrontendUploadPump10bfe8(rdram, ctx, runtime);
        }
        else if (ctx)
        {
            ctx->pc = callerRa;
        }

        if (traceIndex < traceCap)
        {
            const uint32_t queueAfter = readGuestU32OrZero(rdram, 0x002410F4u);
            std::cerr << "[MOH:frontend-upload-pump:return]"
                      << " idx=" << std::dec << traceIndex
                      << " submit=" << (hasPacket ? 1 : 0)
                      << " entry=" << functionEntry
                      << " nextPc=0x" << std::hex << (ctx ? ctx->pc : 0u)
                      << " queue=0x" << queueBefore << "->0x" << queueAfter
                      << " packet=0x" << readGuestU32OrZero(rdram, queueAfter)
                      << std::dec << std::endl;
        }
    }

