    void mohRender11a278Probe(uint8_t *rdram, R5900Context *ctx, PS2Runtime *runtime)
    {
        // [MOH diag] sub_0011A278 renders object [0x24122C] then clears it. Dump that transient
        // object (and pointers from it) BEFORE the original runs, hunting for X=1548 (=0x60C).
        uint32_t obj = 0u;
        (void)readGuestU32(rdram, 0x0024122Cu, obj);
        static uint32_t s_log = 0u;
        if (obj != 0u && s_log < 8u)
        {
            ++s_log;
            auto dump = [&](const char *tag, uint32_t base, uint32_t lim)
            {
                if (base == 0u || base >= 0x02000000u) return;
                std::cerr << "[MOH:r11a278] " << tag << "=0x" << std::hex << base << " f:";
                for (uint32_t off = 0u; off <= lim; off += 4u)
                {
                    uint32_t w = 0u;
                    (void)readGuestU32(rdram, base + off, w);
                    std::cerr << " " << off << "=" << w;
                    if (w == 1548u || w == 1903u || w == (1548u << 4) || w == (1903u << 4))
                        std::cerr << "<<HIT";
                }
                std::cerr << std::dec << std::endl;
            };
            dump("obj", obj, 0x60u);
            uint32_t p08 = 0u, p10 = 0u, p14 = 0u, p18 = 0u, p1c = 0u;
            (void)readGuestU32(rdram, obj + 0x08u, p08);
            (void)readGuestU32(rdram, obj + 0x10u, p10);
            (void)readGuestU32(rdram, obj + 0x14u, p14);
            (void)readGuestU32(rdram, obj + 0x18u, p18);
            (void)readGuestU32(rdram, obj + 0x1Cu, p1c);
            dump("obj+0x08", p08, 0x40u);
            dump("obj+0x10", p10, 0x40u);
            dump("obj+0x14", p14, 0x40u);
            dump("obj+0x18", p18, 0x40u);
            dump("obj+0x1C", p1c, 0x40u);
        }

        if (g_mohOriginalRender11a278 && g_mohOriginalRender11a278 != &mohRender11a278Probe)
            g_mohOriginalRender11a278(rdram, ctx, runtime);
        else if (ctx)
            ctx->pc = getRegU32(ctx, 31);
    }

    void mohUpdate10cfb8Trace(uint8_t *rdram, R5900Context *ctx, PS2Runtime *runtime)
    {
        const uint32_t a0 = getRegU32(ctx, 4);
        const uint32_t a1 = getRegU32(ctx, 5);
        const uint32_t a2 = getRegU32(ctx, 6);
        const uint32_t ra = getRegU32(ctx, 31);
        uint32_t beforeChild = 0u;
        uint32_t before24 = 0u;
        uint32_t before2c = 0u;
        (void)readGuestU32(rdram, a0 + 0x08u, beforeChild);
        (void)readGuestU32(rdram, a0 + 0x24u, before24);
        (void)readGuestU32(rdram, a0 + 0x2Cu, before2c);

        if (g_mohOriginalUpdate10cfb8 && g_mohOriginalUpdate10cfb8 != &mohUpdate10cfb8Trace)
        {
            g_mohOriginalUpdate10cfb8(rdram, ctx, runtime);
        }
        else if (ctx)
        {
            ctx->pc = ra;
        }

        static uint32_t logCount = 0u;
        if (logCount < 40u)
        {
            std::cerr << "[MOH:fe-update10]"
                      << " method=0x10cfb8"
                      << " node=0x" << std::hex << a0
                      << " out=0x" << a1
                      << " obj=0x" << a2
                      << " ra=0x" << ra
                      << " beforeChild=0x" << beforeChild
                      << " before24=0x" << before24
                      << " before2c=0x" << before2c
                      << " ret=0x" << (ctx ? getRegU32(ctx, 2) : 0u)
                      << " node";
            logMohWords(rdram, a0, {0x00u, 0x04u, 0x08u, 0x0Cu, 0x10u, 0x14u,
                                    0x18u, 0x1Cu, 0x20u, 0x24u, 0x28u, 0x2Cu});
            std::cerr << std::dec << std::endl;
            ++logCount;
        }

        // [MOH diag] one-time deep scan: object [0x24122C] (the render target per sub_0011A278)
        // and pointers reachable from it, hunting for the off-screen X value 1548 (=0x60C) or 0x60C0.
        static bool s_objDone = false;
        if (!s_objDone)
        {
            uint32_t obj = 0u;
            (void)readGuestU32(rdram, 0x0024122Cu, obj);
            if (obj != 0u)
            {
                s_objDone = true;
                auto dumpObj = [&](const char *tag, uint32_t base)
                {
                    if (base == 0u) return;
                    std::cerr << "[MOH:fe-obj] " << tag << "=0x" << std::hex << base << " f:";
                    for (uint32_t off = 0x00u; off <= 0x60u; off += 0x04u)
                    {
                        uint32_t w = 0u;
                        (void)readGuestU32(rdram, base + off, w);
                        std::cerr << " " << off << "=" << w;
                        if (w == 1548u || w == 1903u || w == (1548u << 4) || w == (1903u << 4) ||
                            w == 0xFFFFF94Cu /*(-180<<? )*/ )
                            std::cerr << "<<HIT";
                    }
                    std::cerr << std::dec << std::endl;
                };
                dumpObj("obj[24122C]", obj);
                uint32_t p10 = 0u, p8 = 0u, p4 = 0u, pC = 0u;
                (void)readGuestU32(rdram, obj + 0x10u, p10);
                (void)readGuestU32(rdram, obj + 0x08u, p8);
                (void)readGuestU32(rdram, obj + 0x04u, p4);
                (void)readGuestU32(rdram, obj + 0x0Cu, pC);
                dumpObj("obj+0x04", p4);
                dumpObj("obj+0x08", p8);
                dumpObj("obj+0x0C", pC);
                dumpObj("obj+0x10", p10);
            }
        }
    }

