    void mohBgm1c5a28Trace(uint8_t *rdram, R5900Context *ctx, PS2Runtime *runtime)
    {
        const bool fnEntry = ctx && ctx->pc == 0x001C5A28u;
        uint32_t ra = 0u;
        uint32_t traceIndex = UINT32_MAX;
        bool startedAsfStreamer = false;
        if (fnEntry)
        {
            ra = getRegU32(ctx, 31);
            static std::atomic<uint32_t> s_count{0u};
            traceIndex = s_count.fetch_add(1u, std::memory_order_relaxed);
            if (traceIndex < 12u)
            {
                const uint32_t a1 = getRegU32(ctx, 5);
                std::cerr << "[MOH:menu-music-chain-v1] fn=1c5a28"
                          << " idx=" << std::dec << traceIndex
                          << std::hex
                          << " a0=0x" << getRegU32(ctx, 4)
                          << " a1=0x" << a1
                          << " path='"
                          << readGuestStringLimited(rdram, a1, 40u)
                          << "'"
                          << " a2=0x" << getRegU32(ctx, 6)
                          << " a3=0x" << getRegU32(ctx, 7)
                          << " ra=0x" << ra
                          << std::dec << std::endl;
            }

            // Guest-owned start boundary for the shell BGM: the play call
            // carries the .asf path; mirror it on the host bridge (the native
            // EE ring producer never runs without IOP stream feedback).
            const std::string bgmPath =
                readGuestStringLimited(rdram, getRegU32(ctx, 5), 64u);
            const std::string bgmLower = mohLowerAscii(bgmPath);
            if (bgmLower.size() > 4u &&
                bgmLower.compare(bgmLower.size() - 4u, 4u, ".asf") == 0)
            {
                std::filesystem::path hostPath;
                if (resolveMohHostFilePath(bgmPath, hostPath))
                {
                    mohMenuMusicStreamer().start(bgmPath, hostPath);
                    startedAsfStreamer = true;
                }
                else
                {
                    std::cerr << "[MOH:menu-music] host path unresolved for '"
                              << bgmPath << "'" << std::endl;
                }
            }
        }
        if (g_mohOriginalBgm1c5a28 &&
            g_mohOriginalBgm1c5a28 != &mohBgm1c5a28Trace)
        {
            g_mohOriginalBgm1c5a28(rdram, ctx, runtime);
        }
        else if (ctx)
        {
            ctx->pc = getRegU32(ctx, 31);
        }
        if (fnEntry && traceIndex < 12u && ctx)
        {
            std::cerr << "[MOH:menu-music-chain-v1] fn=1c5a28-exit"
                      << " idx=" << std::dec << traceIndex
                      << " ret=0x" << std::hex << getRegU32(ctx, 2)
                      << " pc=0x" << ctx->pc
                      << std::dec << std::endl;
        }
        if (fnEntry && startedAsfStreamer && ctx)
        {
            const uint32_t bgmHandle = getRegU32(ctx, 2);
            if (bgmHandle != 0u && bgmHandle != 0xFFFFFFFFu &&
                (bgmHandle & 0x80000000u) == 0u)
            {
                g_mohMenuMusicGuestHandle.store(
                    bgmHandle, std::memory_order_release);
                std::cerr << "[MOH:menu-music] guest handle=0x"
                          << std::hex << bgmHandle
                          << std::dec << std::endl;
            }
        }
    }

    // The 6_1 loader dispatches through a jump table at core guest address
    // 0x0031FB90 (func_140738: v0=lui0x32/addiu-0x470 -> 0x31FB90; a0 =
    // table[a1]; jr a0).  In MOH2RDVD.ELF this table holds valid handler
    // addresses (0x140760/0x140768/0x14076C/... = the exact cases func_140738
    // already dispatches).  At runtime every entry has its low 16 bits zeroed
    // (0x140768 -> 0x140000, 0x1433B8 -> 0x140000, ...): the core ELF data at
    // this offset lands mis-loaded (no recompiled function ever writes here),
    // so `jr a0` lands at 0x140000, mid-body of sub_0013FD78 with no entry
    // case, and the dispatcher restarts that function from the top forever.
    //
    // Repair the table once, just before func_140738 first reads it, from the
    // authoritative static bytes in MOH2RDVD.ELF (loaded at its native VA, so
    // no relocation is needed).  Only entries matching the exact corruption
    // signature are touched: runtime == (elf & 0xFFFF0000), elf low half != 0,
    // elf a plausible core code address.  All other words are left untouched.
    // Idempotent, self-timing core jump-table repair.  Safe to call from any
    // hook: it only performs the repair once, and only once the core data is
    // actually loaded (detected by the corruption signature being present), so
    // early callers that fire before the core .data lands simply retry later.
    // The core image (MOH2RDVD.ELF, native VA 0x00104000) is streamed into
    // guest RAM in file order by the launcher's bounded CD loader, and every
    // loaded word lands with its low 16 bits zeroed (a systemic ~310k-word
    // low-halfword load corruption).  Because recompiled code runs from native
    // C++, the guest .text / .vutext / .rodata bytes are only ever read as data
    // (jump tables, embedded pointers, VU microcode) and are never written at
    // runtime, so they can be authoritatively restored in full from the ELF.
    //
    // Timing matters and differs per section: the C++ ctors that copy .text
    // jump-table pointers into runtime globals run right after the core entry,
    // BEFORE .rodata finishes streaming — so .text/.vutext/.data must be
    // restored as soon as they are present (early), while .rodata must be
    // restored only once IT has streamed in (later) or the launcher overwrites
    // the restore with corrupted bytes.  Each section is therefore restored
    // once, gated on that section being present, so an early caller fixes
    // .text before the ctors and a later caller fixes .rodata before its jump
    // tables (e.g. 0x31FB90 / func_140738) are used during level load.
    void mohRepairCoreImageSection(uint8_t *rdram, uint32_t va, uint32_t fileOff,
                                   uint32_t size, const char *name,
                                   bool codePtrSignatureOnly)
    {
        std::ifstream elf("extracted/MOH2RDVD.ELF", std::ios::binary);
        if (!elf.is_open())
        {
            return;
        }
        std::vector<uint8_t> buf(size);
        elf.seekg(fileOff, std::ios::beg);
        elf.read(reinterpret_cast<char *>(buf.data()),
                 static_cast<std::streamsize>(size));
        const uint32_t got = static_cast<uint32_t>(elf.gcount());
        uint64_t fixed = 0u;
        if (codePtrSignatureOnly)
        {
            // Writable .data: only fix words matching the exact
            // low-halfword-zeroed core-code-pointer signature.
            constexpr uint32_t kCodeLo = 0x00104000u;
            constexpr uint32_t kCodeHi = 0x00260000u;
            for (uint32_t off = 0u; off + 4u <= got; off += 4u)
            {
                const uint32_t elfVal =
                    static_cast<uint32_t>(buf[off]) |
                    (static_cast<uint32_t>(buf[off + 1u]) << 8) |
                    (static_cast<uint32_t>(buf[off + 2u]) << 16) |
                    (static_cast<uint32_t>(buf[off + 3u]) << 24);
                if ((elfVal & 0xFFFFu) == 0u ||
                    elfVal < kCodeLo || elfVal >= kCodeHi)
                {
                    continue;
                }
                const uint32_t addr = va + off;
                const uint32_t rt = readGuestU32OrZero(rdram, addr);
                if ((elfVal & 0xFFFF0000u) == rt && elfVal != rt)
                {
                    (void)writeGuestU32(rdram, addr, elfVal);
                    ++fixed;
                }
            }
        }
        else
        {
            uint8_t *dst = getMemPtr(rdram, va);
            if (dst)
            {
                for (uint32_t off = 0u; off < got; ++off)
                {
                    if (dst[off] != buf[off])
                    {
                        dst[off] = buf[off];
                        ++fixed;
                    }
                }
            }
        }
        std::cerr << "[MOH:jumptable-repair-v1] section " << name
                  << " restored " << std::dec << fixed << " words/bytes"
                  << std::endl;
    }

    void mohRepairCoreJumpTables(uint8_t *rdram)
    {
        if (!rdram)
        {
            return;
        }
        // .text/.vutext/.data are present by core entry; restore them before
        // the ctors run.  Gate on a .text word being loaded.
        static std::atomic<bool> s_early{false};
        bool expEarly = false;
        if (!s_early.load(std::memory_order_acquire) &&
            readGuestU32OrZero(rdram, 0x00104100u) != 0u &&
            s_early.compare_exchange_strong(expEarly, true,
                                            std::memory_order_acq_rel))
        {
            mohRepairCoreImageSection(rdram, 0x00104000u, 0x00001000u,
                                      0x00133D40u, ".text", false);
            mohRepairCoreImageSection(rdram, 0x00237D40u, 0x00134D40u,
                                      0x000076D0u, ".vutext", false);
            mohRepairCoreImageSection(rdram, 0x0023F480u, 0x0013C480u,
                                      0x0002DC5Cu, ".data", true);
        }
        // .rodata is different: the low-halfword corruption is a *discrete
        // later event* (the early per-section restore above finds it clean and
        // fixes nothing, yet the jump table at 0x31FB90 is corrupt by the time
        // func_140738 dispatches through it at level load — producing the
        // 0x140000 spin).  So the .rodata restore is corruption-TRIGGERED and
        // RE-RUNNABLE rather than one-shot: it fires only when the canary word
        // 0x31FB90 (jump-table entry, correct value 0x00140768) shows the
        // zeroed-low-halfword signature, and can fire again if re-corrupted.
        // This is driven from both the heartbeat and the func_140738 wrapper,
        // so the table is repaired in the instant before it is read.
        const uint32_t canary = readGuestU32OrZero(rdram, 0x0031FB90u);
        if (canary != 0u && (canary & 0x0000FFFFu) == 0u &&
            (canary & 0xFFFF0000u) == 0x00140000u)
        {
            mohRepairCoreImageSection(rdram, 0x0031C200u, 0x00219200u,
                                      0x00015AE0u, ".rodata", false);
        }
    }

    void mohJumpTableRepair140738(uint8_t *rdram, R5900Context *ctx, PS2Runtime *runtime)
    {
        mohRepairCoreJumpTables(rdram);
        if (g_mohOriginalJumpTable140738 &&
            g_mohOriginalJumpTable140738 != &mohJumpTableRepair140738)
        {
            g_mohOriginalJumpTable140738(rdram, ctx, runtime);
        }
        else if (ctx)
        {
            ctx->pc = getRegU32(ctx, 31);
        }
    }

    // Core entry point (MOH2RDVD.ELF _start, guest 0x104008).  The core .data
    // is already loaded (and low-halfword corrupted) by the time the launcher
    // transfers control here, but the C++ static initializers that build the
    // 6_1 dispatch structures run INSIDE this entry (before any frame).  Repair
    // the core jump tables first so those constructors copy correct code
    // pointers, then run the real entry.
    void mohCoreEntry104008Repair(uint8_t *rdram, R5900Context *ctx, PS2Runtime *runtime)
    {
        mohRepairCoreJumpTables(rdram);
        if (g_mohOriginalCoreEntry104008 &&
            g_mohOriginalCoreEntry104008 != &mohCoreEntry104008Repair)
        {
            g_mohOriginalCoreEntry104008(rdram, ctx, runtime);
        }
        else if (ctx)
        {
            ctx->pc = getRegU32(ctx, 31);
        }
    }

    // TEMP step-1 probe for the 0x230000 blocker: capture the EE dispatch
    // chain (exact recompiled-function path to the bogus jump), full register
    // file of interest, and the heap object around a0/v0 so the fn-pointer
    // FIELD address can be pinned before any write-watch is armed.
    void mohProbe230000(uint8_t *rdram, R5900Context *ctx, PS2Runtime *runtime)
    {
        (void)runtime;
        if (ctx)
        {
            static std::atomic<uint32_t> s_n{0u};
            const uint32_t n = s_n.fetch_add(1u, std::memory_order_relaxed);
            if (n < 3u)
            {
                std::cerr << "[MOH:ww230-site-v1] n=" << std::dec << n
                          << std::hex
                          << " ra=0x" << getRegU32(ctx, 31)
                          << " sp=0x" << getRegU32(ctx, 29)
                          << " a0=0x" << getRegU32(ctx, 4)
                          << " a1=0x" << getRegU32(ctx, 5)
                          << " a2=0x" << getRegU32(ctx, 6)
                          << " a3=0x" << getRegU32(ctx, 7)
                          << " v0=0x" << getRegU32(ctx, 2)
                          << " v1=0x" << getRegU32(ctx, 3)
                          << " t9=0x" << getRegU32(ctx, 25)
                          << " s0=0x" << getRegU32(ctx, 16)
                          << " s1=0x" << getRegU32(ctx, 17)
                          << " s2=0x" << getRegU32(ctx, 18)
                          << " s3=0x" << getRegU32(ctx, 19)
                          << " s4=0x" << getRegU32(ctx, 20)
                          << "\n  obj@a0=";
                const uint32_t a0 = getRegU32(ctx, 4);
                for (uint32_t w = 0u; w < 32u; ++w)
                {
                    std::cerr << (w ? "," : "") << "0x"
                              << readGuestU32OrZero(rdram, a0 + w * 4u);
                }
                std::cerr << "\n  stackRets=";
                const uint32_t sp = getRegU32(ctx, 29);
                for (uint32_t w = 0u; w < 40u; ++w)
                {
                    const uint32_t v =
                        readGuestU32OrZero(rdram, sp + w * 4u);
                    if (v >= 0x00104000u && v < 0x00374000u)
                    {
                        std::cerr << "0x" << v << "@sp+0x" << (w * 4u) << " ";
                    }
                }
                std::cerr << std::dec
                          << "\n  ee-dispatch-chain: " << mohDispatchHistory();
                // Locate every RAM word == 0x00230000 to pin the field(s) that
                // hold the bogus pointer.
                std::cerr << "\n  0x230000-in-RAM@=";
                uint32_t found = 0u;
                for (uint32_t addr = 0x00100000u;
                     addr < 0x00700000u && found < 24u; addr += 4u)
                {
                    if (readGuestU32OrZero(rdram, addr) == 0x00230000u)
                    {
                        std::cerr << "0x" << std::hex << addr << " ";
                        ++found;
                    }
                }
                std::cerr << std::dec << " (found=" << found << ")"
                          << std::endl;
            }
        }
        if (ctx)
        {
            ctx->pc = getRegU32(ctx, 31);
        }
    }

