    // TEMP menu-SFX probe (bounded): 0x20BC68 is the SPU2 voice-upload entry
    // (its drain poll is what mohSound20bac8Fix unblocks).  Log its args to
    // capture sample source address/size when menu navigation plays a sound.
    void mohVoiceUpload20bc68Trace(uint8_t *rdram, R5900Context *ctx, PS2Runtime *runtime)
    {
        if (ctx && ctx->pc == 0x0020BC68u)
        {
            static std::atomic<uint32_t> s_count{0u};
            const uint32_t idx =
                s_count.fetch_add(1u, std::memory_order_relaxed);
            const bool menuPhase =
                g_mohMenuMusicGuestHandle.load(
                    std::memory_order_acquire) != 0u;
            static std::atomic<uint32_t> s_menuCount{0u};
            const uint32_t menuIdx =
                menuPhase
                    ? s_menuCount.fetch_add(1u, std::memory_order_relaxed)
                    : UINT32_MAX;
            if (idx < 24u || menuIdx < 24u)
            {
                const uint32_t a1 = getRegU32(ctx, 5);
                std::cerr << "[MOH:menu-sfx-probe-v1] fn=20bc68"
                          << " idx=" << std::dec << idx
                          << " menuIdx=" << menuIdx
                          << std::hex
                          << " a0=0x" << getRegU32(ctx, 4)
                          << " a1=0x" << a1
                          << " a2=0x" << getRegU32(ctx, 6)
                          << " a3=0x" << getRegU32(ctx, 7)
                          << " t0=0x" << getRegU32(ctx, 8)
                          << " ra=0x" << getRegU32(ctx, 31)
                          << " a1words=";
                logMohGuestWords(rdram, a1, 8u);
                std::cerr << std::dec << std::endl;
            }

            // TEMP SFX step-5 validation: decode the source a1 as RAW SPU2
            // ADPCM (no VAGp header) up to a3 bytes / first END block, and log
            // block count, END/loop flags, sample count and peak amplitude to
            // prove the capture point carries a real, decodable sample.
            if (menuIdx < 4u)
            {
                const uint32_t src = getRegU32(ctx, 5) & 0x1FFFFFFFu;
                const uint32_t size = std::min<uint32_t>(getRegU32(ctx, 7),
                                                         0x2000u);
                if (src + size <= PS2_RAM_SIZE && size >= 16u)
                {
                    const uint8_t *d = rdram + src;
                    int16_t s1 = 0, s2 = 0;
                    uint32_t blocks = 0u, samples = 0u;
                    uint32_t peak = 0u;
                    bool endSeen = false, loopSeen = false;
                    for (uint32_t off = 0u; off + 16u <= size; off += 16u)
                    {
                        const uint8_t hdr = d[off];
                        const uint8_t flags = d[off + 1u];
                        uint8_t shift = hdr & 0x0Fu;
                        if (shift > 12u) shift = 9u;
                        uint8_t filter = (hdr >> 4) & 0x07u;
                        if (filter > 4u) filter = 0u;
                        static const int32_t fpos[5] = {0, 60, 115, 98, 122};
                        static const int32_t fneg[5] = {0, 0, 52, 55, 60};
                        for (int si = 0; si < 28; ++si)
                        {
                            const uint8_t byte = d[off + 2u + si / 2];
                            const uint8_t nib =
                                (si & 1) ? (byte >> 4) : (byte & 0x0Fu);
                            int32_t r = (nib & 8u) ? (int32_t)(nib | 0xFFFFFFF0u)
                                                   : (int32_t)nib;
                            int32_t sh = r << (12 - shift);
                            int32_t f = sh +
                                (fpos[filter] * (int32_t)s1 -
                                 fneg[filter] * (int32_t)s2 + 32) / 64;
                            if (f < -32768) f = -32768;
                            if (f > 32767) f = 32767;
                            s2 = s1; s1 = (int16_t)f;
                            const uint32_t mag = f < 0 ? (uint32_t)(-f)
                                                       : (uint32_t)f;
                            if (mag > peak) peak = mag;
                            ++samples;
                        }
                        ++blocks;
                        if (flags & 0x01u) { endSeen = true; }
                        if (flags & 0x02u) { loopSeen = true; }
                        if (flags & 0x01u) break;
                    }
                    std::cerr << "[MOH:sfx-decode-validate-v1]"
                              << " menuIdx=" << std::dec << menuIdx
                              << " src=0x" << std::hex << src
                              << " spu2=0x" << getRegU32(ctx, 6)
                              << std::dec
                              << " blocks=" << blocks
                              << " samples=" << samples
                              << " peak=" << peak
                              << " end=" << (endSeen ? 1 : 0)
                              << " loop=" << (loopSeen ? 1 : 0)
                              << std::endl;

                    // TEMP SFX step-6 one-shot: experimental, env-gated OFF by
                    // default (PS2_MOH_SFX_BRIDGE=1).  Play the first fully
                    // decodable menu SFX once through the existing sample
                    // backend by wrapping the raw SPU2 ADPCM in a synthetic
                    // VAGp header (48000 Hz), then keying it.
                    static const bool sfxBridgeEnabled = [] {
                        const char *v = std::getenv("PS2_MOH_SFX_BRIDGE");
                        return v && v[0] == '1';
                    }();
                    static std::atomic<bool> sOneShotDone{false};
                    bool expected = false;
                    if (sfxBridgeEnabled && runtime && menuIdx == 0u &&
                        endSeen && peak > 1000u &&
                        sOneShotDone.compare_exchange_strong(expected, true))
                    {
                        const uint32_t adpcmBytes = blocks * 16u;
                        std::vector<uint8_t> vag(48u + adpcmBytes, 0u);
                        vag[0] = 'V'; vag[1] = 'A'; vag[2] = 'G'; vag[3] = 'p';
                        vag[7] = 0x20u;                       // version
                        vag[0x0C] = (adpcmBytes >> 24) & 0xFF;
                        vag[0x0D] = (adpcmBytes >> 16) & 0xFF;
                        vag[0x0E] = (adpcmBytes >> 8) & 0xFF;
                        vag[0x0F] = adpcmBytes & 0xFF;
                        vag[0x10] = 0x00; vag[0x11] = 0x00;   // 48000 Hz =
                        vag[0x12] = 0xBB; vag[0x13] = 0x80;   //   0x0000BB80
                        std::memcpy(vag.data() + 48u, d, adpcmBytes);
                        const uint32_t key = getRegU32(ctx, 6);
                        runtime->audioBackend().onVagTransferFromBuffer(
                            vag.data(),
                            static_cast<uint32_t>(vag.size()),
                            key);
                        runtime->audioBackend().play(key, 1.0f, 1.0f);
                        std::cerr << "[MOH:sfx-oneshot-v1] played"
                                  << " key=0x" << std::hex << key
                                  << " adpcmBytes=0x" << adpcmBytes
                                  << std::dec << " samples=" << samples
                                  << " peak=" << peak << std::endl;
                    }
                }
            }
        }
        if (g_mohOriginalVoiceUpload20bc68 &&
            g_mohOriginalVoiceUpload20bc68 != &mohVoiceUpload20bc68Trace)
        {
            g_mohOriginalVoiceUpload20bc68(rdram, ctx, runtime);
        }
        else if (ctx)
        {
            ctx->pc = getRegU32(ctx, 31);
        }
    }

    // TEMP menu-SFX probe: candidate SE-play wrappers next to the BGM family.
