    void mohSound20b888Stub(uint8_t *rdram, R5900Context *ctx, PS2Runtime *runtime)
    {
        // IOP sound-driver poll (func_20B888->func_20BD78) that our runtime never
        // completes (no full IOP/SPU2 emulation). Report "ready" so the sound-bank
        // (ShellBnk.abk) init proceeds; the menu render doesn't need SPU2 playback.
        (void)rdram;
        (void)runtime;
        if (ctx)
        {
            setReturnU32(ctx, 1u);
            ctx->pc = getRegU32(ctx, 31);
        }
    }

    void mohSound20bac8Fix(uint8_t *rdram, R5900Context *ctx, PS2Runtime *runtime)
    {
        if (g_mohOriginalSound20bac8 && g_mohOriginalSound20bac8 != &mohSound20bac8Fix)
        {
            g_mohOriginalSound20bac8(rdram, ctx, runtime);
        }
        else if (ctx)
        {
            ctx->pc = getRegU32(ctx, 31);
        }
        // sub_0020BC68's voice-upload poll loops while the SPU2 voice counter byte at
        // guest 0x00261924 is > 23. The IOP would decrement it as voices drain; our
        // runtime doesn't, so clear it (low byte of the word) so the loop exits.
        uint32_t counterWord = 0u;
        if (readGuestU32(rdram, 0x00261924u, counterWord))
        {
            (void)writeGuestU32(rdram, 0x00261924u, counterWord & 0xFFFFFF00u);
        }
    }

    void mohAlloc1f5398Fix(uint8_t *rdram, R5900Context *ctx, PS2Runtime *runtime)
    {
        const uint32_t callerRa = getRegU32(ctx, 31);
        const uint32_t outerRa =
            readGuestU32OrZero(
                rdram,
                getRegU32(ctx, 29) + 0x60u);

        if (g_mohOriginalAlloc1f5398 && g_mohOriginalAlloc1f5398 != &mohAlloc1f5398Fix)
        {
            g_mohOriginalAlloc1f5398(rdram, ctx, runtime);
        }
        if (!ctx)
        {
            return;
        }
        // Only post-process once the allocator (FUN_001f5398, 0x1f5398-0x1f54e0)
        // has fully returned (pc left the body), so v0 holds the allocated node.
        if (ctx->pc >= 0x001F5398u && ctx->pc < 0x001F54E0u)
        {
            return;
        }
        const uint32_t node = getRegU32(ctx, 2); // v0 = returned FS handle node
        if (node == 0u)
        {
            return;
        }

        if (callerRa == 0x001F4874u)
        {
            g_mohHandle9TraceEntry.store(
                node,
                std::memory_order_release);

            logMohHandle9TraceV1(
                "[MOH:handle9-create-trace-v1]",
                "allocator-return",
                rdram,
                ctx,
                0x001F5398u,
                readGuestU32OrZero(
                    rdram,
                    node + 0x00u),
                node,
                "cd:data\\6\\6_1\\comp.viv",
                outerRa);
        }

        // The game reuses the same slot (open/close sequentially) but the free path
        // does not unlink the node from the sorted handle list, so the list head
        // (FS-mgr 0x0025FCAC) still points at this slot and its next (+0x2C) self-
        // cycles. Re-inserting the reused slot then self-links the list and the game
        // error-exits. Clear the stale linkage so the next insert (FUN_001f4cf0)
        // sees a fresh node.
        uint32_t head = 0u;
        if (readGuestU32(rdram, 0x0025FCACu, head) && head == node)
        {
            (void)writeGuestU32(rdram, 0x0025FCACu, 0u);
        }
        (void)writeGuestU32(rdram, node + 0x2Cu, 0u);
    }

    void mohCmp1ec258Safe(uint8_t *rdram, R5900Context *ctx, PS2Runtime *runtime)
    {
        (void)runtime;
        if (!ctx)
        {
            return;
        }
        // Original comparator @0x1ec258 returns (keyA - keyB) where
        // key = (u16@+0 << 16) | u16@+2. That subtraction overflows when the
        // frontend's key table contains keys spanning >2^31, yielding an
        // inconsistent ordering so the sort (sub_0021AFF8 @0x21b650) never
        // terminates -> hard freeze on a black screen. Return an overflow-safe
        // signed 3-way compare so the sort always finishes.
        const uint32_t a0 = getRegU32(ctx, 4);
        const uint32_t a1 = getRegU32(ctx, 5);
        uint32_t rawA = 0u;
        uint32_t rawB = 0u;
        (void)readGuestU32(rdram, a0, rawA);
        (void)readGuestU32(rdram, a1, rawB);
        const int32_t keyA = static_cast<int32_t>(((rawA & 0xFFFFu) << 16) | ((rawA >> 16) & 0xFFFFu));
        const int32_t keyB = static_cast<int32_t>(((rawB & 0xFFFFu) << 16) | ((rawB >> 16) & 0xFFFFu));
        const int32_t result = (keyA < keyB) ? -1 : ((keyA > keyB) ? 1 : 0);
        setReturnU32(ctx, static_cast<uint32_t>(result));
        ctx->pc = getRegU32(ctx, 31);
    }

    void mohDisplayManagerLifecycleTraceV1(
        uint8_t *rdram,
        R5900Context *ctx,
        PS2Runtime *runtime,
        const char *operation,
        PS2Runtime::RecompiledFunction original)
    {
        const bool traceActive =
            rdram &&
            ctx &&
            g_mohLevelViv6_1Active.load(std::memory_order_acquire) &&
            g_mohSceneSortComparator160a60SeenV1.load(
                std::memory_order_acquire) &&
            g_mohCompC0RequestSeenV1.load(std::memory_order_acquire);
        const uint32_t pcBefore = ctx ? ctx->pc : 0u;
        const uint32_t raBefore = ctx ? getRegU32(ctx, 31) : 0u;
        const uint32_t spBefore = ctx ? getRegU32(ctx, 29) : 0u;
        const uint32_t managerArg = ctx ? getRegU32(ctx, 4) : 0u;
        const uint32_t flagsArg = ctx ? getRegU32(ctx, 5) : 0u;
        const uint32_t currentBefore =
            traceActive ? readGuestU32OrZero(rdram, 0x0024ABACu) : 0u;
        const uint32_t previousBefore =
            traceActive ? readGuestU32OrZero(rdram, 0x0024ABA8u) : 0u;
        const uint32_t waitBefore =
            traceActive
                ? readGuestU32OrZero(rdram, kMohFrameWaitFlagAddr)
                : 0u;
        const uint32_t counterBefore =
            traceActive
                ? readGuestU32OrZero(rdram, kMohFrameCounterAddr)
                : 0u;
        const auto readManagerWord = [&](uint32_t manager, uint32_t offset)
        {
            return manager != 0u
                       ? readGuestU32OrZero(rdram, manager + offset)
                       : 0u;
        };
        const uint32_t argFrameBefore =
            traceActive ? readManagerWord(managerArg, 0xF8u) : 0u;
        const uint32_t argSwapBefore =
            traceActive ? readManagerWord(managerArg, 0xF4u) : 0u;
        const uint32_t argDescriptorBefore =
            traceActive ? readManagerWord(managerArg, 0x100u) : 0u;

        uint32_t traceIndex = 16u;
        if (traceActive)
        {
            static std::atomic<uint32_t> sTraceCount{0u};
            traceIndex =
                sTraceCount.fetch_add(1u, std::memory_order_relaxed);
        }

        const auto logTrace = [&](const char *phase)
        {
            if (!traceActive || traceIndex >= 16u)
            {
                return;
            }

            const uint32_t currentNow =
                readGuestU32OrZero(rdram, 0x0024ABACu);
            const uint32_t previousNow =
                readGuestU32OrZero(rdram, 0x0024ABA8u);
            const uint32_t currentDescriptor =
                readManagerWord(currentNow, 0x100u);
            std::cerr
                << "[MOH:post-c0-display-manager-lifecycle-trace-v1]"
                << " idx=" << std::dec << traceIndex
                << " operation=" << operation
                << " phase=" << phase
                << " pc=0x" << std::hex << pcBefore
                << " ra=0x" << raBefore
                << " sp=0x" << spBefore
                << " nextPc=0x" << (ctx ? ctx->pc : 0u)
                << " curRa=0x" << (ctx ? getRegU32(ctx, 31) : 0u)
                << " curSp=0x" << (ctx ? getRegU32(ctx, 29) : 0u)
                << " curV0=0x" << (ctx ? getRegU32(ctx, 2) : 0u)
                << " managerArg=0x" << managerArg
                << " flagsArg=0x" << flagsArg
                << " current=0x" << currentBefore
                << "->0x" << currentNow
                << " previous=0x" << previousBefore
                << "->0x" << previousNow
                << " wait=0x" << waitBefore
                << "->0x"
                << readGuestU32OrZero(rdram, kMohFrameWaitFlagAddr)
                << " counter=0x" << counterBefore
                << "->0x"
                << readGuestU32OrZero(rdram, kMohFrameCounterAddr)
                << " argFrame=0x" << argFrameBefore
                << "->0x" << readManagerWord(managerArg, 0xF8u)
                << " argSwap=0x" << argSwapBefore
                << "->0x" << readManagerWord(managerArg, 0xF4u)
                << " argDescriptor=0x" << argDescriptorBefore
                << "->0x" << readManagerWord(managerArg, 0x100u)
                << " currentDescriptor=0x" << currentDescriptor
                << " firstMethod=0x"
                << readManagerWord(currentDescriptor, 0x9Cu)
                << " secondMethod=0x"
                << readManagerWord(currentDescriptor, 0xACu)
                << " currentWords=";
            if (currentNow != 0u)
            {
                logMohGuestWords(rdram, currentNow + 0xF0u, 8u);
            }
            else
            {
                std::cerr << "(null)";
            }
            std::cerr << std::dec << std::endl;
        };

        logTrace("enter");
        if (original)
        {
            original(rdram, ctx, runtime);
        }
        else if (ctx)
        {
            ctx->pc = getRegU32(ctx, 31);
        }
        logTrace("return");
    }

