    void traceMohCompC1ReadPlateauV1(
        uint8_t *rdram,
        R5900Context *ctx)
    {
        constexpr uint32_t kAsyncManagerBase = 0x0025FC80u;
        constexpr uint32_t kDvdManagerBase = 0x0025AB10u;
        constexpr uint32_t kDvdDescriptor = 0x0025AB34u;
        constexpr uint32_t kType2PendingRequest = 0x0036B0B0u;

        if (!rdram ||
            !ctx ||
            ctx->pc != 0x001A15C8u ||
            getRegU32(ctx, 31) != 0x0010A6ACu ||
            !g_mohLevelViv6_1Active.load(std::memory_order_acquire))
        {
            return;
        }

        const uint32_t table =
            readGuestU32OrZero(rdram, kMohAsyncTableBaseAddr);
        const uint32_t entry =
            readGuestU32OrZero(
                rdram,
                kAsyncManagerBase + 0x20u);
        const uint32_t handle =
            readGuestU32OrZero(rdram, entry + 0x00u);
        const uint32_t expectedEntry =
            table != 0u && handle != 0u
                ? table +
                      (((handle >> 24u) & 0xFFu) *
                       kMohAsyncEntryStride)
                : 0u;
        const uint32_t context =
            readGuestU32OrZero(rdram, entry + 0x14u);
        const uint32_t offset =
            readGuestU32OrZero(rdram, entry + 0x18u);
        const uint32_t chunk =
            readGuestU32OrZero(rdram, entry + 0x1Cu);
        const uint32_t destination =
            readGuestU32OrZero(rdram, entry + 0x20u);
        const uint32_t slot =
            readGuestU32OrZero(rdram, entry + 0x24u);
        const std::string path =
            readGuestStringLimited(rdram, slot + 0x0Cu, 128u);
        const bool compC1Art = isMohExactCompC1ArtPath(path);
        const bool compC2Art = isMohExactCompC2ArtPath(path);
        const bool compC3Art = isMohExactCompC3ArtPath(path);
        if (entry == 0u ||
            entry != expectedEntry ||
            (handle & kMohFrontendAsyncTypeMask) !=
                kMohFrontendAsyncTypeBits ||
            (!compC1Art && !compC2Art && !compC3Art))
        {
            return;
        }

        static std::atomic<uint32_t> sCompC1TraceCount{0u};
        static std::atomic<uint32_t> sCompC2TraceCount{0u};
        static std::atomic<uint32_t> sCompC3TraceCount{0u};
        std::atomic<uint32_t> &traceCount =
            compC3Art
                ? sCompC3TraceCount
                : (compC2Art
                       ? sCompC2TraceCount
                       : sCompC1TraceCount);
        const uint32_t traceIndex =
            traceCount.fetch_add(1u, std::memory_order_relaxed);
        if (traceIndex >= 8u)
        {
            return;
        }

        const uint32_t loaderObject =
            g_mohCompC0LoaderObject.load(
                std::memory_order_acquire);
        const uint32_t fileObject =
            readGuestU32OrZero(rdram, context + 0x04u);
        const uint32_t nextObject =
            readGuestU32OrZero(rdram, fileObject + 0x04u);
        const uint32_t memberSize =
            readGuestU32OrZero(rdram, slot + 0x04u);
        const uint32_t memberOffset =
            readGuestU32OrZero(rdram, slot + 0x08u);
        const uint64_t chunkHostOffset =
            static_cast<uint64_t>(memberOffset) + offset;
        const uint32_t destinationPhysical =
            destination & 0x1FFFFFFFu;
        std::filesystem::path hostPath;
        std::error_code hostError;
        const bool hostResolved =
            resolveMohHostFilePath(
                "cd:data\\6\\6_1\\comp.viv",
                hostPath) &&
            std::filesystem::is_regular_file(
                hostPath,
                hostError) &&
            !hostError;
        const uint64_t hostSize =
            hostResolved
                ? std::filesystem::file_size(
                      hostPath,
                      hostError)
                : 0u;
        const bool hostRangeExact =
            hostResolved &&
            !hostError &&
            memberSize != 0u &&
            static_cast<uint64_t>(memberOffset) +
                    memberSize <=
                hostSize &&
            chunk != 0u &&
            chunk <= 0x8000u &&
            static_cast<uint64_t>(offset) + chunk <=
                memberSize &&
            chunkHostOffset <= hostSize &&
            chunk <= hostSize - chunkHostOffset &&
            destinationPhysical < PS2_RAM_SIZE &&
            chunk <= PS2_RAM_SIZE - destinationPhysical;
        std::vector<uint8_t> hostBytes(
            hostRangeExact ? chunk : 0u);
        const bool hostRead =
            hostRangeExact &&
            readMohHostFileRange(
                hostPath,
                chunkHostOffset,
                hostBytes.data(),
                chunk);
        uint32_t firstDestinationMismatch = chunk;
        if (hostRead)
        {
            for (uint32_t byte = 0u; byte < chunk; ++byte)
            {
                if (hostBytes[byte] !=
                    rdram[destinationPhysical + byte])
                {
                    firstDestinationMismatch = byte;
                    break;
                }
            }
        }

        const uint32_t descriptorBytes =
            readGuestU32OrZero(
                rdram,
                kDvdDescriptor + 0x00u);
        const uint32_t descriptorTail =
            readGuestU32OrZero(
                rdram,
                kDvdDescriptor + 0x04u);
        const uint32_t descriptorAlignment =
            readGuestU32OrZero(
                rdram,
                kDvdDescriptor + 0x08u);
        const uint32_t descriptorLba =
            readGuestU32OrZero(
                rdram,
                kDvdDescriptor + 0x0Cu);
        const uint32_t descriptorSectors =
            readGuestU32OrZero(
                rdram,
                kDvdDescriptor + 0x10u);
        const uint32_t descriptorDestination =
            readGuestU32OrZero(
                rdram,
                kDvdDescriptor + 0x14u);
        const uint32_t dvdStaging =
            readGuestU32OrZero(
                rdram,
                kDvdManagerBase + 0x40u);
        const bool destinationOrderExact =
            descriptorDestination >= destination &&
            descriptorDestination - destination < chunk;
        const uint32_t descriptorProgress =
            destinationOrderExact
                ? descriptorDestination - destination
                : chunk;
        const bool descriptorRangeExact =
            destinationOrderExact &&
            descriptorBytes != 0u &&
            descriptorBytes <= chunk - descriptorProgress;
        const uint32_t descriptorDestinationPhysical =
            descriptorDestination & 0x1FFFFFFFu;
        const bool descriptorDestinationMatch =
            hostRead &&
            descriptorRangeExact &&
            descriptorDestinationPhysical < PS2_RAM_SIZE &&
            descriptorBytes <=
                PS2_RAM_SIZE - descriptorDestinationPhysical &&
            std::memcmp(
                hostBytes.data() + descriptorProgress,
                rdram + descriptorDestinationPhysical,
                descriptorBytes) == 0;
        const uint64_t stagingSource64 =
            static_cast<uint64_t>(dvdStaging) +
            descriptorAlignment;
        const uint32_t stagingSourcePhysical =
            static_cast<uint32_t>(stagingSource64) &
            0x1FFFFFFFu;
        const bool descriptorStagingMatch =
            hostRead &&
            descriptorRangeExact &&
            stagingSource64 <= 0xFFFFFFFFull &&
            stagingSourcePhysical < PS2_RAM_SIZE &&
            descriptorBytes <=
                PS2_RAM_SIZE - stagingSourcePhysical &&
            std::memcmp(
                hostBytes.data() + descriptorProgress,
                rdram + stagingSourcePhysical,
                descriptorBytes) == 0;

        std::cerr
            << (compC3Art
                    ? "[MOH:comp-c3-art-plateau-trace-v1]"
                    : (compC2Art
                           ? "[MOH:comp-c2-art-plateau-trace-v1]"
                           : "[MOH:comp-c1-read-plateau-trace-v1]"))
            << " idx=" << std::dec << traceIndex
            << " pc=0x" << std::hex << ctx->pc
            << " ra=0x" << getRegU32(ctx, 31)
            << " handle=0x" << handle
            << " table=0x" << table
            << " entry=0x" << entry
            << " expectedEntry=0x" << expectedEntry
            << " status=0x"
            << readGuestU32OrZero(rdram, entry + 0x08u)
            << " operation=0x"
            << readGuestU32OrZero(rdram, entry + 0x10u)
            << " context=0x" << context
            << " loaderObject=0x" << loaderObject
            << " fileObject=0x" << fileObject
            << " nextObject=0x" << nextObject
            << " offset=0x" << offset
            << " chunk=0x" << chunk
            << " destination=0x" << destination
            << " slot=0x" << slot
            << " callback=0x"
            << readGuestU32OrZero(rdram, entry + 0x28u)
            << " startFn=0x"
            << readGuestU32OrZero(rdram, entry + 0x2Cu)
            << " memberOffset=0x" << memberOffset
            << " memberSize=0x" << memberSize
            << " descriptorProgress=0x"
            << descriptorProgress
            << " descriptorBytes=0x" << descriptorBytes
            << " descriptorTail=0x" << descriptorTail
            << " descriptorAlignment=0x"
            << descriptorAlignment
            << " descriptorLba=0x" << descriptorLba
            << " descriptorSectors=0x"
            << descriptorSectors
            << " descriptorDestination=0x"
            << descriptorDestination
            << " managerCurrent=0x"
            << readGuestU32OrZero(
                   rdram,
                   kAsyncManagerBase + 0x20u)
            << " managerQueue=0x"
            << readGuestU32OrZero(
                   rdram,
                   kAsyncManagerBase + 0x2Cu)
            << " managerDepth=0x"
            << readGuestU32OrZero(
                   rdram,
                   kAsyncManagerBase + 0x10u)
            << " managerCount=0x"
            << readGuestU32OrZero(
                   rdram,
                   kAsyncManagerBase + 0x0Cu)
            << " dvdFlags=0x"
            << readGuestU32OrZero(
                   rdram,
                   kDvdManagerBase + 0x00u)
            << " dvdSema=0x"
            << readGuestU32OrZero(
                   rdram,
                   kDvdManagerBase + 0x0Cu)
            << " dvdCallback=0x"
            << readGuestU32OrZero(
                   rdram,
                   kDvdManagerBase + 0x18u)
            << " dvdComparator=0x"
            << readGuestU32OrZero(
                   rdram,
                   kDvdManagerBase + 0x1Cu)
            << " firstDestinationMismatch=0x"
            << firstDestinationMismatch
            << " path='" << path << "'"
            << " host='" << hostPath.string() << "'"
            << " hostSize=0x" << hostSize
            << std::dec
            << " contextIsLoaderObject="
            << (context == loaderObject ? 1 : 0)
            << " hostRangeExact="
            << (hostRangeExact ? 1 : 0)
            << " hostRead=" << (hostRead ? 1 : 0)
            << " destinationFullMatch="
            << (hostRead &&
                        firstDestinationMismatch == chunk
                    ? 1
                    : 0)
            << " descriptorRangeExact="
            << (descriptorRangeExact ? 1 : 0)
            << " descriptorDestinationMatch="
            << (descriptorDestinationMatch ? 1 : 0)
            << " descriptorStagingMatch="
            << (descriptorStagingMatch ? 1 : 0)
            << " entryWords=";
        logMohGuestWords(rdram, entry, 12u);
        std::cerr << " objectWords=";
        logMohGuestWords(rdram, context, 16u);
        std::cerr << " fileObjectWords=";
        logMohGuestWords(rdram, fileObject, 16u);
        std::cerr << " nextObjectWords=";
        logMohGuestWords(rdram, nextObject, 16u);
        std::cerr << " slotWords=";
        logMohGuestWords(rdram, slot, 12u);
        std::cerr << " managerWords=";
        logMohGuestWords(rdram, kAsyncManagerBase, 16u);
        std::cerr << " dvdManagerWords=";
        logMohGuestWords(rdram, kDvdManagerBase, 20u);
        std::cerr << " dvdDescriptorWords=";
        logMohGuestWords(rdram, kDvdDescriptor, 12u);
        std::cerr << " type2PendingWords=";
        logMohGuestWords(rdram, kType2PendingRequest, 6u);
        std::cerr << std::dec << std::endl;
    }

